window.AARTI_DATA = {"deities":[{"id":"ganesh","n":"Ganesh","d":"श्री गणेश","ini":"ग","c":"#C2410C","aka":["ganesh","ganesha","ganpati","ganapati","vinayak","vinayaka","vighnaharta","gajanan","lambodar","ekdant","bappa"],"akaD":["गणपति","विनायक","गजानन","बप्पा"],"about":"Lord of beginnings and remover of obstacles, so every puja begins with him. Son of Shiv and Parvati, he rides a mouse and loves modak.","img":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/64/Ganesha_Basohli_miniature_circa_1730_Dubost_p73.jpg/330px-Ganesha_Basohli_miniature_circa_1730_Dubost_p73.jpg","page":"https://commons.wikimedia.org/wiki/File:Ganesha_Basohli_miniature_circa_1730_Dubost_p73.jpg","cap":"Ganesha, Basohli miniature, c. 1730","by":"Pahari (Basohli) painter","pos":"50% 30%"},"day":3},{"id":"vishnu","n":"Vishnu","d":"श्री विष्णु","ini":"वि","c":"#1D4E89","aka":["vishnu","narayan","narayana","hari","jagdish","jagadish","satyanarayan"],"akaD":["नारायण","हरि","जगदीश"],"about":"The preserver, who takes avatars such as Ram and Krishna whenever dharma is in danger. He rests on the serpent Shesh, with Lakshmi at his feet.","img":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f3/Raja_Ravi_Varma%2C_Seshanarayana_%28Oleographic_print%29.jpg/330px-Raja_Ravi_Varma%2C_Seshanarayana_%28Oleographic_print%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Raja_Ravi_Varma%2C_Seshanarayana_%28Oleographic_print%29.jpg","cap":"Seshanarayana, oleograph","by":"Raja Ravi Varma","pos":"50% 45%"},"day":4},{"id":"shiv","n":"Shiv","d":"भगवान शिव","ini":"शि","c":"#4B5B7A","aka":["shiv","shiva","mahadev","mahadeva","bholenath","bhole","shankar","shambhu","rudra","neelkanth","omkar"],"akaD":["महादेव","भोलेनाथ","शंकर","शम्भु"],"about":"The great ascetic of Kailash, destroyer of ignorance and the kindest of gods to his devotees. The Ganga flows from his hair and the crescent moon rests on his brow.","img":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8f/A_version_from_the_Ravi_Varma_press-_%22Shankar%2C%22_c.1910%27s.jpg/330px-A_version_from_the_Ravi_Varma_press-_%22Shankar%2C%22_c.1910%27s.jpg","page":"https://commons.wikimedia.org/wiki/File:A_version_from_the_Ravi_Varma_press-_%22Shankar%2C%22_c.1910%27s.jpg","cap":"Shankar, Ravi Varma Press, c. 1910s","by":"Ravi Varma Press","pos":"50% 22%"},"day":1},{"id":"durga","n":"Durga","d":"माँ दुर्गा","ini":"दु","c":"#A3121F","aka":["durga","ambe","amba","jagdamba","mata rani","sherawali","bhavani","gauri","devi","sherowali"],"akaD":["अम्बे","जगदम्बा","शेरावाली","भवानी","माता रानी"],"about":"The Mother Goddess who rides a lion and defeated Mahishasur. Navratri, her nine nights, is one of the great festivals of the year.","img":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/63/Raja_Ravi_Varma%2C_Ambika_%28Oleographic_print%29.jpg/330px-Raja_Ravi_Varma%2C_Ambika_%28Oleographic_print%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Raja_Ravi_Varma%2C_Ambika_%28Oleographic_print%29.jpg","cap":"Ambika, oleograph","by":"Raja Ravi Varma","pos":"50% 25%"},"day":5},{"id":"lakshmi","n":"Lakshmi","d":"माँ लक्ष्मी","ini":"ल","c":"#B4235F","aka":["lakshmi","laxmi","mahalakshmi","kamla","kamala"],"akaD":["महालक्ष्मी","कमला"],"about":"Goddess of wealth, fortune and grace, consort of Vishnu. She is welcomed into every home with lamps on Diwali night.","img":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a6/Raja_Ravi_Varma%2C_Goddess_Lakshmi%2C_1896.jpg/330px-Raja_Ravi_Varma%2C_Goddess_Lakshmi%2C_1896.jpg","page":"https://commons.wikimedia.org/wiki/File:Raja_Ravi_Varma%2C_Goddess_Lakshmi%2C_1896.jpg","cap":"Goddess Lakshmi, 1896","by":"Raja Ravi Varma","pos":"50% 18%"},"day":5},{"id":"saraswati","n":"Saraswati","d":"माँ सरस्वती","ini":"स","c":"#3B6E8F","aka":["saraswati","sarasvati","sharda","sharada","vagdevi","veena vadini"],"akaD":["शारदा","वीणावादिनी","वाग्देवी"],"about":"Goddess of learning, speech and music, who holds the veena and rides a swan. Students pray to her before study, especially on Basant Panchami.","img":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Raja_Ravi_Varma%2C_Goddess_Saraswati.jpg/330px-Raja_Ravi_Varma%2C_Goddess_Saraswati.jpg","page":"https://commons.wikimedia.org/wiki/File:Raja_Ravi_Varma%2C_Goddess_Saraswati.jpg","cap":"Goddess Saraswati","by":"Raja Ravi Varma","pos":"50% 24%"}},{"id":"hanuman","n":"Hanuman","d":"श्री हनुमान","ini":"ह","c":"#D9620B","aka":["hanuman","bajrang","bajrangbali","pavanputra","pawanputra","maruti","anjaneya","sankat mochan","kesari nandan"],"akaD":["बजरंगबली","पवनपुत्र","मारुति","संकटमोचन"],"about":"Son of the wind god, devoted servant of Shri Ram, and a symbol of strength and fearlessness. He carried the mountain of herbs to save Lakshman.","img":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1b/Hanuman_fetches_the_herb-bearing_mountain%2C_in_a_print_from_the_Ravi_Varma_Press%2C_1910%27s.jpg/330px-Hanuman_fetches_the_herb-bearing_mountain%2C_in_a_print_from_the_Ravi_Varma_Press%2C_1910%27s.jpg","page":"https://commons.wikimedia.org/wiki/File:Hanuman_fetches_the_herb-bearing_mountain%2C_in_a_print_from_the_Ravi_Varma_Press%2C_1910%27s.jpg","cap":"Hanuman fetches the herb-bearing mountain, Ravi Varma Press, 1910s","by":"Ravi Varma Press","pos":"50% 28%"},"day":2},{"id":"ram","n":"Ram","d":"श्री राम","ini":"रा","c":"#24705F","aka":["ram","rama","raghunath","raghav","raghupati","siyaram","sitaram"],"akaD":["रघुनाथ","राघव","सियाराम"],"about":"The seventh avatar of Vishnu and the ideal king of the Ramayan, worshipped with Sita, Lakshman and Hanuman as the Ram Panchayatan.","img":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d1/Ramapanchayan%2C_Raja_Ravi_Varma_%28Lithograph%29.jpg/330px-Ramapanchayan%2C_Raja_Ravi_Varma_%28Lithograph%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Ramapanchayan%2C_Raja_Ravi_Varma_%28Lithograph%29.jpg","cap":"Ram Panchayatan, lithograph, before 1906","by":"Raja Ravi Varma","pos":"50% 35%"}},{"id":"krishna","n":"Krishna","d":"श्री कृष्ण","ini":"कृ","c":"#2A3A85","aka":["krishna","krishn","kanha","kanhaiya","gopal","shyam","murari","giridhar","kunj bihari","banke bihari","govind"],"akaD":["कान्हा","गोपाल","श्याम","गिरिधर","गोविन्द"],"about":"The eighth avatar of Vishnu: the butter-stealing child of Gokul, the flute player of Vrindavan, and the teacher of the Bhagavad Gita.","img":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/74/Raja_Ravi_Varma%2C_Sri_Krishna_as_Envoy.jpg/330px-Raja_Ravi_Varma%2C_Sri_Krishna_as_Envoy.jpg","page":"https://commons.wikimedia.org/wiki/File:Raja_Ravi_Varma%2C_Sri_Krishna_as_Envoy.jpg","cap":"Sri Krishna as Envoy, 1906","by":"Raja Ravi Varma","pos":"50% 18%"}},{"id":"surya","n":"Surya","d":"सूर्य देव","ini":"सू","c":"#C77A0A","aka":["surya","suryadev","sun","savitr","savita","aditya","bhaskar","dinkar"],"akaD":["सविता","आदित्य","भास्कर","दिनकर"],"about":"The Sun, the visible god, worshipped at sunrise with water offerings. The Gayatri mantra is addressed to him as Savitr, and Chhath is his great festival.","img":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6c/Surya_in_his_chariot.jpg/330px-Surya_in_his_chariot.jpg","page":"https://commons.wikimedia.org/wiki/File:Surya_in_his_chariot.jpg","cap":"Surya in his chariot, late 19th century","by":"Unknown artist","pos":"50% 40%"},"day":0},{"id":"ishvar","n":"Ishvar","d":"ईश्वर","ini":"ॐ","c":"#7A5A2E","aka":["god","bhagwan","ishwar","prayer","prarthana"],"akaD":["भगवान","प्रार्थना"],"gallery":false,"label":"Universal prayers","about":"Prayers addressed to God in any form, sung by people of every tradition."}],"kinds":[{"id":"aarti","n":"Aarti","pl":"Aartis","d":"आरती","note":"Sung while the lamp is waved before the deity."},{"id":"chalisa","n":"Chalisa","pl":"Chalisas","d":"चालीसा","note":"Forty chaupais in praise of a deity, recited daily by millions."},{"id":"stotra","n":"Stotra","pl":"Stotras and stutis","d":"स्तोत्र","note":"Hymns of praise, most in Sanskrit, including ashtakams of eight verses."},{"id":"mantra","n":"Mantra","pl":"Mantras and shlokas","d":"मंत्र","note":"Short sacred verses for daily prayer, study and japa."},{"id":"bhajan","n":"Bhajan","pl":"Bhajans","d":"भजन","note":"Devotional songs of the saint-poets: Tulsidas, Surdas, Meera, Narsinh Mehta."},{"id":"granth","n":"Granth","pl":"Granths","d":"ग्रंथ","note":"Scriptures, read chapter by chapter."}],"occasions":{"ganesh-chaturthi":{"n":"Ganesh Chaturthi","d":"गणेश चतुर्थी","aka":["ganeshotsav","ganesh utsav","vinayaka chaturthi"],"note":"Ten days of Ganeshotsav. In Maharashtra every aarti session opens with Sukhkarta Dukhharta."},"navratri":{"n":"Navratri","d":"नवरात्रि","aka":["navaratri","navratra","durga puja"],"note":"Nine nights of the Goddess. Jai Ambe Gauri is sung every morning and evening."},"dussehra":{"n":"Dussehra","d":"दशहरा","aka":["dasara","dasehra","vijayadashami"],"note":"Ram’s victory over Ravan, the day after Navratri ends."},"dhanteras":{"n":"Dhanteras","d":"धनतेरस","aka":["dhantrayodashi"],"note":"Lamps are lit at dusk and Lakshmi is worshipped for the coming year."},"diwali":{"n":"Diwali","d":"दीपावली","aka":["deepavali","divali","lakshmi puja"],"note":"Lakshmi Puja at dusk. Most homes begin with the Ganesh aarti, then Lakshmi."},"govardhan":{"n":"Govardhan Puja","d":"गोवर्धन पूजा","aka":["annakut"],"note":"Offerings to Krishna as Giridhar, who lifted Govardhan hill."},"mahashivratri":{"n":"Maha Shivratri","d":"महाशिवरात्रि","aka":["shivratri","shivaratri"],"note":"Night-long worship of Shiv."},"shravan":{"n":"Sawan month","d":"सावन","aka":["shravan","savan","sawan somvar"],"note":"Shiv’s month; Mondays are kept with special devotion."},"janmashtami":{"n":"Janmashtami","d":"जन्माष्टमी","aka":["krishna janmashtami","gokulashtami"],"note":"Krishna’s birth, celebrated at midnight."},"holi":{"n":"Holi","d":"होली","aka":[],"note":"The festival of colours, dear to Krishna’s Braj."},"ram-navami":{"n":"Ram Navami","d":"राम नवमी","aka":[],"note":"The birth of Shri Ram."},"hanuman-jayanti":{"n":"Hanuman Jayanti","d":"हनुमान जयंती","aka":["hanuman janmotsav"],"note":"Hanuman’s birth, on Chaitra Purnima in North India."},"satyanarayan":{"n":"Satyanarayan Katha","d":"सत्यनारायण कथा","aka":["satyanarayan puja"],"note":"Om Jai Jagdish Hare is the aarti of the katha."},"griha-pravesh":{"n":"Griha Pravesh","d":"गृह प्रवेश","aka":["housewarming"],"note":"Moving into a new home."},"sundarkand":{"n":"Sundarkand path","d":"सुंदरकांड पाठ","aka":["sunderkand","ramayan path"],"note":"Recitation of the Sundarkand, usually closed with Hanuman’s aarti."},"daily":{"n":"Daily aarti","d":"नित्य आरती","aka":["daily","sandhya","evening","morning"],"note":"Sung any day, morning or evening."},"closing":{"n":"Close of any aarti","d":"आरती के अंत में","aka":["closing","end"],"note":"Recited as the flame is offered at the end."},"basant-panchami":{"n":"Basant Panchami","d":"बसंत पंचमी","aka":["vasant panchami","saraswati puja"],"note":"Saraswati Puja at the start of spring. Students place their books before the goddess."},"chhath":{"n":"Chhath Puja","d":"छठ पूजा","aka":["chhath","chhathi maiya","surya shashthi"],"note":"Offerings to the setting and rising Sun, kept with great devotion in Bihar and eastern Uttar Pradesh."},"gita-jayanti":{"n":"Gita Jayanti","d":"गीता जयंती","aka":["mokshada ekadashi"],"note":"The day Krishna taught the Gita to Arjun, on Margashirsha Shukla Ekadashi."},"morning":{"n":"Morning prayer","d":"प्रातः प्रार्थना","aka":["morning","prabhat","subah"],"note":"Short prayers for the start of the day or before study."},"meals":{"n":"Before meals","d":"भोजन से पहले","aka":["bhojan mantra","food"],"note":"Recited before eating, offering the food first."}},"occOrder":["daily","morning","closing","navratri","dussehra","dhanteras","diwali","govardhan","chhath","ganesh-chaturthi","basant-panchami","mahashivratri","shravan","janmashtami","holi","ram-navami","hanuman-jayanti","gita-jayanti","satyanarayan","sundarkand","griha-pravesh","meals"],"weekdays":[{"n":"Sunday","d":"रविवार","who":"Surya Dev","ids":["gayatri-mantra","om-jai-jagdish-hare"],"note":"Many offer water to the rising sun and recite the Gayatri mantra."},{"n":"Monday","d":"सोमवार","who":"Shiv ji","ids":["om-jai-shiv-omkara","shiv-rudrashtakam","karpur-gauram","mahamrityunjaya-mantra"]},{"n":"Tuesday","d":"मंगलवार","who":"Hanuman ji","ids":["hanuman-chalisa","aarti-keejai-hanuman-lala-ki","shri-ramchandra-kripalu"],"note":"Many homes also worship Durga on Tuesdays."},{"n":"Wednesday","d":"बुधवार","who":"Ganesh ji","ids":["jai-ganesh-deva","sukhkarta-dukhharta","vakratunda-mahakaya"]},{"n":"Thursday","d":"गुरुवार","who":"Vishnu ji","ids":["om-jai-jagdish-hare","vaishnav-jan-to"]},{"n":"Friday","d":"शुक्रवार","who":"Lakshmi Mata","ids":["om-jai-lakshmi-mata","jai-ambe-gauri"],"note":"Durga and Santoshi Mata are also worshipped on Fridays."},{"n":"Saturday","d":"शनिवार","who":"Shani Dev and Hanuman ji","ids":["hanuman-chalisa","aarti-keejai-hanuman-lala-ki"],"note":"There’s no Shani aarti in the collection yet."}],"fests":[{"date":"2026-10-11","len":9,"occ":"navratri","label":"Sharad Navratri"},{"date":"2026-10-20","occ":"dussehra"},{"date":"2026-11-06","occ":"dhanteras"},{"date":"2026-11-08","occ":"diwali","label":"Diwali · Lakshmi Puja"},{"date":"2026-11-15","occ":"chhath","label":"Chhath Puja, evening arghya"}],"presets":[{"n":"Daily evening aarti","ids":["jai-ganesh-deva","om-jai-jagdish-hare","karpur-gauram"]},{"n":"Morning prayers","ids":["gayatri-mantra","vakratunda-mahakaya","saraswati-vandana","tvameva-mata"]},{"n":"Diwali Lakshmi Puja","ids":["jai-ganesh-deva","om-jai-lakshmi-mata","om-jai-jagdish-hare","karpur-gauram"]},{"n":"Navratri","ids":["jai-ganesh-deva","durga-chalisa","jai-ambe-gauri","karpur-gauram"]},{"n":"Monday, for Shiv ji","ids":["jai-ganesh-deva","shiv-rudrashtakam","om-jai-shiv-omkara","karpur-gauram"]},{"n":"Tuesday, for Hanuman ji","ids":["hanuman-chalisa","aarti-keejai-hanuman-lala-ki","shri-ramchandra-kripalu"]}],"navratri":{"occ":"navratri","d":"शारदीय नवरात्रि","n":"Sharad Navratri","tag":"Nine nights of the Goddess","about":["Navratri means “nine nights”. Sharad Navratri, the autumn one, begins on the first day of the bright half of Ashvin and is the greatest of the four Navratris in the year; Chaitra Navratri in spring ends on Ram Navami, and the two Gupta Navratris of Magh and Ashadh are kept quietly by those who know them.","For nine nights the Goddess is worshipped in nine forms, the Navdurga, one each night, from Shailputri, daughter of the mountain, to Siddhidatri, giver of perfection. The Durga Saptashati tells why: the gods, helpless before Mahishasur and later Shumbh and Nishumbh, poured their power into one Goddess, and she fought and won. The tenth day, Vijayadashami or Dussehra, celebrates her victory and Ram’s victory over Ravan, whom he fought after worshipping the Goddess."],"customs":[{"n":"Ghatasthapana","d":"घटस्थापना","t":"On the first morning a kalash of water, crowned with mango leaves and a coconut, is set up as the seat of the Goddess, often beside a bed of soil sown with barley (jau or jawara) that sprouts through the nine days. Many homes keep an akhand jyoti, a lamp that is not allowed to go out until Navami."},{"n":"Path and aarti","d":"पाठ और आरती","t":"Morning and evening, families sing the Durga aarti and recite the Durga Chalisa, and those who can read the Durga Saptashati, either whole each day or divided across the nine days."},{"n":"Vrat","d":"व्रत","t":"Many fast through the nine days or on the first and last, eating fruit, milk, and dishes of kuttu, singhara, sabudana and samak rice, without grain, onion or garlic. Others fast only on Ashtami."},{"n":"Kanya pujan","d":"कन्या पूजन","t":"On Ashtami or Navami, nine young girls, seen as forms of the Goddess, and often one boy as Langur (Bhairav), are invited home, their feet washed, and they are fed halwa, puri and black chana and given gifts."},{"n":"Across India","d":"देश भर में","t":"Bengal celebrates Durga Puja from Shashthi to Dashami in pandals, with Sandhi Puja at the meeting of Ashtami and Navami. Gujarat dances garba and dandiya every night. Tamil Nadu, Karnataka and Andhra set out golu, steps of dolls. Kerala and the South keep Saraswati and Ayudha Puja on Navami, and children begin their learning on Vijayadashami. Mysuru and Kullu hold their famous Dasara processions."}],"days":[{"n":1,"tithi":"Pratipada","td":"प्रतिपदा","g":"Shailputri","gd":"शैलपुत्री","means":"Daughter of the mountain","about":"Sati, born again as the daughter of Himavan, king of the mountains, after giving up her life at her father Daksh’s sacrifice. As Parvati she would once more become Shiv’s wife. She is worshipped on the first day, together with the kalash.","look":"Rides the bull Nandi, holds a trident in her right hand and a lotus in her left, with a crescent moon on her brow.","offer":"Pure ghee is commonly offered on the first day.","read":[{"id":"navdurga-dhyan","v":1,"why":"Her meditation verse"},{"id":"durga-chalisa","why":"Recited every day of Navratri"},{"id":"jai-ambe-gauri","why":"The evening aarti"},{"id":"ya-devi-sarvabhuteshu","why":"To begin the nine nights"}]},{"n":2,"tithi":"Dwitiya","td":"द्वितीया","g":"Brahmacharini","gd":"ब्रह्मचारिणी","means":"She who practises austerity","about":"Parvati as the young ascetic who undertook years of fierce tapas, living on leaves and then on nothing at all, to win Shiv as her husband. She stands for steadfastness and devotion that does not give up.","look":"Walks barefoot in white, holding a japa mala in her right hand and a kamandalu, a water-pot, in her left.","offer":"Sugar is commonly offered.","read":[{"id":"navdurga-dhyan","v":2,"why":"Her meditation verse"},{"id":"bhavani-ashtakam","why":"A prayer of complete surrender"},{"id":"durga-chalisa","why":"The daily chalisa"},{"id":"jai-ambe-gauri","why":"The evening aarti"}]},{"n":3,"tithi":"Tritiya","td":"तृतीया","g":"Chandraghanta","gd":"चन्द्रघण्टा","means":"She who wears a bell-shaped moon","about":"Parvati as Shiv’s bride, a half-moon shaped like a bell on her forehead. The sound of her bell drives away demons and fear, and brings her devotees courage and peace.","look":"Golden in colour, with ten arms bearing weapons, riding a lion, ready for battle yet calm.","offer":"Milk, or kheer made with milk, is commonly offered.","read":[{"id":"navdurga-dhyan","v":3,"why":"Her meditation verse"},{"id":"durga-saptashati","ch":4,"at":"४.२४","why":"The Shakradi Stuti, where the gods ask her bell to protect them"},{"id":"durga-chalisa","why":"The daily chalisa"},{"id":"jai-ambe-gauri","why":"The evening aarti"}]},{"n":4,"tithi":"Chaturthi","td":"चतुर्थी","g":"Kushmanda","gd":"कूष्माण्डा","means":"She whose warmth holds the cosmic egg","about":"When there was only darkness, she created the universe with a gentle smile. She lives in the core of the sun and gives it its light and energy.","look":"Eight-armed (Ashtabhuja), holding a kamandalu, bow, arrow, lotus, a pot of nectar, discus, mace and japa mala, riding a lion.","offer":"Malpua is commonly offered.","read":[{"id":"navdurga-dhyan","v":4,"why":"Her meditation verse"},{"id":"durga-saptashati","ch":5,"why":"Ya Devi Sarvabhuteshu: the Goddess present in every being"},{"id":"durga-chalisa","why":"The daily chalisa"},{"id":"jai-ambe-gauri","why":"The evening aarti"}]},{"n":5,"tithi":"Panchami","td":"पञ्चमी","g":"Skandamata","gd":"स्कन्दमाता","means":"Mother of Skanda","about":"The mother of Skanda, also called Kartikeya, the commander of the gods’ army. Worshipping her, it is said, brings the grace of her son too.","look":"Seated on a lotus, which is why she is also called Padmasana, with the child Skanda on her lap; four-armed, holding lotuses, and riding a lion.","offer":"Bananas are commonly offered.","read":[{"id":"navdurga-dhyan","v":5,"why":"Her meditation verse"},{"id":"jai-jai-giribarraj-kishori","why":"Sita’s prayer to the mother of Ganesh and six-faced Skanda"},{"id":"durga-chalisa","why":"The daily chalisa"},{"id":"jai-ambe-gauri","why":"The evening aarti"}]},{"n":6,"tithi":"Shashthi","td":"षष्ठी","g":"Katyayani","gd":"कात्यायनी","means":"Daughter of the sage Katyayan","about":"Born in the hermitage of the sage Katyayan, she is the warrior form who slew Mahishasur. The gopis of Braj worshipped her for a month to win Krishna as their beloved. In Bengal, Durga Puja begins on this day.","look":"Four-armed, holding a sword and a lotus, the other hands raised in blessing and reassurance, riding a lion.","offer":"Honey is commonly offered.","read":[{"id":"navdurga-dhyan","v":6,"why":"Her meditation verse"},{"id":"durga-saptashati","ch":11,"why":"The gods praise Katyayani as Narayani"},{"id":"sarva-mangala-mangalye","why":"The best-known verse of the Narayani Stuti"},{"id":"jai-ambe-gauri","why":"The evening aarti"}]},{"n":7,"tithi":"Saptami","td":"सप्तमी","g":"Kalaratri","gd":"कालरात्रि","means":"The dark night of time","about":"The fiercest of the nine, the night that swallows all darkness. She destroyed Raktabeej and every evil force. Though terrifying to see, she always brings good to her devotees, so she is also called Shubhankari.","look":"Dark as night, hair loose, a necklace flashing like lightning, three eyes and fire on her breath; four-armed with a sword and an iron hook, riding a donkey.","offer":"Jaggery is commonly offered.","read":[{"id":"navdurga-dhyan","v":7,"why":"Her meditation verse"},{"id":"durga-chalisa","why":"The chalisa, which sings of her terrible Kalika form"},{"id":"durge-durghat-bhari","why":"An aarti to the slayer of Mahishasur"},{"id":"jai-ambe-gauri","why":"The evening aarti"}]},{"n":8,"tithi":"Ashtami","td":"अष्टमी","g":"Mahagauri","gd":"महागौरी","means":"The radiantly fair one","about":"After Parvati’s long austerities her body had grown dark with dust; Shiv washed her with the waters of the Ganga and she shone white as jasmine and the moon. Durga Ashtami, with kanya pujan and havan in many homes, falls on this day.","look":"Dressed all in white, riding a white bull, four-armed, with a trident and a damru.","offer":"Coconut is commonly offered.","read":[{"id":"navdurga-dhyan","v":8,"why":"Her meditation verse"},{"id":"jai-jai-giribarraj-kishori","why":"Sita’s prayer to Gauri"},{"id":"sarva-mangala-mangalye","why":"Said at kanya pujan and the havan"},{"id":"jai-ambe-gauri","why":"The evening aarti"}]},{"n":9,"tithi":"Navami","td":"नवमी","g":"Siddhidatri","gd":"सिद्धिदात्री","means":"Giver of perfection","about":"She grants every siddhi, every spiritual power and attainment. By her grace, it is said, half of Shiv’s body became the Goddess, and he became Ardhanarishvar. On Navami Navratri closes with kanya pujan, havan and, in the South, Ayudha and Saraswati Puja.","look":"Seated on a lotus, four-armed with a discus, conch, mace and lotus, attended by siddhas, gandharvas and gods.","offer":"Sesame seeds, or halwa, puri and chana for the girls of kanya pujan, are commonly offered.","read":[{"id":"navdurga-dhyan","v":9,"why":"Her meditation verse"},{"id":"durga-saptashati","ch":11,"why":"The Narayani Stuti, to close the path"},{"id":"durga-chalisa","why":"The daily chalisa"},{"id":"jai-ambe-gauri","why":"The evening aarti"},{"id":"karpur-gauram","why":"To close the aarti"}]}],"after":{"occ":"dussehra","t":"Vijayadashami: the Goddess’s victory over Mahishasur and Ram’s over Ravan. The kalash is moved, the sprouted barley is shared as a blessing, and in Bengal the images are taken for visarjan."}},"texts":[{"id":"aarti-keejai-hanuman-lala-ki","kind":"aarti","deity":"hanuman","lang":"hi","language":"Hindi","region":"North India","title":{"d":"आरती कीजै हनुमान लला की","r":"Aarti Keejai Hanuman Lala Ki","en":"Aarti of Shri Hanuman"},"auth":{"t":"Traditional. Some versions close with a line naming Tulsidas.","c":"traditional"},"occ":["hanuman-jayanti","sundarkand","daily"],"when":"Sung on Tuesdays and Saturdays, on Hanuman Jayanti, and after Hanuman Chalisa or a Sundarkand path.","dialect":"Awadhi","notes":"The order of the couplets varies between editions.","refrain":{"d":"आरती कीजै हनुमान लला की।\nदुष्ट दलन रघुनाथ कला की॥","r":"Aarti keejai Hanuman Lala ki,\nDusht dalan Raghunath kala ki.","m":"Offer the aarti to beloved Hanuman, crusher of the wicked, a living ray of Raghunath’s power.","h":"प्यारे हनुमान की आरती कीजिए, जो दुष्टों का दलन करते हैं और श्री रघुनाथ की शक्ति के अंश हैं।"},"refrainFirst":true,"verses":[{"d":"जाके बल से गिरिवर काँपे।\nरोग दोष जाके निकट न झाँके॥","r":"Jake bal se girivar kaanpe,\nRog dosh jake nikat na jhaanke.","m":"At his strength even great mountains tremble; disease and misfortune dare not come near him.","h":"जिनके बल से बड़े-बड़े पर्वत काँप उठते हैं; रोग और दोष उनके पास भी नहीं फटकते।"},{"d":"अंजनि पुत्र महा बलदायी।\nसन्तन के प्रभु सदा सहाई॥","r":"Anjani putra maha baldayi,\nSantan ke prabhu sada sahai.","m":"Son of Anjani, giver of great strength, the lord who always helps the good.","h":"अंजनी के पुत्र, महान बल देने वाले, संतों के स्वामी और सदा सहायता करने वाले।"},{"d":"दे बीरा रघुनाथ पठाए।\nलंका जारि सिया सुधि लाए॥","r":"De beera Raghunath pathaye,\nLanka jaari Siya sudhi laye.","m":"Raghunath handed him the betel-leaf token and sent him forth; he burned Lanka and brought back news of Sita.","h":"श्री रघुनाथ ने उन्हें बीड़ा देकर भेजा; उन्होंने लंका जलाकर सीताजी का समाचार लाया।"},{"d":"लंका सो कोट समुद्र सी खाई।\nजात पवनसुत बार न लाई॥","r":"Lanka so kot samudra si khai,\nJaat Pavansut baar na lai.","m":"Lanka was a fortress with the ocean for a moat, yet the son of the Wind crossed it without a moment’s delay.","h":"लंका जैसा किला और समुद्र जैसी खाई थी, फिर भी पवनपुत्र को उसे पार करने में देर नहीं लगी।"},{"d":"लंका जारि असुर संहारे।\nसियारामजी के काज सँवारे॥","r":"Lanka jaari asur sanhaare,\nSiyaramji ke kaaj sanvaare.","m":"He set Lanka ablaze, destroyed the demons and accomplished the work of Sita and Ram.","h":"उन्होंने लंका जलाकर असुरों का संहार किया और सीता-राम जी के काम सँवारे।"},{"d":"लक्ष्मण मूर्छित पड़े सकारे।\nआनि संजीवन प्राण उबारे॥","r":"Lakshman moorchhit pade sakare,\nAani sanjivan praan ubaare.","m":"When Lakshman lay unconscious, he brought the life-giving herb by dawn and saved his life.","h":"जब लक्ष्मण मूर्छित पड़े थे, तब वे सवेरा होने से पहले संजीवनी लाए और उनके प्राण बचाए।"},{"d":"पैठि पाताल तोरि जम कारे।\nअहिरावण की भुजा उखारे॥","r":"Paithi patal tori jam kaare,\nAhiravan ki bhuja ukhaare.","m":"He entered the netherworld, broke through its deadly defences and tore off Ahiravan’s arms.","h":"उन्होंने पाताल में घुसकर यमराज जैसे पहरेदारों को तोड़ा और अहिरावण की भुजाएँ उखाड़ दीं।"},{"d":"बाएँ भुजा असुर दल मारे।\nदाहिने भुजा सन्तजन तारे॥","r":"Baayen bhuja asur dal maare,\nDahine bhuja santjan taare.","m":"With his left arm he struck down the demon armies; with his right he rescued the good.","h":"बाईं भुजा से उन्होंने असुरों के दल मारे और दाईं भुजा से संतजनों को तारा।"},{"d":"सुर नर मुनि आरती उतारें।\nजय जय जय हनुमान उचारें॥","r":"Sur nar muni aarti utaaren,\nJai jai jai Hanuman uchaaren.","m":"Gods, humans and sages wave the aarti to him, calling out “Victory, victory, victory to Hanuman!”","h":"देवता, मनुष्य और मुनि उनकी आरती उतारते हैं और “जय जय जय हनुमान” बोलते हैं।"},{"d":"कंचन थार कपूर लौ छाई।\nआरती करत अंजना माई॥","r":"Kanchan thaar kapoor lau chhai,\nAarti karat Anjana maai.","m":"With the camphor flame glowing on a golden plate, Mother Anjana herself performs his aarti.","h":"सोने की थाली में कपूर की लौ जल रही है और माता अंजना स्वयं उनकी आरती कर रही हैं।"},{"d":"जो हनुमानजी की आरती गावे।\nबसि बैकुण्ठ परमपद पावे॥","r":"Jo Hanumanji ki aarti gaave,\nBasi Baikunth parampad paave.","m":"Whoever sings Hanuman’s aarti dwells in Vaikunth and attains the highest state.","h":"जो हनुमानजी की आरती गाता है, वह बैकुण्ठ में निवास करके परमपद पाता है।"}]},{"id":"aarti-kunj-bihari-ki","kind":"aarti","deity":"krishna","lang":"hi","language":"Hindi","region":"North India, especially Braj","title":{"d":"आरती कुंजबिहारी की","r":"Aarti Kunj Bihari Ki","en":"Aarti of Shri Krishna"},"auth":{"t":"Traditional","c":"traditional"},"occ":["janmashtami","govardhan","holi","daily"],"when":"The best-known Krishna aarti, sung on Janmashtami, at Braj festivals and in daily worship. “Giridhar” recalls Krishna lifting Govardhan hill, so it is also sung on Govardhan Puja.","dialect":"Braj Bhasha","notes":"Each stanza runs straight into “श्री गिरिधर कृष्णमुरारी की”. Wording varies, for example “टेर सुन दीन दुखारी की” or “दीन भिखारी की”.","refrain":{"d":"आरती कुंजबिहारी की,\nश्री गिरिधर कृष्णमुरारी की॥","r":"Aarti Kunj Bihari ki,\nShri Giridhar Krishna Murari ki.","m":"The aarti of Kunj Bihari, who roams the groves of Vrindavan: of Shri Giridhar, Krishna, Murari.","h":"वृन्दावन के कुंजों में विहार करने वाले, गोवर्धन धारण करने वाले श्रीकृष्ण मुरारी की आरती।"},"refrainFirst":true,"verses":[{"d":"गले में बैजंती माला, बजावै मुरली मधुर बाला।\nश्रवण में कुण्डल झलकाला, नंद के आनंद नंदलाला।\nगगन सम अंग कांति काली, राधिका चमक रही आली।\nलतन में ठाढ़े बनमाली; भ्रमर सी अलक, कस्तूरी तिलक,\nचंद्र सी झलक; ललित छवि श्यामा प्यारी की॥","r":"Gale mein Baijanti mala, bajavai murli madhur bala,\nShravan mein kundal jhalkala, Nand ke anand Nandlala.\nGagan sam ang kanti kali, Radhika chamak rahi aali,\nLatan mein thaadhe Banmali; bhramar si alak, kasturi tilak,\nChandra si jhalak; lalit chhavi Shyama pyari ki.","m":"He wears the Vaijayanti garland and plays his flute sweetly; earrings glitter in his ears, Nandlal, the joy of Nand. His body is dark as the sky and Radha shines beside him; he stands among the creepers with curls like black bees, a musk tilak and a moon-like glow — the lovely beauty of Shyama’s beloved.","h":"उनके गले में वैजयन्ती माला है और वे मधुर मुरली बजाते हैं; कानों में कुण्डल झलकते हैं, वे नन्द के आनन्द नन्दलाल हैं। आकाश जैसा साँवला शरीर है और साथ में राधिका चमक रही हैं; वे लताओं के बीच खड़े वनमाली हैं, भौंरों जैसी लटें, कस्तूरी का तिलक और चन्द्रमा जैसी आभा है। यह श्यामा (राधा) के प्रिय की ललित छवि है।"},{"d":"कनकमय मोर मुकुट बिलसै, देवता दरसन को तरसैं।\nगगन सों सुमन रासि बरसै;\nबजे मुरचंग, मधुर मिरदंग, ग्वालिन संग;\nअतुल रति गोप कुमारी की॥","r":"Kanakmay mor mukut bilsai, devta darsan ko tarsain,\nGagan son suman raasi barsai;\nBaje murchang, madhur mirdang, gwalin sang;\nAtul rati gop kumari ki.","m":"A golden peacock-feather crown gleams; the gods long for a glimpse of him and flowers rain from the sky. The murchang and mridang play sweetly among the cowherd girls, whose love for him has no equal.","h":"सोने का मोर-मुकुट चमक रहा है; देवता उनके दर्शन को तरसते हैं और आकाश से फूलों की वर्षा होती है। ग्वालिनों के साथ मुरचंग और मधुर मृदंग बज रहे हैं; गोप-कुमारियों का उनसे अतुलनीय प्रेम है।"},{"d":"जहां ते प्रकट भई गंगा, कलुष कलि हारिणि श्रीगंगा।\nस्मरन ते होत मोह भंगा;\nबसी शिव सीस, जटा के बीच, हरै अघ कीच;\nचरन छवि श्रीबनवारी की॥","r":"Jahan te pragat bhai Ganga, kalush kali harini Shri Ganga,\nSmaran te hot moh bhanga;\nBasi Shiv sees, jata ke beech, harai agh keech;\nCharan chhavi Shri Banwari ki.","m":"The beauty of Banwari’s feet, from which the Ganga flowed: Shri Ganga, who washes away the impurity of this age, whose remembrance breaks delusion, who lives in Shiv’s matted hair and cleanses the mire of sin.","h":"यह श्री बनवारी के चरणों की छवि है, जिनसे गंगा प्रकट हुईं: वे श्रीगंगा जो कलियुग के पाप हरती हैं, जिनके स्मरण से मोह टूट जाता है, जो शिवजी की जटाओं में बसती हैं और पाप का कीचड़ धो देती हैं।"},{"d":"चमकती उज्ज्वल तट रेनू, बज रही वृंदावन बेनू।\nचहुं दिसि गोपि ग्वाल धेनू;\nहंसत मृदु मंद, चांदनी चंद, कटत भव फंद;\nटेर सुन दीन दुखारी की॥","r":"Chamakti ujjwal tat renu, baj rahi Vrindavan benu,\nChahun disi gopi gwal dhenu;\nHansat mridu mand, chandni chand, katat bhav phand;\nTer sun deen dukhari ki.","m":"The bright sand of the riverbank glitters and the flute sounds through Vrindavan, with gopis, cowherds and cows all around. He smiles softly, like moonlight, cutting the bonds of worldly life, and hears the call of the humble and suffering.","h":"यमुना तट की उजली रेत चमक रही है, वृन्दावन में बाँसुरी बज रही है, चारों ओर गोपियाँ, ग्वाले और गायें हैं। वे चाँदनी जैसी कोमल मुस्कान से संसार के बन्धन काटते हैं और दीन-दुखियों की पुकार सुनते हैं।"}]},{"id":"durge-durghat-bhari","kind":"aarti","deity":"durga","lang":"mr","language":"Marathi","region":"Maharashtra","title":{"d":"दुर्गे दुर्घट भारी","r":"Durge Durghat Bhari","en":"Marathi aarti of Maa Durga"},"auth":{"t":"Usually credited to Samarth Ramdas, 17th century, though the last verse names “नरहरि”","c":"attributed"},"occ":["navratri","dussehra","daily"],"when":"The Durga aarti of Maharashtrian homes, sung every evening of Navratri and at the ghat (kalash) worship, usually after Sukhkarta Dukhharta.","notes":"The refrain follows each verse. Its second line is printed both as “सुरवर ईश्वर वरदे” and “सुरवर ईश्वरवरदे”. Which poet wrote it is debated: many aarti books credit Samarth Ramdas, others read “नरहरि” in the last line as the poet’s own name.","refrain":{"d":"जय देवी जय देवी महिषासुरमथनी।\nसुरवर ईश्वर वरदे तारक संजीवनी॥","r":"Jai Devi jai Devi Mahishasuramathani,\nSurvar Ishwar varade tarak sanjivani.","m":"Glory, Goddess, glory to you who crushed Mahishasur! You grant boons to the great gods and to Shiv; you carry us across and give us new life.","h":"हे देवी, आपकी जय हो, महिषासुर का मर्दन करने वाली देवी, आपकी जय हो! आप श्रेष्ठ देवताओं और शिव को भी वर देती हैं, संसार से तारने वाली और जीवन देने वाली हैं।"},"refrainFirst":false,"verses":[{"d":"दुर्गे दुर्घट भारी तुजविण संसारी।\nअनाथनाथे अंबे करुणा विस्तारी।\nवारी वारी जन्ममरणांते वारी।\nहारी पडलो आता संकट निवारी॥","r":"Durge durghat bhari tujvin sansari,\nAnathnathe Ambe karuna vistari.\nVari vari janmamarananté vari,\nHari padlo aata sankat nivari.","m":"Durga, without you this worldly life is too hard to bear. Mother Ambe, protector of the helpless, spread your compassion over me. Turn away, turn away the round of birth and death. I am beaten now: take this trouble from me.","h":"हे दुर्गा, आपके बिना यह संसार बहुत कठिन है। हे अनाथों की नाथ अम्बे, अपनी करुणा फैलाइए। मेरे जन्म-मरण के चक्र को दूर कीजिए, दूर कीजिए। मैं अब हार गया हूँ, मेरा संकट दूर कीजिए।"},{"d":"त्रिभुवनभुवनी पाहता तुजऐसी नाही।\nचारी श्रमले परंतु न बोलवे काही।\nसाही विवाद करिता पडिले प्रवाही।\nते तू भक्तालागी पावसी लवलाही॥","r":"Tribhuvanbhuvani pahata tujaisi nahi,\nChari shramale parantu na bolave kahi.\nSahi vivad karita padile pravahi,\nTe tu bhaktalagi pavasi lavlahi.","m":"Search all three worlds and there is none like you. The four Vedas tired themselves out and still could not describe you; the six schools of philosophy argued and were swept away. Yet you, Mother, come at once to your devotees.","h":"तीनों लोकों में देखने पर भी आप जैसी कोई नहीं है। चारों वेद थक गए पर आपका वर्णन नहीं कर सके; छहों दर्शन विवाद करते-करते बह गए। फिर भी आप भक्तों के लिए तुरन्त प्रकट हो जाती हैं।"},{"d":"प्रसन्नवदने प्रसन्न होसी निजदासा।\nक्लेशापासुनि सोडवी तोडी भवपाशा।\nअंबे तुजवाचून कोण पुरविल आशा।\nनरहरि तल्लिन झाला पदपंकजलेशा॥","r":"Prasannavadane prasanna hosi nijadasa,\nKleshapasuni sodavi todi bhavapasha.\nAmbe tujvachun kon puravil aasha,\nNarhari tallin jhala padpankajlesha.","m":"Goddess of the smiling face, you are pleased with your own servant: free him from suffering and cut the noose of worldly life. Mother Ambe, who but you will fulfil my hopes? Narahari is lost in devotion to the dust of your lotus feet.","h":"हे प्रसन्न मुख वाली देवी, आप अपने दास पर प्रसन्न होती हैं; उसे कष्टों से छुड़ाइए और संसार के बन्धन तोड़ दीजिए। हे अम्बे, आपके बिना मेरी आशा कौन पूरी करेगा? नरहरि आपके चरण-कमलों की धूल में लीन हो गया है।"}]},{"id":"jai-ambe-gauri","kind":"aarti","deity":"durga","lang":"hi","language":"Hindi","region":"North and West India","title":{"d":"जय अम्बे गौरी","r":"Jai Ambe Gauri","en":"Aarti of Maa Durga"},"auth":{"t":"Traditional. The closing verse names Swami Shivanand.","c":"attributed"},"occ":["navratri","dussehra","daily"],"when":"The central aarti of Navratri across North India, sung morning and evening through the nine nights, and on Tuesdays and Fridays.","notes":"Wording varies between editions: “हरि ब्रह्मा शिवरी” or “शिवजी” in the refrain, and the four-arms line appears with either “वरमुद्रा धारी” or “खड्ग खप्पर धारी”.","refrain":{"d":"जय अम्बे गौरी, मैया जय श्यामा गौरी।\nतुमको निशदिन ध्यावत, हरि ब्रह्मा शिवरी॥","r":"Jai Ambe Gauri, Maiya jai Shyama Gauri,\nTumko nishdin dhyavat, Hari Brahma Shivri.","m":"Glory to Mother Ambe, to Gauri, to Shyama! Vishnu, Brahma and Shiv meditate on you day and night.","h":"हे अम्बे गौरी, हे श्यामा गौरी, आपकी जय हो! विष्णु, ब्रह्मा और शिव दिन-रात आपका ध्यान करते हैं।"},"refrainFirst":true,"verses":[{"d":"माँग सिन्दूर विराजत, टीको मृगमद को।\nउज्ज्वल से दोउ नैना, चन्द्रवदन नीको॥","r":"Maang sindoor virajat, teeko mrigmad ko,\nUjjwal se dou naina, chandravadan neeko.","m":"Vermilion graces the parting of your hair, with a tilak of musk; your eyes are bright and your face is lovely as the moon.","h":"आपकी माँग में सिन्दूर और माथे पर कस्तूरी का टीका शोभा पा रहा है; आपके दोनों नेत्र उज्ज्वल हैं और मुख चन्द्रमा जैसा सुन्दर है।"},{"d":"कनक समान कलेवर, रक्ताम्बर राजै।\nरक्तपुष्प गल माला, कण्ठन पर साजै॥","r":"Kanak samaan kalevar, raktambar raajai,\nRaktapushp gal mala, kanthan par saajai.","m":"Your form shines like gold, dressed in red, and a garland of red flowers adorns your neck.","h":"आपका शरीर सोने जैसा चमकता है और आप लाल वस्त्र धारण करती हैं; गले में लाल फूलों की माला शोभा देती है।"},{"d":"केहरि वाहन राजत, खड्ग खप्पर धारी।\nसुर नर मुनि जन सेवत, तिनके दुखहारी॥","r":"Kehari vahan raajat, khadg khappar dhari,\nSur nar muni jan sevat, tinke dukhhari.","m":"You ride the lion, holding sword and skull-bowl. Gods, humans and sages serve you, and you take away their sorrows.","h":"आप सिंह की सवारी करती हैं और खड्ग तथा खप्पर धारण करती हैं। देवता, मनुष्य और मुनि आपकी सेवा करते हैं और आप उनके दुःख हरती हैं।"},{"d":"कानन कुण्डल शोभित, नासाग्रे मोती।\nकोटिक चन्द्र दिवाकर, सम राजत ज्योती॥","r":"Kaanan kundal shobhit, nasagre moti,\nKotik chandra divakar, sam raajat jyoti.","m":"Earrings shine in your ears and a pearl at your nose; your radiance equals millions of moons and suns.","h":"कानों में कुण्डल और नाक में मोती शोभा पाते हैं; आपकी ज्योति करोड़ों चन्द्रमा और सूर्य के समान है।"},{"d":"शुम्भ निशुम्भ बिदारे, महिषासुर घाती।\nधूम्र विलोचन नैना, निशदिन मदमाती॥","r":"Shumbh Nishumbh bidaare, Mahishasur ghaati,\nDhoomra vilochan naina, nishdin madmaati.","m":"You tore apart Shumbh and Nishumbh and slew Mahishasur; you struck down Dhumralochan, your eyes ablaze with divine fervour day and night.","h":"आपने शुम्भ-निशुम्भ को चीर डाला और महिषासुर का वध किया; धूम्रलोचन को मारा, आपके नेत्र दिन-रात दिव्य मद से भरे रहते हैं।"},{"d":"चण्ड मुण्ड संहारे, शोणित बीज हरे।\nमधु कैटभ दोउ मारे, सुर भयहीन करे॥","r":"Chand Mund sanhaare, shonit beej hare,\nMadhu Kaitabh dou maare, sur bhayheen kare.","m":"You destroyed Chand and Mund and vanquished Raktabeej; you slew Madhu and Kaitabh and freed the gods from fear.","h":"आपने चण्ड-मुण्ड का संहार किया और रक्तबीज को मारा; मधु और कैटभ दोनों को मारकर देवताओं को भयमुक्त किया।"},{"d":"ब्रह्माणी रुद्राणी, तुम कमला रानी।\nआगम निगम बखानी, तुम शिव पटरानी॥","r":"Brahmani Rudrani, tum Kamla Rani,\nAagam nigam bakhani, tum Shiv patrani.","m":"You are Brahmani and Rudrani, and Queen Kamala; the scriptures sing your praise, chief queen of Shiv.","h":"आप ही ब्रह्माणी, रुद्राणी और कमला रानी हैं; वेद और शास्त्र आपका बखान करते हैं, आप शिवजी की पटरानी हैं।"},{"d":"चौंसठ योगिनी मंगल गावत, नृत्य करत भैरों।\nबाजत ताल मृदंगा, अरु बाजत डमरू॥","r":"Chaunsath yogini mangal gaavat, nritya karat Bhairon,\nBaajat taal mridanga, aru baajat damru.","m":"The sixty-four yoginis sing auspicious songs and Bhairav dances; cymbals and drums resound, and the damru too.","h":"चौंसठ योगिनियाँ मंगल गीत गाती हैं और भैरव नृत्य करते हैं; ताल, मृदंग और डमरू बजते हैं।"},{"d":"तुम ही जग की माता, तुम ही हो भरता।\nभक्तन की दुख हरता, सुख सम्पति करता॥","r":"Tum hi jag ki mata, tum hi ho bharta,\nBhaktan ki dukh harta, sukh sampati karta.","m":"You alone are the mother of the world and its sustainer; you remove your devotees’ sorrows and bring them happiness and plenty.","h":"आप ही जगत की माता और पालनहार हैं; आप भक्तों के दुःख हरती हैं और उन्हें सुख-सम्पत्ति देती हैं।"},{"d":"भुजा चार अति शोभित, वरमुद्रा धारी।\nमनवांछित फल पावत, सेवत नर नारी॥","r":"Bhuja chaar ati shobhit, varmudra dhari,\nManvanchhit phal paavat, sevat nar nari.","m":"Your four arms are radiant, one raised in blessing; the men and women who serve you receive what their hearts desire.","h":"आपकी चारों भुजाएँ अत्यन्त सुन्दर हैं और एक हाथ वरमुद्रा में है; जो नर-नारी आपकी सेवा करते हैं, वे मनचाहा फल पाते हैं।"},{"d":"कंचन थाल विराजत, अगर कपूर बाती।\nश्रीमालकेतु में राजत, कोटि रतन ज्योती॥","r":"Kanchan thaal virajat, agar kapoor baati,\nShrimalketu mein raajat, koti ratan jyoti.","m":"A golden plate is set with aloe-wood, camphor and wicks, and the flames shine like countless jewels.","h":"सोने की थाली में अगर, कपूर और बाती सजी है, और उसकी लौ करोड़ों रत्नों जैसी चमकती है।"},{"d":"श्री अम्बेजी की आरती, जो कोई नर गावे।\nकहत शिवानन्द स्वामी, सुख सम्पत्ति पावे॥","r":"Shri Ambeji ki aarti, jo koi nar gaave,\nKahat Shivanand Swami, sukh sampatti paave.","m":"Whoever sings this aarti of Mother Ambe, says Swami Shivanand, gains happiness and prosperity.","h":"स्वामी शिवानन्द कहते हैं, जो कोई श्री अम्बे जी की यह आरती गाता है, वह सुख और सम्पत्ति पाता है।"}]},{"id":"jai-ganesh-deva","kind":"aarti","deity":"ganesh","lang":"hi","language":"Hindi","region":"North India","title":{"d":"जय गणेश जय गणेश देवा","r":"Jai Ganesh Jai Ganesh Deva","en":"Aarti of Shri Ganesh"},"auth":{"t":"Traditional. The last verse names “Soor”, often read as Surdas.","c":"attributed"},"occ":["ganesh-chaturthi","diwali","satyanarayan","griha-pravesh","daily"],"when":"Sung first in most North Indian pujas, because Ganesh is worshipped before any other deity. Wednesday is his day.","notes":"Editions differ slightly, for example “माथे सिन्दूर सोहे” or “माथे पर तिलक सोहे”. Many families add the verse “दीनन की लाज रखो, शम्भु सुतकारी”.","refrain":{"d":"जय गणेश जय गणेश, जय गणेश देवा।\nमाता जाकी पार्वती, पिता महादेवा॥","r":"Jai Ganesh jai Ganesh, jai Ganesh Deva,\nMata jaki Parvati, pita Mahadeva.","m":"Glory to Lord Ganesh, whose mother is Parvati and whose father is Mahadev.","h":"भगवान गणेश की जय हो, जिनकी माता पार्वती और पिता महादेव हैं।"},"refrainFirst":true,"verses":[{"d":"एक दन्त दयावन्त, चार भुजा धारी।\nमाथे सिन्दूर सोहे, मूसे की सवारी॥","r":"Ek dant dayavant, chaar bhuja dhari,\nMathe sindoor sohe, moose ki savari.","m":"The one-tusked, compassionate lord with four arms. Vermilion graces his forehead and he rides a mouse.","h":"एक दाँत वाले, दयालु, चार भुजाओं वाले प्रभु; उनके मस्तक पर सिन्दूर शोभा देता है और वे चूहे की सवारी करते हैं।"},{"d":"पान चढ़े फूल चढ़े, और चढ़े मेवा।\nलड्डुअन का भोग लगे, सन्त करें सेवा॥","r":"Paan chadhe phool chadhe, aur chadhe meva,\nLadduan ka bhog lage, sant karen seva.","m":"Betel leaves, flowers and dry fruits are offered to him; laddus are his bhog, and the saintly serve him.","h":"उन्हें पान, फूल और मेवा चढ़ाए जाते हैं; लड्डुओं का भोग लगता है और संत उनकी सेवा करते हैं।"},{"d":"अंधन को आँख देत, कोढ़िन को काया।\nबाँझन को पुत्र देत, निर्धन को माया॥","r":"Andhan ko aankh det, kodhin ko kaya,\nBaanjhan ko putra det, nirdhan ko maya.","m":"He gives sight to the blind, a healthy body to the afflicted, children to the childless and wealth to the poor.","h":"वे अंधों को आँखें, रोगियों को स्वस्थ काया, निःसंतानों को संतान और निर्धनों को धन देते हैं।"},{"d":"‘सूर’ श्याम शरण आए, सफल कीजे सेवा।\nमाता जाकी पार्वती, पिता महादेवा॥","r":"Soor Shyam sharan aaye, saphal keeje seva,\nMata jaki Parvati, pita Mahadeva.","m":"Soor, devotee of Shyam, has come to your refuge: make this worship fruitful, son of Parvati and Mahadev.","h":"श्याम के भक्त सूरदास आपकी शरण में आए हैं; हे पार्वती और महादेव के पुत्र, उनकी सेवा सफल कीजिए।"}]},{"id":"om-jai-jagdish-hare","kind":"aarti","deity":"vishnu","lang":"hi","language":"Hindi","region":"North India, now sung everywhere","title":{"d":"ॐ जय जगदीश हरे","r":"Om Jai Jagdish Hare","en":"Aarti of Shri Vishnu"},"auth":{"t":"Pandit Shardha Ram Phillauri, around 1870","c":"known"},"occ":["daily","satyanarayan","diwali","griha-pravesh"],"when":"Probably the most widely sung aarti of all. Many homes close every evening aarti with it, whichever deity was worshipped, and it is the aarti of Satyanarayan Katha. Thursday is Vishnu’s day.","notes":"The line “श्रद्धा भक्ति बढ़ाओ” is often read as the poet’s signature, since his name was Shardha Ram. Editions differ in places, for example “मैं मूरख फलगामी” or “मैं मूरख खल कामी”.","refrain":{"d":"ॐ जय जगदीश हरे, स्वामी जय जगदीश हरे।\nभक्त जनों के संकट, दास जनों के संकट, क्षण में दूर करे॥","r":"Om jai Jagdish hare, Swami jai Jagdish hare,\nBhakt janon ke sankat, daas janon ke sankat, kshan mein door kare.","m":"Om, glory to you, Hari, Lord of the universe! You remove the troubles of your devotees and servants in an instant.","h":"हे जगत के स्वामी हरि, आपकी जय हो! आप भक्तों और सेवकों के संकट पल भर में दूर कर देते हैं।"},"refrainFirst":true,"verses":[{"d":"जो ध्यावे फल पावे, दुःख बिनसे मन का, स्वामी दुःख बिनसे मन का।\nसुख सम्पत्ति घर आवे, कष्ट मिटे तन का॥","r":"Jo dhyave phal pave, dukh binse man ka, Swami dukh binse man ka,\nSukh sampatti ghar aave, kasht mite tan ka.","m":"Whoever meditates on you receives the fruit, and the mind’s sorrow is destroyed; happiness and prosperity come home and the body’s suffering ends.","h":"जो आपका ध्यान करता है, उसे फल मिलता है और उसके मन का दुःख मिट जाता है; घर में सुख-सम्पत्ति आती है और शरीर का कष्ट दूर होता है।"},{"d":"मात पिता तुम मेरे, शरण गहूँ मैं किसकी, स्वामी शरण गहूँ मैं किसकी।\nतुम बिन और न दूजा, आस करूँ मैं जिसकी॥","r":"Maat pita tum mere, sharan gahoon main kiski, Swami sharan gahoon main kiski,\nTum bin aur na dooja, aas karoon main jiski.","m":"You are my mother and father; whose refuge should I seek? Without you there is no other in whom I can place my hope.","h":"आप ही मेरे माता-पिता हैं; मैं और किसकी शरण लूँ? आपके सिवा दूसरा कोई नहीं, जिससे मैं आशा रखूँ।"},{"d":"तुम पूरण परमात्मा, तुम अन्तर्यामी, स्वामी तुम अन्तर्यामी।\nपारब्रह्म परमेश्वर, तुम सब के स्वामी॥","r":"Tum pooran Paramatma, tum Antaryami, Swami tum Antaryami,\nParabrahm Parameshwar, tum sab ke swami.","m":"You are the complete Supreme Soul, the knower of every heart: the Supreme Brahman, the Supreme Lord, master of all.","h":"आप पूर्ण परमात्मा हैं, सबके मन की जानने वाले अन्तर्यामी हैं; आप ही परब्रह्म परमेश्वर और सबके स्वामी हैं।"},{"d":"तुम करुणा के सागर, तुम पालनकर्ता, स्वामी तुम पालनकर्ता।\nमैं मूरख फलगामी, मैं सेवक तुम स्वामी, कृपा करो भर्ता॥","r":"Tum karuna ke sagar, tum palankarta, Swami tum palankarta,\nMain moorakh phalgami, main sevak tum swami, kripa karo bharta.","m":"You are an ocean of compassion and the sustainer of all. I am foolish and chase rewards; I am your servant and you my master. Be gracious, Lord.","h":"आप करुणा के सागर और सबका पालन करने वाले हैं। मैं मूर्ख हूँ और फल की इच्छा करता हूँ; मैं सेवक हूँ और आप स्वामी, हे प्रभु, कृपा कीजिए।"},{"d":"तुम हो एक अगोचर, सबके प्राणपति, स्वामी सबके प्राणपति।\nकिस विधि मिलूँ दयामय, तुमको मैं कुमति॥","r":"Tum ho ek agochar, sabke pranpati, Swami sabke pranpati,\nKis vidhi miloon dayamay, tumko main kumati.","m":"You are the One beyond the senses, lord of every life. How can someone of my poor understanding reach you, merciful one?","h":"आप एक हैं, इन्द्रियों से परे हैं और सबके प्राणों के स्वामी हैं। हे दयामय, मुझ जैसा कम बुद्धि वाला आपसे किस प्रकार मिले?"},{"d":"दीनबन्धु दुःखहर्ता, ठाकुर तुम मेरे, स्वामी रक्षक तुम मेरे।\nअपने हाथ उठाओ, अपनी शरण लगाओ, द्वार पड़ा तेरे॥","r":"Deenbandhu dukhharta, Thakur tum mere, Swami rakshak tum mere,\nApne haath uthao, apni sharan lagao, dwaar pada tere.","m":"Friend of the humble, remover of sorrow, you are my lord and protector. Raise your hand and take me into your refuge; I lie at your door.","h":"हे दीनों के बन्धु, दुःख हरने वाले, आप ही मेरे स्वामी और रक्षक हैं। अपना हाथ बढ़ाइए और मुझे अपनी शरण में लीजिए; मैं आपके द्वार पर पड़ा हूँ।"},{"d":"विषय विकार मिटाओ, पाप हरो देवा, स्वामी पाप हरो देवा।\nश्रद्धा भक्ति बढ़ाओ, सन्तन की सेवा॥","r":"Vishay vikaar mitao, paap haro Deva, Swami paap haro Deva,\nShraddha bhakti badhao, santan ki seva.","m":"Wipe away my cravings and failings and take away my sins, Lord. Increase my faith, my devotion and my service to the saintly.","h":"हे देव, मेरे विषय-विकार मिटाइए और पाप हर लीजिए। मेरी श्रद्धा, भक्ति और संतों की सेवा बढ़ाइए।"},{"d":"तन मन धन सब कुछ है तेरा, स्वामी सब कुछ है तेरा।\nतेरा तुझको अर्पण, क्या लागे मेरा॥","r":"Tan man dhan sab kuchh hai tera, Swami sab kuchh hai tera,\nTera tujhko arpan, kya laage mera.","m":"Body, mind and wealth all belong to you. I offer you what is already yours; what part of it is mine?","h":"तन, मन, धन सब कुछ आपका ही है। आपकी वस्तु आपको ही अर्पित है; इसमें मेरा क्या लगता है?"}]},{"id":"om-jai-lakshmi-mata","kind":"aarti","deity":"lakshmi","lang":"hi","language":"Hindi","region":"North India","title":{"d":"ॐ जय लक्ष्मी माता","r":"Om Jai Lakshmi Mata","en":"Aarti of Maa Lakshmi"},"auth":{"t":"Traditional","c":"traditional"},"occ":["diwali","dhanteras","daily"],"when":"The heart of Lakshmi Puja on Diwali evening, sung after the Ganesh aarti. Also sung on Fridays and on Dhanteras.","notes":"Sung to the same tune as Om Jai Jagdish Hare, whose pattern it follows. Some editions print “हरि विष्णु विधाता” in the refrain.","refrain":{"d":"ॐ जय लक्ष्मी माता, मैया जय लक्ष्मी माता।\nतुमको निशदिन सेवत, हर विष्णु विधाता॥","r":"Om jai Lakshmi Mata, Maiya jai Lakshmi Mata,\nTumko nishdin sevat, Har Vishnu Vidhata.","m":"Om, glory to Mother Lakshmi! Shiv, Vishnu and Brahma worship you day and night.","h":"हे लक्ष्मी माता, आपकी जय हो! शिव, विष्णु और ब्रह्मा दिन-रात आपकी सेवा करते हैं।"},"refrainFirst":true,"verses":[{"d":"उमा रमा ब्रह्माणी, तुम ही जग माता।\nसूर्य चन्द्रमा ध्यावत, नारद ऋषि गाता॥","r":"Uma Rama Brahmani, tum hi jag mata,\nSurya Chandrama dhyavat, Narad rishi gata.","m":"You are Uma, Rama and Brahmani, mother of the world. The sun and moon meditate on you and the sage Narad sings your glory.","h":"आप ही उमा, रमा और ब्रह्माणी हैं, आप ही जगत की माता हैं। सूर्य और चन्द्रमा आपका ध्यान करते हैं और नारद मुनि आपका गुणगान करते हैं।"},{"d":"दुर्गा रूप निरंजनि, सुख सम्पत्ति दाता।\nजो कोई तुमको ध्यावत, ऋद्धि सिद्धि धन पाता॥","r":"Durga roop niranjani, sukh sampatti data,\nJo koi tumko dhyavat, riddhi siddhi dhan pata.","m":"Pure one in the form of Durga, giver of happiness and plenty: whoever meditates on you gains abundance, success and wealth.","h":"आप दुर्गा रूप में निर्मल हैं और सुख-सम्पत्ति देने वाली हैं; जो कोई आपका ध्यान करता है, वह ऋद्धि, सिद्धि और धन पाता है।"},{"d":"तुम पाताल निवासिनि, तुम ही शुभदाता।\nकर्म प्रभाव प्रकाशिनि, भवनिधि की त्राता॥","r":"Tum Patal nivasini, tum hi shubhdata,\nKarm prabhav prakashini, bhavnidhi ki trata.","m":"You dwell even in the netherworld, and you alone bestow good fortune. You bring the fruits of our deeds to light and carry us across the ocean of worldly life.","h":"आप पाताल में भी निवास करती हैं और आप ही शुभ फल देने वाली हैं। आप कर्मों के फल को प्रकट करती हैं और संसार-सागर से पार उतारती हैं।"},{"d":"जिस घर में तुम रहतीं, सब सद्गुण आता।\nसब सम्भव हो जाता, मन नहीं घबराता॥","r":"Jis ghar mein tum rahtin, sab sadgun aata,\nSab sambhav ho jata, man nahin ghabrata.","m":"Every virtue comes to the home where you live; everything becomes possible and the mind is free of fear.","h":"जिस घर में आप रहती हैं, वहाँ सब सद्गुण आ जाते हैं; सब कुछ सम्भव हो जाता है और मन नहीं घबराता।"},{"d":"तुम बिन यज्ञ न होते, वस्त्र न कोई पाता।\nखान पान का वैभव, सब तुमसे आता॥","r":"Tum bin yagya na hote, vastra na koi pata,\nKhaan paan ka vaibhav, sab tumse aata.","m":"Without you no sacrifice could be performed and no one would have clothing; all the richness of food and drink comes from you.","h":"आपके बिना न यज्ञ हो सकते हैं, न किसी को वस्त्र मिलते हैं; खान-पान का सारा वैभव आपसे ही आता है।"},{"d":"शुभ गुण मन्दिर सुन्दर, क्षीरोदधि जाता।\nरत्न चतुर्दश तुम बिन, कोई नहीं पाता॥","r":"Shubh gun mandir sundar, Kshirodadhi jata,\nRatna chaturdash tum bin, koi nahin pata.","m":"Beautiful temple of auspicious qualities, born of the ocean of milk: without you no one obtains the fourteen treasures.","h":"आप शुभ गुणों का सुन्दर मन्दिर हैं और क्षीरसागर से उत्पन्न हुई हैं; आपके बिना कोई भी चौदह रत्न नहीं पा सकता।"},{"d":"महालक्ष्मी जी की आरती, जो कोई जन गाता।\nउर आनन्द समाता, पाप उतर जाता॥","r":"Mahalakshmi ji ki aarti, jo koi jan gata,\nUr anand samata, paap utar jata.","m":"Whoever sings this aarti of Mahalakshmi is filled with joy, and their sins fall away.","h":"जो कोई महालक्ष्मी जी की यह आरती गाता है, उसके हृदय में आनन्द भर जाता है और उसके पाप उतर जाते हैं।"}]},{"id":"om-jai-saraswati-mata","kind":"aarti","deity":"saraswati","lang":"hi","language":"Hindi","region":"North India","title":{"d":"ॐ जय सरस्वती माता","r":"Om Jai Saraswati Mata","en":"Aarti of Maa Saraswati"},"auth":{"t":"Traditional","c":"traditional"},"occ":["basant-panchami","navratri","daily"],"when":"Sung on Basant Panchami and before study in schools and homes. In South India, Saraswati Puja falls during Navratri.","notes":"Sung to the same tune as Om Jai Jagdish Hare.","refrain":{"d":"ॐ जय सरस्वती माता, मैया जय सरस्वती माता।\nसद्गुण वैभव शालिनी, त्रिभुवन विख्याता॥","r":"Om jai Saraswati Mata, Maiya jai Saraswati Mata,\nSadgun vaibhav shalini, tribhuvan vikhyata.","m":"Om, glory to Mother Saraswati! Rich in every virtue and splendour, famed in all three worlds.","h":"हे सरस्वती माता, आपकी जय हो! आप सद्गुणों और वैभव से सम्पन्न हैं और तीनों लोकों में प्रसिद्ध हैं।"},"refrainFirst":true,"verses":[{"d":"चन्द्रवदनि पद्मासिनि, द्युति मंगलकारी।\nसोहे शुभ हंस सवारी, अतुल तेजधारी॥","r":"Chandravadani padmasini, dyuti mangalkari,\nSohe shubh hans savari, atul tejdhari.","m":"Moon-faced goddess seated on a lotus, your radiance brings blessings. You ride the auspicious swan and shine with matchless light.","h":"हे चन्द्रमुखी, कमल पर विराजने वाली देवी, आपकी कान्ति मंगल करने वाली है। आप शुभ हंस की सवारी पर शोभा पाती हैं और अतुलनीय तेज धारण करती हैं।"},{"d":"बाएँ कर में वीणा, दाएँ कर माला।\nशीश मुकुट मणि सोहे, गल मोतियन माला॥","r":"Baayen kar mein veena, daayen kar mala,\nSheesh mukut mani sohe, gal motiyan mala.","m":"The veena is in your left hand and a rosary in your right. A jewelled crown graces your head and a string of pearls your neck.","h":"आपके बाएँ हाथ में वीणा और दाएँ हाथ में माला है। सिर पर मणियों का मुकुट और गले में मोतियों की माला शोभा देती है।"},{"d":"देवी शरण जो आए, उनका उद्धार किया।\nपैठी मंथरा दासी, रावण संहार किया॥","r":"Devi sharan jo aaye, unka uddhar kiya,\nPaithi Manthara dasi, Ravan sanhar kiya.","m":"Goddess, you raised up all who came to your refuge. You entered the mind of the maid Manthara and so brought about Ravan’s end.","h":"हे देवी, जो आपकी शरण में आया, आपने उसका उद्धार किया। आपने मंथरा दासी की बुद्धि में प्रवेश करके रावण के संहार का मार्ग बनाया।"},{"d":"विद्या ज्ञान प्रदायिनि, ज्ञान प्रकाश भरो।\nमोह अज्ञान और तिमिर का, जग से नाश करो॥","r":"Vidya gyan pradayini, gyan prakash bharo,\nMoh agyan aur timir ka, jag se naash karo.","m":"Giver of learning and wisdom, fill us with the light of knowledge, and drive delusion, ignorance and darkness from the world.","h":"हे विद्या और ज्ञान देने वाली, हमें ज्ञान के प्रकाश से भर दीजिए और संसार से मोह, अज्ञान और अन्धकार का नाश कीजिए।"},{"d":"धूप दीप फल मेवा, माँ स्वीकार करो।\nज्ञानचक्षु दे माता, जग निस्तार करो॥","r":"Dhoop deep phal meva, Maa sweekar karo,\nGyanchakshu de Mata, jag nistar karo.","m":"Mother, accept our incense, lamp, fruit and dry fruits. Give us the eye of wisdom and carry the world across.","h":"हे माँ, धूप, दीप, फल और मेवा स्वीकार कीजिए। हे माता, ज्ञान की आँखें देकर जगत का उद्धार कीजिए।"},{"d":"माँ सरस्वती की आरती, जो कोई जन गावे।\nहितकारी सुखकारी, ज्ञान भक्ति पावे॥","r":"Maa Saraswati ki aarti, jo koi jan gaave,\nHitkari sukhkari, gyan bhakti paave.","m":"Whoever sings this aarti of Mother Saraswati gains wisdom and devotion, which bring wellbeing and happiness.","h":"जो कोई माँ सरस्वती की यह आरती गाता है, वह हितकारी और सुखकारी ज्ञान और भक्ति पाता है।"}]},{"id":"om-jai-shiv-omkara","kind":"aarti","deity":"shiv","lang":"hi","language":"Hindi","region":"North India","title":{"d":"ॐ जय शिव ओंकारा","r":"Om Jai Shiv Omkara","en":"Aarti of Lord Shiv"},"auth":{"t":"Traditional. The closing verse names Swami Shivanand.","c":"attributed"},"occ":["mahashivratri","shravan","daily"],"when":"Sung on Mondays, through the month of Sawan and on Maha Shivratri. It praises Shiv as one with Brahma and Vishnu.","notes":"One of the most variable texts. Longer versions add verses on Kailash, the Ganga and Kashi Vishwanath, and some lines differ by region, such as “त्रिपुरारी कंसारी कर माला धारी”. This is a shorter common form.","refrain":{"d":"ॐ जय शिव ओंकारा, स्वामी जय शिव ओंकारा।\nब्रह्मा विष्णु सदाशिव, अर्द्धांगी धारा॥","r":"Om jai Shiv Omkara, Swami jai Shiv Omkara,\nBrahma Vishnu Sadashiv, ardhangi dhara.","m":"Om, glory to Shiv, embodiment of Om! You are Brahma, Vishnu and Sadashiv, and you hold your consort as half of your own body.","h":"ओंकार स्वरूप शिव, आपकी जय हो! आप ही ब्रह्मा, विष्णु और सदाशिव हैं, और आपने पार्वती को अपने आधे अंग में धारण किया है।"},"refrainFirst":true,"verses":[{"d":"एकानन चतुरानन पंचानन राजे।\nहंसासन गरुड़ासन वृषवाहन साजे॥","r":"Ekanan chaturanan panchanan raje,\nHansasan Garudasan vrishvahan saje.","m":"With one face, four faces and five faces you shine, seated on the swan, on Garuda, and riding the bull.","h":"आप एक मुख, चार मुख और पाँच मुख वाले रूपों में शोभा पाते हैं; हंस, गरुड़ और बैल पर सवार होकर सुशोभित होते हैं।"},{"d":"दो भुज चार चतुर्भुज दसभुज अति सोहे।\nत्रिगुण रूप निरखते त्रिभुवन जन मोहे॥","r":"Do bhuj chaar chaturbhuj dasbhuj ati sohe,\nTrigun roop nirakhte tribhuvan jan mohe.","m":"With two, four and ten arms you are magnificent; seeing your form of the three gunas, all three worlds are enchanted.","h":"दो भुजाओं, चार भुजाओं और दस भुजाओं वाले आपके रूप अत्यन्त सुन्दर हैं; आपके त्रिगुण रूप को देखकर तीनों लोकों के लोग मोहित हो जाते हैं।"},{"d":"अक्षमाला वनमाला मुण्डमाला धारी।\nचन्दन मृगमद सोहै भाले शशिधारी॥","r":"Akshmala vanmala mundmala dhari,\nChandan mrigmad sohai bhale shashidhari.","m":"You wear rudraksha beads, a garland of forest flowers and a garland of skulls; sandalwood and musk adorn you, and the moon rests on your brow.","h":"आप रुद्राक्ष की माला, वनमाला और मुण्डमाला धारण करते हैं; चन्दन और कस्तूरी आपको शोभा देते हैं और आपके मस्तक पर चन्द्रमा है।"},{"d":"श्वेताम्बर पीताम्बर बाघम्बर अंगे।\nसनकादिक गरुड़ादिक भूतादिक संगे॥","r":"Shvetambar pitambar baghambar ange,\nSanakadik Garudadik bhootadik sange.","m":"Dressed in white, in yellow silk and in tiger skin, accompanied by sages like Sanaka, by Garuda and by hosts of spirits.","h":"आप श्वेत वस्त्र, पीताम्बर और बाघम्बर धारण करते हैं; सनक आदि मुनि, गरुड़ आदि और भूतगण आपके साथ रहते हैं।"},{"d":"कर के मध्य कमण्डलु चक्र त्रिशूलधर्ता।\nजगकर्ता जगभर्ता जगसंहारकर्ता॥","r":"Kar ke madhya kamandalu chakra trishooldharta,\nJagkarta jagbharta jagsanharkarta.","m":"Holding the water-pot, the discus and the trident: creator, sustainer and destroyer of the world.","h":"आपके हाथों में कमण्डलु, चक्र और त्रिशूल हैं; आप ही जगत के रचयिता, पालनकर्ता और संहारकर्ता हैं।"},{"d":"ब्रह्मा विष्णु सदाशिव जानत अविवेका।\nप्रणवाक्षर के मध्ये ये तीनों एका॥","r":"Brahma Vishnu Sadashiv janat aviveka,\nPranavakshar ke madhye ye teenon eka.","m":"Only the unwise think Brahma, Vishnu and Sadashiv are separate; within the sacred syllable Om, the three are one.","h":"अज्ञानी लोग ही ब्रह्मा, विष्णु और सदाशिव को अलग-अलग मानते हैं; ॐ अक्षर के भीतर ये तीनों एक ही हैं।"},{"d":"त्रिगुणस्वामी जी की आरती जो कोई नर गावे।\nकहत शिवानन्द स्वामी मनवांछित फल पावे॥","r":"Trigunswami ji ki aarti jo koi nar gave,\nKahat Shivanand Swami manvanchhit phal pave.","m":"Whoever sings this aarti of the lord of the three gunas, says Swami Shivanand, gains the fruit of their heart’s desire.","h":"स्वामी शिवानन्द कहते हैं, जो कोई त्रिगुण स्वामी की यह आरती गाता है, वह मनचाहा फल पाता है।"}]},{"id":"sukhkarta-dukhharta","kind":"aarti","deity":"ganesh","lang":"mr","language":"Marathi","region":"Maharashtra","title":{"d":"सुखकर्ता दुःखहर्ता","r":"Sukhkarta Dukhharta","en":"Marathi aarti of Shri Ganesh"},"auth":{"t":"Samarth Ramdas, 17th century. The last verse carries his signature, “दास रामाचा”.","c":"attributed"},"occ":["ganesh-chaturthi","daily"],"when":"Opens the aarti in Maharashtrian homes and Ganeshotsav pandals; the session usually ends with “घालीन लोटांगण” and Mantrapushpanjali.","notes":"The refrain follows each verse rather than opening the aarti. It is set in a Marathi cut of the typeface, because a few letters are traditionally drawn differently in Marathi.","refrain":{"d":"जय देव जय देव जय मंगलमूर्ती।\nदर्शनमात्रे मनकामना पुरती॥","r":"Jai Dev jai Dev jai Mangalmurti,\nDarshanmatre mankamana purti.","m":"Glory, Lord, to the auspicious one: the mere sight of you fulfils the heart’s wishes.","h":"हे देव, हे मंगलमूर्ति, आपकी जय हो! आपके दर्शन मात्र से मन की कामनाएँ पूरी हो जाती हैं।"},"refrainFirst":false,"verses":[{"d":"सुखकर्ता दुःखहर्ता वार्ता विघ्नाची।\nनुरवी पुरवी प्रेम कृपा जयाची।\nसर्वांगी सुंदर उटी शेंदुराची।\nकंठी झळके माळ मुक्ताफळांची॥","r":"Sukhkarta dukhharta varta vighnachi,\nNuravi puravi prem krupa jayachi.\nSarvangi sundar uti shendurachi,\nKanthi jhalake maal muktaphalanchi.","m":"Giver of joy and remover of sorrow, whose grace leaves not even a whisper of obstacles and showers love. His whole body glows with vermilion paste and a string of pearls gleams at his throat.","h":"आप सुख देने वाले और दुःख हरने वाले हैं; आपकी कृपा से विघ्नों की बात भी नहीं रहती, और आप प्रेम बरसाते हैं। आपके सारे अंगों पर सिन्दूर का सुन्दर लेप है और गले में मोतियों की माला झलकती है।"},{"d":"रत्नखचित फरा तुज गौरीकुमरा।\nचंदनाची उटी कुंकुमकेशरा।\nहिरेजडित मुकुट शोभतो बरा।\nरुणझुणती नूपुरे चरणी घागरिया॥","r":"Ratnakhachit phara tuj Gaurikumara,\nChandanachi uti kumkumkeshara.\nHirejadit mukut shobhato bara,\nRunjhunati nupure charani ghagariya.","m":"Son of Gauri, jewels adorn you and you are anointed with sandalwood, kumkum and saffron. A diamond-studded crown shines on you, and anklets with tiny bells jingle at your feet.","h":"हे गौरीपुत्र, आप रत्नों से सजे हैं और आप पर चन्दन, कुमकुम और केसर का लेप है। हीरों से जड़ा मुकुट सुन्दर शोभा देता है और चरणों में घुँघरू वाले नूपुर रुनझुन बजते हैं।"},{"d":"लंबोदर पीतांबर फणिवरबंधना।\nसरळ सोंड वक्रतुंड त्रिनयना।\nदास रामाचा वाट पाहे सदना।\nसंकटी पावावे निर्वाणी रक्षावे सुरवरवंदना॥","r":"Lambodar pitambar phanivarbandhana,\nSaral sond vakratunda trinayana.\nDas Ramacha vaat pahe sadana,\nSankati pavave nirvani rakshave survaravandana.","m":"Big-bellied lord in yellow silk with a serpent for a sash, straight-trunked, curve-faced, three-eyed. Ramdas, your servant, waits for you at home: come to us in trouble and protect us at the last, lord worshipped by the gods.","h":"हे लम्बोदर, आप पीताम्बर पहनते हैं और सर्प की करधनी बाँधते हैं; आपकी सूँड सीधी है, मुख टेढ़ा है और तीन नेत्र हैं। आपका दास रामदास घर पर आपकी राह देख रहा है; हे देवताओं से वन्दित, संकट में आइए और अन्त समय में रक्षा कीजिए।"}]},{"id":"jai-jai-giribarraj-kishori","kind":"bhajan","deity":"durga","lang":"hi","language":"Hindi","region":"All of North India","title":{"d":"जय जय गिरिबरराज किसोरी","r":"Jai Jai Giribarraj Kishori","en":"Sita’s prayer to Gauri"},"auth":{"t":"Goswami Tulsidas, from the Bal Kand of the Ramcharitmanas","c":"known"},"occ":["navratri","daily"],"when":"In the Manas, Sita sings this to Gauri (Parvati) in the temple of Janakpur before the bow ceremony, and the goddess blesses her. It is sung in Navratri, especially on Ashtami for Mahagauri, and by unmarried girls praying for a good husband.","form":"Stuti from the Ramcharitmanas","dialect":"Awadhi","notes":"Dohas 235 and 236 of the Bal Kand with the chaupais between them, as printed in Gita Press editions. Tulsidas uses Awadhi spellings such as बिस्व and बेदु.","refrain":null,"refrainFirst":true,"verses":[{"d":"जय जय गिरिबरराज किसोरी। जय महेस मुख चंद चकोरी॥\nजय गजबदन षडानन माता। जगत जननि दामिनि दुति गाता॥","r":"Jai jai Giribarraj Kishori, jai Mahes mukh chand chakori,\nJai Gajbadan Shadanan mata, jagat janani damini duti gata.","m":"Glory, glory to the daughter of the king of mountains! Glory to you, the chakor bird gazing at the moon of Shiv’s face! Glory to the mother of elephant-faced Ganesh and six-faced Kartikeya, mother of the world, whose body shines like lightning.","h":"हे पर्वतराज हिमालय की पुत्री, आपकी जय हो, जय हो! हे महादेव के मुखचन्द्र को निहारने वाली चकोरी, आपकी जय हो! हे गणेश और षडानन (कार्तिकेय) की माता, जगत की जननी, बिजली जैसी कान्ति वाले शरीर वाली, आपकी जय हो।"},{"d":"नहिं तव आदि मध्य अवसाना। अमित प्रभाउ बेदु नहिं जाना॥\nभव भव बिभव पराभव कारिनि। बिस्व बिमोहनि स्वबस बिहारिनि॥","r":"Nahin tav aadi madhya avasana, amit prabhau bedu nahin jana,\nBhav bhav bibhav parabhav karini, bisva bimohani svabas biharini.","m":"You have no beginning, middle or end; even the Vedas do not know your boundless power. You bring about the birth, growth and dissolution of the world; you enchant the universe and move freely by your own will.","h":"आपका न आदि है, न मध्य, न अन्त; आपके अपार प्रभाव को वेद भी नहीं जानते। आप संसार की उत्पत्ति, पालन और संहार करने वाली हैं; सारे विश्व को मोहित करने वाली और अपनी इच्छा से विहार करने वाली हैं।"},{"d":"पतिदेवता सुतीय महुँ मातु प्रथम तव रेख।\nमहिमा अमित न सकहिं कहि सहस सारदा सेष॥","r":"Patidevata sutiya mahun matu pratham tav rekh,\nMahima amit na sakahin kahi sahas Sarada Sesh.","m":"Mother, among devoted and virtuous wives you are counted first. Not even a thousand Saraswatis and Sheshnags could describe your boundless glory.","h":"हे माता, पति को देवता मानने वाली श्रेष्ठ स्त्रियों में आपकी गिनती सबसे पहले है। आपकी अपार महिमा को हजारों सरस्वती और शेषनाग भी नहीं कह सकते।","n":"दोहा"},{"d":"सेवत तोहि सुलभ फल चारी। बरदायनी पुरारि पिआरी॥\nदेबि पूजि पद कमल तुम्हारे। सुर नर मुनि सब होहिं सुखारे॥","r":"Sevat tohi sulabh phal chari, bardayani Purari piari,\nDebi puji pad kamal tumhare, sur nar muni sab hohin sukhare.","m":"Serving you, the four aims of life come easily. Giver of boons, beloved of Shiv! Goddess, by worshipping your lotus feet gods, men and sages all become happy.","h":"आपकी सेवा करने से चारों फल (धर्म, अर्थ, काम, मोक्ष) सहज ही मिल जाते हैं। हे वर देने वाली, हे शिवजी की प्रिया! हे देवी, आपके चरण-कमलों की पूजा करके देवता, मनुष्य और मुनि सब सुखी हो जाते हैं।"},{"d":"मोर मनोरथु जानहु नीकें। बसहु सदा उर पुर सबही कें॥\nकीन्हेउँ प्रगट न कारन तेहीं। अस कहि चरन गहे बैदेहीं॥","r":"Mor manorathu janahu neeken, basahu sada ur pur sabahi ken,\nKeenheun pragat na karan tehin, as kahi charan gahe Baidehin.","m":"You know my heart’s wish well, for you live always in the city of every heart; that is why I have not spoken it aloud. Saying this, Sita clasped the goddess’s feet.","h":"आप मेरे मन की इच्छा भली-भाँति जानती हैं, क्योंकि आप सदा सबके हृदय रूपी नगर में निवास करती हैं; इसी कारण मैंने उसे प्रकट नहीं किया। ऐसा कहकर सीताजी ने देवी के चरण पकड़ लिए।"},{"d":"बिनय प्रेम बस भई भवानी। खसी माल मूरति मुसुकानी॥\nसादर सियँ प्रसादु सिर धरेऊ। बोली गौरि हरषु हियँ भरेऊ॥","r":"Binay prem bas bhai Bhavani, khasi maal murati musukani,\nSadar siyan prasadu sir dhareu, boli Gauri harashu hiyan bhareu.","m":"Bhavani was won over by her humility and love. A garland slipped from the image and the image smiled. Sita reverently placed the blessed garland on her head, and Gauri spoke, her heart full of joy.","h":"सीताजी की विनय और प्रेम से भवानी वश में हो गईं। मूर्ति से माला खिसक पड़ी और मूर्ति मुस्कुरा उठी। सीताजी ने आदरपूर्वक उस प्रसाद को सिर पर रखा, और गौरीजी हृदय में हर्ष भरकर बोलीं।"},{"d":"सुनु सिय सत्य असीस हमारी। पूजिहि मन कामना तुम्हारी॥\nनारद बचन सदा सुचि साचा। सो बरु मिलिहि जाहिं मनु राचा॥","r":"Sunu siya satya asees hamari, poojihi man kamana tumhari,\nNarad bachan sada suchi sacha, so baru milihi jahin manu racha.","m":"Listen, Sita, my blessing is true: your heart’s desire will be fulfilled. Narad’s words are always pure and true; you will marry the one your heart is set on.","h":"हे सीता, सुनो, मेरा आशीर्वाद सत्य है: तुम्हारे मन की कामना पूरी होगी। नारदजी के वचन सदा पवित्र और सच्चे होते हैं; जिस पर तुम्हारा मन रीझा है, वही वर तुम्हें मिलेगा।"},{"d":"मनु जाहिं राचेउ मिलिहि सो बरु सहज सुंदर साँवरो।\nकरुना निधान सुजान सीलु सनेहु जानत रावरो॥\nएहि भाँति गौरि असीस सुनि सिय सहित हियँ हरषीं अली।\nतुलसी भवानिहि पूजि पुनि पुनि मुदित मन मंदिर चली॥","r":"Manu jahin racheu milihi so baru sahaj sundar sanvaro,\nKaruna nidhan sujan seelu sanehu janat ravaro.\nEhi bhanti Gauri asees suni Siya sahit hiyan harashin ali,\nTulasi Bhavanihi puji puni puni mudit man mandir chali.","m":"The one your heart has chosen, naturally handsome and dark, will be yours. He is a treasure of compassion and all-knowing, and he knows your goodness and your love. Hearing Gauri’s blessing, Sita and her friends rejoiced. Says Tulsi: worshipping Bhavani again and again, Sita returned to the palace with a glad heart.","h":"जिस पर तुम्हारा मन रीझ गया है, वही स्वभाव से सुन्दर साँवला वर तुम्हें मिलेगा। वे करुणा के भण्डार और सब जानने वाले हैं, तुम्हारे शील और स्नेह को जानते हैं। गौरीजी का यह आशीर्वाद सुनकर सीताजी और उनकी सखियाँ हृदय में हर्षित हुईं। तुलसीदासजी कहते हैं, भवानी की बार-बार पूजा करके सीताजी प्रसन्न मन से महल को चलीं।","n":"छंद"},{"d":"जानि गौरि अनुकूल सिय हिय हरषु न जाइ कहि।\nमंजुल मंगल मूल बाम अंग फरकन लगे॥","r":"Jani Gauri anukool siya hiy harashu na jai kahi,\nManjul mangal mool bam ang pharakan lage.","m":"Knowing Gauri to be favourable, Sita felt a joy beyond words, and her left limbs began to throb, a lovely sign of good fortune to come.","h":"गौरीजी को अनुकूल जानकर सीताजी के हृदय में जो हर्ष हुआ, वह कहा नहीं जा सकता। उनके बाएँ अंग फड़कने लगे, जो सुन्दर मंगल के शुभ संकेत हैं।","n":"सोरठा"}]},{"id":"maiya-mori-main-nahin-makhan-khayo","kind":"bhajan","deity":"krishna","lang":"hi","language":"Hindi","region":"All of North India, especially Braj","title":{"d":"मैया मोरी मैं नहिं माखन खायो","r":"Maiya Mori Main Nahin Makhan Khayo","en":"Little Krishna pleads his innocence"},"auth":{"t":"Surdas, 16th century. The last verse carries his name.","c":"attributed"},"occ":["janmashtami","daily"],"when":"A favourite on Janmashtami and in tellings of Krishna’s childhood, often sung to children.","dialect":"Braj Bhasha","refrain":{"d":"मैया मोरी मैं नहिं माखन खायो॥","r":"Maiya mori main nahin makhan khayo.","m":"Mother, I did not eat the butter!","h":"माँ, मैंने माखन नहीं खाया!"},"refrainFirst":true,"verses":[{"d":"भोर भयो गैयन के पाछे, मधुबन मोहिं पठायो।\nचार पहर बंसीबट भटक्यो, साँझ परे घर आयो॥","r":"Bhor bhayo gaiyan ke pachhe, Madhuban mohin pathayo,\nChar pahar Bansibat bhatakyo, saanjh pare ghar aayo.","m":"At dawn you sent me off to Madhuban behind the cows. All day I wandered by the Bansivat tree, and came home only at dusk.","h":"सुबह होते ही तुमने मुझे गायों के पीछे मधुबन भेज दिया। चारों पहर मैं वंशीवट पर भटकता रहा और शाम होने पर घर लौटा।"},{"d":"मैं बालक बहियन को छोटो, छींको किहि बिधि पायो।\nग्वाल बाल सब बैर परे हैं, बरबस मुख लपटायो॥","r":"Main balak bahiyan ko chhoto, chheenko kihi bidhi paayo,\nGwal baal sab bair pare hain, barbas mukh laptayo.","m":"I’m a little boy with short arms; how could I reach the pot hanging from the rafters? The cowherd boys are all against me. They smeared the butter on my face!","h":"मैं छोटा बालक हूँ, मेरी बाँहें छोटी हैं; मैं ऊपर टँगे छींके तक कैसे पहुँच सकता हूँ? सारे ग्वाल-बाल मेरे दुश्मन बने हैं, उन्होंने ज़बरदस्ती मेरे मुँह पर माखन लगा दिया।"},{"d":"तू जननी मन की अति भोरी, इनके कहे पतिआयो।\nजिय तेरे कछु भेद उपजि है, जानि परायो जायो॥","r":"Tu janani man ki ati bhori, inke kahe patiayo,\nJiya tere kachhu bhed upaji hai, jaani parayo jaayo.","m":"Mother, you are far too trusting; you believed what they said. Some doubt has come into your heart, as if I were somebody else’s child.","h":"माँ, तुम मन की बहुत भोली हो, जो इनकी बातों पर विश्वास कर लिया। तुम्हारे मन में कुछ भेद आ गया है, मानो मैं किसी पराए का जाया हूँ।"},{"d":"यह लै अपनी लकुटि कमरिया, बहुतहिं नाच नचायो।\nसूरदास तब बिहँसि जसोदा, लै उर कंठ लगायो॥","r":"Yah lai apni lakuti kamariya, bahutahin naach nachayo,\nSurdas tab bihansi Jasoda, lai ur kanth lagayo.","m":"“Here, take back your stick and blanket; you’ve made me dance enough!” Then, says Surdas, Yashoda laughed and hugged him close.","h":"“यह लो अपनी लाठी और कमली, तुमने मुझे बहुत नाच नचाया है।” सूरदास कहते हैं, तब यशोदा हँस पड़ीं और कान्हा को गले से लगा लिया।"}]},{"id":"payoji-maine-ram-ratan-dhan-payo","kind":"bhajan","deity":"krishna","lang":"hi","language":"Hindi","region":"All of North India","title":{"d":"पायो जी मैंने राम रतन धन पायो","r":"Payoji Maine Ram Ratan Dhan Payo","en":"Meera’s song of the priceless treasure"},"auth":{"t":"Meerabai, 16th century. The last line carries her name.","c":"attributed"},"occ":["janmashtami","daily"],"when":"One of the best-loved bhajans of Meerabai, sung at satsangs and on Janmashtami.","dialect":"Rajasthani and Braj","notes":"Meera’s Lord is Krishna, Giridhar Nagar; “Ram ratan”, the jewel of Ram’s name, is the divine name itself. Wording varies between singers.","refrain":{"d":"पायो जी मैंने राम रतन धन पायो॥","r":"Payo ji maine Ram ratan dhan payo.","m":"I have found it: the priceless jewel of the divine name.","h":"मैंने राम नाम रूपी अनमोल रत्न-धन पा लिया है।"},"refrainFirst":true,"verses":[{"d":"वस्तु अमोलक दी मेरे सतगुरु, किरपा कर अपनायो॥","r":"Vastu amolak di mere Satguru, kirpa kar apnayo.","m":"My true Guru gave me something beyond price and, in his grace, made me his own.","h":"मेरे सतगुरु ने कृपा करके मुझे अपनाया और यह अनमोल वस्तु दी।"},{"d":"जनम जनम की पूँजी पाई, जग में सभी खोवायो॥","r":"Janam janam ki poonji paai, jag mein sabhi khovayo.","m":"I have found the treasure of many lifetimes, and let go of everything else in the world.","h":"मैंने जन्म-जन्मान्तर की पूँजी पा ली और संसार का सब कुछ छोड़ दिया।"},{"d":"खरचै न खूटै, चोर न लूटै, दिन दिन बढ़त सवायो॥","r":"Kharchai na khootai, chor na lootai, din din badhat savayo.","m":"Spending it does not use it up, thieves cannot steal it; it grows by a quarter every day.","h":"यह धन खर्च करने से घटता नहीं, चोर इसे लूट नहीं सकते; यह दिन-दिन सवाया बढ़ता जाता है।"},{"d":"सत की नाव खेवटिया सतगुरु, भवसागर तर आयो॥","r":"Sat ki naav khevatiya Satguru, bhavsagar tar aayo.","m":"In the boat of truth, with my Guru at the oars, I have crossed the ocean of worldly life.","h":"सत्य की नाव में, सतगुरु को खेवनहार बनाकर, मैं संसार-सागर से पार उतर आई।"},{"d":"मीरा के प्रभु गिरिधर नागर, हरख हरख जस गायो॥","r":"Meera ke prabhu Giridhar Nagar, harakh harakh jas gaayo.","m":"Meera’s Lord is Giridhar Nagar; overflowing with joy, she sings his praise.","h":"मीरा के प्रभु गिरिधर नागर हैं; वह आनन्द से भरकर उनका यश गाती है।"}]},{"id":"raghupati-raghav-raja-ram","kind":"bhajan","deity":"ram","lang":"hi","language":"Hindi","region":"All of India","title":{"d":"रघुपति राघव राजा राम","r":"Raghupati Raghav Raja Ram","en":"The Ram Dhun"},"auth":{"t":"Traditional Ram Dhun. The version with “ईश्वर अल्लाह तेरो नाम” was sung at Mahatma Gandhi’s prayer meetings.","c":"traditional"},"occ":["ram-navami","daily"],"when":"Sung in kirtan, at prayer meetings and school assemblies, and on 2 October.","form":"Dhun","notes":"Gandhi’s version was sung on the Salt March of 1930. Older devotional forms repeat only the names of Sita and Ram.","refrain":{"d":"रघुपति राघव राजाराम, पतित पावन सीताराम॥","r":"Raghupati Raghav Raja Ram, patit pavan Sitaram.","m":"Lord of the Raghus, King Ram, with Sita: purifier of the fallen.","h":"हे रघुकुल के स्वामी, राघव, राजा राम, सीता सहित राम, आप पतितों को पावन करने वाले हैं।"},"refrainFirst":true,"verses":[{"d":"सीताराम सीताराम, भज प्यारे तू सीताराम॥","r":"Sitaram Sitaram, bhaj pyare tu Sitaram.","m":"Sita-Ram, Sita-Ram: dear one, sing the names of Sita and Ram.","h":"सीताराम, सीताराम; हे प्यारे, तू सीताराम का भजन कर।"},{"d":"ईश्वर अल्लाह तेरो नाम, सब को सन्मति दे भगवान॥","r":"Ishwar Allah tero naam, sab ko sanmati de Bhagwan.","m":"Ishwar and Allah are both your names. Lord, give everyone wisdom and goodwill.","h":"ईश्वर और अल्लाह, दोनों आपके ही नाम हैं; हे भगवान, सबको सद्बुद्धि दीजिए।"}]},{"id":"thumak-chalat-ramchandra","kind":"bhajan","deity":"ram","lang":"hi","language":"Hindi","region":"All of North India","title":{"d":"ठुमक चलत रामचंद्र","r":"Thumak Chalat Ramchandra","en":"Baby Ram takes his first steps"},"auth":{"t":"Goswami Tulsidas, from the Gitavali","c":"attributed"},"occ":["ram-navami","daily"],"when":"Sung on Ram Navami and in Ram bhajans, picturing Ram as a toddler in Ayodhya.","dialect":"Braj Bhasha","refrain":{"d":"ठुमक चलत रामचंद्र बाजत पैंजनियाँ॥","r":"Thumak chalat Ramchandra baajat painjaniyan.","m":"Little Ramchandra toddles along, his anklets jingling.","h":"नन्हे रामचन्द्र ठुमक-ठुमक कर चल रहे हैं और उनकी पैंजनियाँ बज रही हैं।"},"refrainFirst":true,"verses":[{"d":"किलकि किलकि उठत धाय गिरत भूमि लटपटाय।\nधाय मात गोद लेत दशरथ की रनियाँ॥","r":"Kilaki kilaki uthat dhaay girat bhoomi latpataay,\nDhaay maat god let Dashrath ki raniyan.","m":"Squealing with laughter he gets up and runs, then stumbles and falls; Dasharath’s queens rush to gather him into their laps.","h":"वे किलकारी मारते हुए उठकर दौड़ते हैं और लड़खड़ाकर ज़मीन पर गिर पड़ते हैं; राजा दशरथ की रानियाँ दौड़कर उन्हें गोद में उठा लेती हैं।"},{"d":"अंचल रज अंग झारि विविध भाँति सो दुलारि।\nतन मन धन वारि वारि कहत मृदु बचनियाँ॥","r":"Anchal raj ang jhaari vividh bhaanti so dulaari,\nTan man dhan vaari vaari kahat mridu bachaniyan.","m":"With the ends of their saris they brush the dust from him and fuss over him in every way, giving their all to him and speaking soft words.","h":"वे अपने आँचल से उनके अंगों की धूल झाड़ती हैं, तरह-तरह से दुलार करती हैं, उन पर तन-मन-धन न्योछावर करती हैं और मीठे वचन बोलती हैं।"},{"d":"विद्रुम से अरुण अधर बोलत मुख मधुर मधुर।\nसुभग नासिका में चारु लटकत लटकनियाँ॥","r":"Vidrum se arun adhar bolat mukh madhur madhur,\nSubhag nasika mein charu latkat latkaniyan.","m":"His lips are red as coral as he babbles sweetly, and a pretty ornament dangles at his nose.","h":"मूँगे जैसे लाल होंठों से वे मीठी-मीठी तोतली बातें करते हैं, और सुन्दर नाक में प्यारा लटकन लटक रहा है।"},{"d":"तुलसीदास अति आनंद देख के मुखारविंद।\nरघुवर छबि के समान रघुवर छबि बनियाँ॥","r":"Tulsidas ati anand dekh ke mukharavind,\nRaghuvar chhabi ke saman Raghuvar chhabi baniyan.","m":"Tulsidas is overjoyed to see that lotus face: Raghuvar’s beauty can be compared only with Raghuvar’s beauty.","h":"उनका कमल जैसा मुख देखकर तुलसीदास को बहुत आनन्द होता है; रघुवर की छवि जैसी केवल रघुवर की ही छवि है।"}]},{"id":"vaishnav-jan-to","kind":"bhajan","deity":"vishnu","lang":"gu","language":"Gujarati","region":"Gujarat, and all of India through Gandhi’s prayer meetings","title":{"d":"वैष्णव जन तो तेने कहिये","r":"Vaishnav Jan To Tene Kahiye","en":"Who is a true devotee"},"auth":{"t":"Narsinh Mehta, 15th century. The last verse carries his name.","c":"known"},"occ":["daily"],"when":"Mahatma Gandhi’s favourite bhajan, sung at his prayer meetings and today at school assemblies and on 2 October.","notes":"Shown in Devanagari, as printed in most Hindi bhajan books. In Gujarati script it begins “વૈષ્ણવ જન તો તેને કહીએ”.","refrain":{"d":"वैष्णव जन तो तेने कहिये जे पीड पराई जाणे रे।\nपर दुःखे उपकार करे तो ये मन अभिमान न आणे रे॥","r":"Vaishnav jan to tene kahiye je peed parai jaane re,\nPar dukhe upkar kare to ye man abhiman na aane re.","m":"Call that person a true devotee who feels the pain of others, who helps those in sorrow and never lets pride into the mind.","h":"सच्चा वैष्णव उसी को कहना चाहिए जो दूसरों की पीड़ा को समझता है, दुःख में दूसरों की सहायता करता है और फिर भी मन में अभिमान नहीं लाता।"},"refrainFirst":true,"verses":[{"d":"सकळ लोकमां सहुने वंदे, निंदा न करे केनी रे।\nवाच काछ मन निश्चळ राखे, धन धन जननी तेनी रे॥","r":"Sakal lokman sahune vande, ninda na kare keni re,\nVach kachh man nishchal rakhe, dhan dhan janani teni re.","m":"Such a person honours everyone in the world and speaks ill of no one, and keeps word, deed and mind steady. Blessed, blessed is the mother who bore them.","h":"वह संसार में सबको आदर देता है और किसी की निन्दा नहीं करता; वाणी, कर्म और मन को स्थिर रखता है। ऐसे व्यक्ति की माता धन्य है।"},{"d":"समदृष्टि ने तृष्णा त्यागी, परस्त्री जेने मात रे।\nजिह्वा थकी असत्य न बोले, परधन नव झाले हाथ रे॥","r":"Samdrishti ne trushna tyagi, parstri jene maat re,\nJihva thaki asatya na bole, pardhan nav jhale haath re.","m":"They see all with an equal eye and have given up craving; every other woman is a mother to them. Their tongue never tells a lie, and their hand never takes another’s wealth.","h":"वह सबको समान दृष्टि से देखता है और तृष्णा छोड़ चुका है; पराई स्त्री उसके लिए माता समान है। उसकी जीभ कभी झूठ नहीं बोलती और उसका हाथ पराया धन नहीं छूता।"},{"d":"मोह माया व्यापे नहि जेने, दृढ वैराग्य जेना मनमां रे।\nरामनाम शुं ताळी लागी, सकळ तीरथ तेना तनमां रे॥","r":"Moh maya vyape nahi jene, dridh vairagya jena manman re,\nRamnaam shun tali lagi, sakal tirath tena tanman re.","m":"Delusion and illusion cannot touch them; firm detachment fills their mind. They are absorbed in the name of Ram, and every place of pilgrimage lives within them.","h":"मोह और माया उसे नहीं व्यापते, उसके मन में दृढ़ वैराग्य है। उसकी लगन राम-नाम में लगी है, और सारे तीर्थ उसके शरीर में बसते हैं।"},{"d":"वणलोभी ने कपटरहित छे, काम क्रोध निवार्या रे।\nभणे नरसैयो तेनुं दरसन करतां, कुळ एकोतेर तार्या रे॥","r":"Vanlobhi ne kapatrahit chhe, kaam krodh nivarya re,\nBhane Narsaiyo tenun darsan kartan, kul ekoter tarya re.","m":"They are free of greed and deceit, and have overcome lust and anger. Narsinh says: just seeing such a person saves seventy-one generations of one’s family.","h":"वह लोभ और कपट से रहित है, उसने काम और क्रोध को जीत लिया है। नरसी कहते हैं, ऐसे व्यक्ति के दर्शन से इकहत्तर पीढ़ियाँ तर जाती हैं।"}]},{"id":"durga-chalisa","kind":"chalisa","deity":"durga","lang":"hi","language":"Hindi","region":"All of North India","title":{"d":"श्री दुर्गा चालीसा","r":"Shri Durga Chalisa","en":"Forty verses in praise of Maa Durga"},"auth":{"t":"Devidas, whose name is in the last chaupai","c":"attributed"},"occ":["navratri","daily"],"when":"Recited every day of Navratri, usually before Jai Ambe Gauri, and on Tuesdays and Fridays through the year.","dialect":"Awadhi and Braj","notes":"Editions differ in places. The thirty-sixth chaupai is printed either as “रिपु मूरख मोहि अति डर पावें” or “मोह मदादिक सब बिनशावें”, and the closing lines vary from book to book. Most printings have forty-one chaupais rather than exactly forty. The eleventh chaupai names हिरण्याक्ष, as most books print it, although in the Narsingh story the demon is his brother Hiranyakashipu.","refrain":null,"refrainFirst":true,"verses":[{"d":"नमो नमो दुर्गे सुख करनी।\nनमो नमो अम्बे दुःख हरनी॥","r":"Namo namo Durge sukh karani,\nNamo namo Ambe dukh harani.","m":"I bow again and again to you, Durga, giver of happiness; I bow again and again to you, Mother Ambe, remover of sorrow.","h":"हे सुख देने वाली दुर्गा माँ, आपको बार-बार नमस्कार है। हे दुःख हरने वाली अम्बे माँ, आपको बार-बार नमस्कार है।"},{"d":"निरंकार है ज्योति तुम्हारी।\nतिहूँ लोक फैली उजियारी॥","r":"Nirankar hai jyoti tumhari,\nTihun lok phaili ujiyari.","m":"Your light is formless, and its brightness has spread through the three worlds.","h":"आपकी ज्योति निराकार है, और उसका प्रकाश तीनों लोकों में फैला हुआ है।"},{"d":"शशि ललाट मुख महाविशाला।\nनेत्र लाल भृकुटि विकराला॥","r":"Shashi lalat mukh mahavishala,\nNetra lal bhrikuti vikarala.","m":"The moon is on your brow and your face is broad and majestic; your eyes are red and your frown is fearsome.","h":"आपके मस्तक पर चन्द्रमा है और मुख अत्यन्त विशाल है; आपके नेत्र लाल हैं और भौंहें भयंकर हैं।"},{"d":"रूप मातु को अधिक सुहावे।\nदरश करत जन अति सुख पावे॥","r":"Roop matu ko adhik suhave,\nDarash karat jan ati sukh pave.","m":"The Mother’s form is utterly lovely; those who see it are filled with joy.","h":"माता का रूप अत्यन्त सुहावना है; जो उनके दर्शन करता है, वह बहुत सुख पाता है।"},{"d":"तुम संसार शक्ति लय कीना।\nपालन हेतु अन्न धन दीना॥","r":"Tum sansar shakti lay keena,\nPalan hetu ann dhan deena.","m":"You hold all the power of the world within you, and to sustain it you gave grain and wealth.","h":"आपने संसार की सारी शक्ति अपने में समा रखी है, और उसके पालन के लिए अन्न और धन दिया है।"},{"d":"अन्नपूर्णा हुई जग पाला।\nतुम ही आदि सुन्दरी बाला॥","r":"Annapurna hui jag pala,\nTum hi aadi sundari bala.","m":"As Annapurna you nourish the world; you are the primordial beauty, the eternal maiden.","h":"अन्नपूर्णा बनकर आप जगत का पालन करती हैं; आप ही आदि सुन्दरी बाला हैं।"},{"d":"प्रलयकाल सब नाशन हारी।\nतुम गौरी शिवशंकर प्यारी॥","r":"Pralaykal sab nashan hari,\nTum Gauri Shivshankar pyari.","m":"At the dissolution of the world you are the one who ends all things; you are Gauri, beloved of Shiv Shankar.","h":"प्रलय के समय आप ही सबका नाश करने वाली हैं; आप ही शिवशंकर की प्रिय गौरी हैं।"},{"d":"शिव योगी तुम्हरे गुण गावें।\nब्रह्मा विष्णु तुम्हें नित ध्यावें॥","r":"Shiv yogi tumhare gun gaven,\nBrahma Vishnu tumhen nit dhyaven.","m":"Shiv and the yogis sing your glories, and Brahma and Vishnu meditate on you every day.","h":"शिवजी और योगीजन आपके गुण गाते हैं, और ब्रह्मा तथा विष्णु नित्य आपका ध्यान करते हैं।"},{"d":"रूप सरस्वती को तुम धारा।\nदे सुबुद्धि ऋषि मुनिन उबारा॥","r":"Roop Saraswati ko tum dhara,\nDe subuddhi rishi munin ubara.","m":"You took the form of Saraswati and, giving them wisdom, saved the rishis and sages.","h":"आपने सरस्वती का रूप धारण किया और ऋषि-मुनियों को सद्बुद्धि देकर उनका उद्धार किया।"},{"d":"धरयो रूप नरसिंह को अम्बा।\nपरगट भई फाड़कर खम्बा॥","r":"Dharyo roop Narsingh ko Amba,\nPargat bhai phadkar khamba.","m":"Mother, you took the form of Narsingh and appeared by bursting out of the pillar.","h":"हे माँ अम्बे, आपने नरसिंह का रूप धारण किया और खम्भा फाड़कर प्रकट हुईं।"},{"d":"रक्षा करि प्रह्लाद बचायो।\nहिरण्याक्ष को स्वर्ग पठायो॥","r":"Raksha kari Prahlad bachayo,\nHiranyaksh ko swarg pathayo.","m":"You protected and saved Prahlad, and sent the demon king to heaven by slaying him.","h":"आपने रक्षा करके प्रह्लाद को बचाया और असुर राजा (हिरण्यकशिपु) का वध करके उसे स्वर्ग भेज दिया।"},{"d":"लक्ष्मी रूप धरो जग माहीं।\nश्री नारायण अंग समाहीं॥","r":"Lakshmi roop dharo jag mahin,\nShri Narayan ang samahin.","m":"You took the form of Lakshmi in the world and dwell at the side of Shri Narayan.","h":"आपने संसार में लक्ष्मी का रूप धारण किया और श्री नारायण के अंग में समाई रहती हैं।"},{"d":"क्षीरसिन्धु में करत विलासा।\nदयासिन्धु दीजै मन आसा॥","r":"Ksheersindhu mein karat vilasa,\nDayasindhu deejai man aasa.","m":"You delight in the ocean of milk; ocean of mercy, fulfil the hopes of my heart.","h":"आप क्षीरसागर में विहार करती हैं; हे दया की सागर, मेरे मन की आशा पूरी कीजिए।"},{"d":"हिंगलाज में तुम्हीं भवानी।\nमहिमा अमित न जात बखानी॥","r":"Hinglaj mein tumhin Bhavani,\nMahima amit na jat bakhani.","m":"You are Bhavani of Hinglaj; your boundless glory cannot be described.","h":"हिंगलाज में आप ही भवानी के रूप में विराजती हैं; आपकी अपार महिमा का वर्णन नहीं किया जा सकता।"},{"d":"मातंगी अरु धूमावति माता।\nभुवनेश्वरी बगला सुख दाता॥","r":"Matangi aru Dhumavati Mata,\nBhuvaneshwari Bagla sukh data.","m":"You are Mother Matangi and Dhumavati; as Bhuvaneshwari and Bagla you give happiness.","h":"आप ही मातंगी और धूमावती माता हैं; आप ही भुवनेश्वरी और बगलामुखी बनकर सुख देती हैं।"},{"d":"श्री भैरव तारा जग तारिणी।\nछिन्न भाल भव दुःख निवारिणी॥","r":"Shri Bhairav Tara jag tarini,\nChhinn bhal bhav dukh nivarini.","m":"As Bhairavi and Tara you carry the world across; as Chhinnamasta you end the sorrows of worldly life.","h":"भैरवी और तारा बनकर आप जगत को तारती हैं; छिन्नमस्ता बनकर आप संसार के दुःख दूर करती हैं।"},{"d":"केहरि वाहन सोह भवानी।\nलांगुर वीर चलत अगवानी॥","r":"Kehari vahan soh Bhavani,\nLangur veer chalat agvani.","m":"Bhavani looks splendid riding the lion, and the brave Langur Veer walks ahead of her.","h":"सिंह पर सवार भवानी शोभा पाती हैं, और वीर लांगुर (हनुमान) उनके आगे-आगे चलते हैं।"},{"d":"कर में खप्पर खड्ग विराजै।\nजाको देख काल डर भाजै॥","r":"Kar mein khappar khadg virajai,\nJako dekh kal dar bhajai.","m":"A skull-bowl and a sword shine in your hands; seeing them, even Death runs in fear.","h":"आपके हाथों में खप्पर और खड्ग सुशोभित हैं, जिन्हें देखकर काल भी डरकर भाग जाता है।"},{"d":"सोहै अस्त्र और त्रिशूला।\nजाते उठत शत्रु हिय शूला॥","r":"Sohai astra aur trishula,\nJate uthat shatru hiy shula.","m":"Weapons and the trident adorn you, and at the sight of them pain rises in the hearts of enemies.","h":"आपके अस्त्र और त्रिशूल शोभा पाते हैं, जिन्हें देखकर शत्रुओं के हृदय में पीड़ा उठती है।"},{"d":"नगरकोट में तुम्हीं विराजत।\nतिहुँलोक में डंका बाजत॥","r":"Nagarkot mein tumhin virajat,\nTihunlok mein danka bajat.","m":"You dwell at Nagarkot, and your drum resounds through the three worlds.","h":"नगरकोट (कांगड़ा) में आप ही विराजमान हैं, और तीनों लोकों में आपका डंका बजता है।"},{"d":"शुम्भ निशुम्भ दानव तुम मारे।\nरक्तबीज शंखन संहारे॥","r":"Shumbh Nishumbh danav tum mare,\nRaktabeej shankhan sanhare.","m":"You slew the demons Shumbh and Nishumbh, and destroyed Raktabeej and his countless doubles.","h":"आपने शुम्भ और निशुम्भ दानवों को मारा, और रक्तबीज तथा उसके असंख्य रूपों का संहार किया।"},{"d":"महिषासुर नृप अति अभिमानी।\nजेहि अघ भार मही अकुलानी॥","r":"Mahishasur nrip ati abhimani,\nJehi agh bhar mahi akulani.","m":"King Mahishasur was utterly arrogant, and the earth groaned under the weight of his sins.","h":"राजा महिषासुर अत्यन्त अभिमानी था, जिसके पापों के बोझ से पृथ्वी व्याकुल हो उठी थी।"},{"d":"रूप कराल कालिका धारा।\nसेन सहित तुम तिहि संहारा॥","r":"Roop karal Kalika dhara,\nSen sahit tum tihi sanhara.","m":"You took the terrible form of Kalika and destroyed him along with his army.","h":"आपने काली का भयंकर रूप धारण किया और उसे उसकी सेना सहित नष्ट कर दिया।"},{"d":"परी गाढ़ सन्तन पर जब जब।\nभई सहाय मातु तुम तब तब॥","r":"Pari gaadh santan par jab jab,\nBhai sahay matu tum tab tab.","m":"Whenever hard times fell on the saints, Mother, you came to their help.","h":"जब-जब संतों पर संकट पड़ा, तब-तब हे माता, आपने उनकी सहायता की।"},{"d":"अमरपुरी अरु बासव लोका।\nतब महिमा सब रहें अशोका॥","r":"Amarpuri aru Basav loka,\nTab mahima sab rahen ashoka.","m":"By your glory the city of the immortals and Indra’s realm all remain free of sorrow.","h":"आपकी महिमा से देवताओं की नगरी और इन्द्रलोक सब शोकरहित रहते हैं।"},{"d":"ज्वाला में है ज्योति तुम्हारी।\nतुम्हें सदा पूजें नर-नारी॥","r":"Jvala mein hai jyoti tumhari,\nTumhen sada pujen nar-nari.","m":"Your flame burns at Jwalaji, and men and women worship you always.","h":"ज्वालाजी में आपकी ज्योति जलती है, और सभी नर-नारी सदा आपकी पूजा करते हैं।"},{"d":"प्रेम भक्ति से जो यश गावें।\nदुःख दारिद्र निकट नहिं आवें॥","r":"Prem bhakti se jo yash gaven,\nDukh daridra nikat nahin aaven.","m":"Sorrow and poverty never come near those who sing your glory with loving devotion.","h":"जो प्रेम और भक्ति से आपका यश गाते हैं, उनके पास दुःख और दरिद्रता नहीं आते।"},{"d":"ध्यावे तुम्हें जो नर मन लाई।\nजन्म-मरण ताकौ छुटि जाई॥","r":"Dhyave tumhen jo nar man laai,\nJanm-maran takau chhuti jaai.","m":"Whoever meditates on you with a focused mind is freed from birth and death.","h":"जो मनुष्य मन लगाकर आपका ध्यान करता है, वह जन्म-मरण के बन्धन से छूट जाता है।"},{"d":"जोगी सुर मुनि कहत पुकारी।\nयोग न हो बिन शक्ति तुम्हारी॥","r":"Jogi sur muni kahat pukari,\nYog na ho bin shakti tumhari.","m":"Yogis, gods and sages declare aloud that without your power there can be no yoga.","h":"योगी, देवता और मुनि पुकार-पुकार कर कहते हैं कि आपकी शक्ति के बिना योग सिद्ध नहीं होता।"},{"d":"शंकर आचारज तप कीनो।\nकाम अरु क्रोध जीति सब लीनो॥","r":"Shankar Aacharaj tap keeno,\nKaam aru krodh jeeti sab leeno.","m":"Shankaracharya performed austerities and conquered desire and anger.","h":"शंकराचार्य ने तप किया और काम तथा क्रोध सबको जीत लिया।"},{"d":"निशिदिन ध्यान धरो शंकर को।\nकाहु काल नहिं सुमिरो तुमको॥","r":"Nishidin dhyan dharo Shankar ko,\nKahu kal nahin sumiro tumko.","m":"Day and night he meditated on Shankar, but never once remembered you.","h":"वे दिन-रात भगवान शंकर का ध्यान करते रहे, पर कभी आपका स्मरण नहीं किया।"},{"d":"शक्ति रूप का मरम न पायो।\nशक्ति गई तब मन पछितायो॥","r":"Shakti roop ka maram na payo,\nShakti gayi tab man pachhitayo.","m":"He did not grasp the secret of your form as Shakti; when his strength left him, he repented.","h":"उन्होंने आपके शक्ति-रूप का रहस्य नहीं समझा; जब उनकी शक्ति चली गई, तब उनका मन पछताया।"},{"d":"शरणागत हुई कीर्ति बखानी।\nजय जय जय जगदम्ब भवानी॥","r":"Sharanagat hui kirti bakhani,\nJai jai jai Jagdamb Bhavani.","m":"Taking refuge in you, he sang your praise: “Victory, victory, victory to Jagdamba Bhavani!”","h":"तब उन्होंने आपकी शरण लेकर आपकी कीर्ति गाई: “जय जय जय जगदम्बा भवानी!”"},{"d":"भई प्रसन्न आदि जगदम्बा।\nदई शक्ति नहिं कीन विलम्बा॥","r":"Bhai prasann aadi Jagdamba,\nDai shakti nahin keen vilamba.","m":"The primal Mother of the world was pleased and gave him back his strength without delay.","h":"आदि जगदम्बा प्रसन्न हुईं और बिना देर किए उन्हें शक्ति लौटा दी।"},{"d":"मोको मातु कष्ट अति घेरो।\nतुम बिन कौन हरै दुःख मेरो॥","r":"Moko matu kasht ati ghero,\nTum bin kaun harai dukh mero.","m":"Mother, great troubles surround me; who but you can take away my sorrow?","h":"हे माता, मुझे बहुत कष्टों ने घेर रखा है; आपके बिना मेरा दुःख कौन हरेगा?"},{"d":"आशा तृष्णा निपट सतावें।\nरिपु मूरख मोहि अति डर पावें॥","r":"Aasha trishna nipat sataven,\nRipu moorakh mohi ati dar paven.","m":"Hope and craving torment me endlessly, and foolish enemies frighten me greatly.","h":"आशा और तृष्णा मुझे बहुत सताती हैं, और मूर्ख शत्रु मुझे बहुत डराते हैं।"},{"d":"शत्रु नाश कीजै महारानी।\nसुमिरौं इकचित तुम्हें भवानी॥","r":"Shatru naash keejai Maharani,\nSumiraun ikchit tumhen Bhavani.","m":"Great Queen, destroy my enemies; Bhavani, I remember you with a single mind.","h":"हे महारानी, मेरे शत्रुओं का नाश कीजिए; हे भवानी, मैं एकाग्र मन से आपका स्मरण करता हूँ।"},{"d":"करो कृपा हे मातु दयाला।\nऋद्धि-सिद्धि दै करहु निहाला॥","r":"Karo kripa he matu dayala,\nRiddhi-siddhi dai karahu nihala.","m":"Be gracious, compassionate Mother; grant me prosperity and success and make me fulfilled.","h":"हे दयालु माता, कृपा कीजिए; ऋद्धि-सिद्धि देकर मुझे निहाल कर दीजिए।"},{"d":"जब लगि जिऊँ दया फल पाऊँ।\nतुम्हरो यश मैं सदा सुनाऊँ॥","r":"Jab lagi jiun daya phal paun,\nTumharo yash main sada sunaun.","m":"As long as I live, may I receive the fruit of your mercy, and may I always tell of your glory.","h":"जब तक मैं जीवित रहूँ, आपकी दया का फल पाता रहूँ और सदा आपका यश सुनाता रहूँ।"},{"d":"श्री दुर्गा चालीसा जो कोई गावै।\nसब सुख भोग परमपद पावै॥","r":"Shri Durga Chalisa jo koi gavai,\nSab sukh bhog parampad pavai.","m":"Whoever sings this Shri Durga Chalisa enjoys every happiness and reaches the highest state.","h":"जो कोई यह श्री दुर्गा चालीसा गाता है, वह सब सुख भोगकर परमपद पाता है।"},{"d":"देवीदास शरण निज जानी।\nकरहु कृपा जगदम्ब भवानी॥","r":"Devidas sharan nij jani,\nKarahu kripa Jagdamb Bhavani.","m":"Knowing Devidas to be in your refuge, Jagdamba Bhavani, be gracious to him.","h":"देवीदास को अपनी शरण में जानकर, हे जगदम्बा भवानी, उस पर कृपा कीजिए।"}]},{"id":"hanuman-chalisa","kind":"chalisa","deity":"hanuman","lang":"hi","language":"Hindi","region":"All of North India, and wherever Hindi speakers live","title":{"d":"हनुमान चालीसा","r":"Hanuman Chalisa","en":"Forty verses in praise of Shri Hanuman"},"auth":{"t":"Goswami Tulsidas, 16th century. The fortieth chaupai carries his name.","c":"attributed"},"occ":["hanuman-jayanti","sundarkand","daily"],"when":"Recited on Tuesdays and Saturdays, morning or night, and in any time of fear or difficulty. On special days many recite it seven, eleven or a hundred and eight times.","dialect":"Awadhi","notes":"Editions differ in small ways, for example “संकर सुवन केसरीनंदन” or “शंकर स्वयं केसरीनंदन” in the sixth chaupai. The two dohas at the start and the one at the end are part of the text but not counted among the forty.","refrain":null,"refrainFirst":true,"verses":[{"d":"श्रीगुरु चरन सरोज रज, निज मनु मुकुरु सुधारि।\nबरनउँ रघुबर बिमल जसु, जो दायकु फल चारि॥","r":"Shriguru charan saroj raj, nij manu mukuru sudhari,\nBaranaun Raghubar bimal jasu, jo dayaku phal chari.","m":"Cleaning the mirror of my mind with the dust of my Guru’s lotus feet, I sing the spotless glory of Shri Ram, which grants the four aims of life.","h":"श्री गुरु के चरणकमलों की धूल से अपने मन रूपी दर्पण को स्वच्छ करके, मैं श्री रघुवीर के निर्मल यश का वर्णन करता हूँ, जो चारों फल (धर्म, अर्थ, काम, मोक्ष) देने वाला है।","n":"दोहा"},{"d":"बुद्धिहीन तनु जानिके, सुमिरौं पवन-कुमार।\nबल बुधि बिद्या देहु मोहिं, हरहु कलेस बिकार॥","r":"Buddhiheen tanu janike, sumiraun Pavan-kumar,\nBal buddhi bidya dehu mohin, harahu kalesh bikar.","m":"Knowing how little wisdom I have, I remember the son of the Wind. Give me strength, understanding and knowledge, and take away my troubles and faults.","h":"अपने आप को बुद्धिहीन जानकर मैं पवनपुत्र हनुमान का स्मरण करता हूँ। हे प्रभु, मुझे बल, बुद्धि और विद्या दीजिए और मेरे क्लेश और विकार दूर कीजिए।","n":"दोहा"},{"d":"जय हनुमान ज्ञान गुन सागर।\nजय कपीस तिहुँ लोक उजागर॥","r":"Jai Hanuman gyan gun sagar,\njai Kapis tihun lok ujagar.","m":"Victory to Hanuman, ocean of wisdom and virtue! Victory to the lord of the monkeys, whose light fills the three worlds.","h":"हे ज्ञान और गुणों के सागर हनुमान, आपकी जय हो! हे वानरों के स्वामी, तीनों लोकों को प्रकाशित करने वाले, आपकी जय हो!"},{"d":"राम दूत अतुलित बल धामा।\nअंजनि-पुत्र पवनसुत नामा॥","r":"Ram doot atulit bal dhama,\nAnjani-putra Pavansut nama.","m":"Ram’s messenger, home of matchless strength, known as Anjani’s son and the son of the Wind.","h":"आप श्री राम के दूत और अतुलित बल के धाम हैं; आप अंजनीपुत्र और पवनसुत नाम से जाने जाते हैं।"},{"d":"महाबीर बिक्रम बजरंगी।\nकुमति निवार सुमति के संगी॥","r":"Mahabir bikram Bajrangi,\nkumati nivar sumati ke sangi.","m":"Great hero, mighty one with a body like a thunderbolt, you drive away bad thoughts and stand beside good sense.","h":"हे महावीर, पराक्रमी, वज्र जैसे अंगों वाले, आप बुरी बुद्धि को दूर करते हैं और अच्छी बुद्धि वालों के साथी हैं।"},{"d":"कंचन बरन बिराज सुबेसा।\nकानन कुंडल कुंचित केसा॥","r":"Kanchan baran biraj subesa,\nkanan kundal kunchit kesa.","m":"Golden in colour and finely dressed, with rings in your ears and curling hair.","h":"आपका रंग सोने जैसा है और आप सुन्दर वेश में शोभा पाते हैं; कानों में कुण्डल और बाल घुँघराले हैं।"},{"d":"हाथ बज्र औ ध्वजा बिराजै।\nकाँधे मूँज जनेऊ साजै॥","r":"Haath bajra au dhwaja birajai,\nkaandhe moonj janeu saajai.","m":"The thunderbolt and the banner shine in your hands, and a sacred thread of munja grass crosses your shoulder.","h":"आपके हाथों में वज्र और ध्वजा शोभा पाते हैं और कन्धे पर मूँज का जनेऊ सजा है।"},{"d":"संकर सुवन केसरीनंदन।\nतेज प्रताप महा जग बंदन॥","r":"Sankar suvan Kesarinandan,\ntej pratap maha jag bandan.","m":"Born of Shankar, joy of Kesari, the whole world bows to your radiance and might.","h":"आप शंकर के अवतार और केसरी के पुत्र हैं; आपके तेज और प्रताप की सारा जगत वन्दना करता है।"},{"d":"बिद्यावान गुनी अति चातुर।\nराम काज करिबे को आतुर॥","r":"Bidyavan guni ati chatur,\nRam kaj karibe ko aatur.","m":"Learned, virtuous and wise, you are always eager to do Ram’s work.","h":"आप विद्वान, गुणवान और अत्यन्त चतुर हैं, और श्री राम के काम करने के लिए सदा उत्सुक रहते हैं।"},{"d":"प्रभु चरित्र सुनिबे को रसिया।\nराम लखन सीता मन बसिया॥","r":"Prabhu charitra sunibe ko rasiya,\nRam Lakhan Sita man basiya.","m":"You delight in hearing the Lord’s story, and Ram, Lakshman and Sita live in your heart.","h":"आप प्रभु श्री राम का चरित्र सुनने के रसिया हैं; राम, लक्ष्मण और सीता आपके मन में बसते हैं।"},{"d":"सूक्ष्म रूप धरि सियहिं दिखावा।\nबिकट रूप धरि लंक जरावा॥","r":"Sukshma roop dhari Siyahin dikhava,\nbikat roop dhari Lank jarava.","m":"Taking a tiny form you appeared before Sita; taking a terrible form you set Lanka on fire.","h":"आपने छोटा रूप धारण करके सीताजी को दर्शन दिए और विकट रूप धारण करके लंका को जलाया।"},{"d":"भीम रूप धरि असुर सँहारे।\nरामचंद्र के काज सँवारे॥","r":"Bheem roop dhari asur sanhare,\nRamchandra ke kaj sanvare.","m":"Taking a fearsome form you destroyed the demons and completed Ramchandra’s work.","h":"आपने भयंकर रूप धारण करके असुरों का संहार किया और श्री रामचन्द्र के कार्य सँवारे।"},{"d":"लाय सजीवन लखन जियाये।\nश्रीरघुबीर हरषि उर लाये॥","r":"Laay Sajivan Lakhan jiyaye,\nShri Raghubir harashi ur laye.","m":"You brought the Sanjivani herb and revived Lakshman, and Shri Ram held you to his heart in joy.","h":"आपने संजीवनी बूटी लाकर लक्ष्मण को जीवित किया, और श्री रघुवीर ने हर्षित होकर आपको हृदय से लगा लिया।"},{"d":"रघुपति कीन्ही बहुत बड़ाई।\nतुम मम प्रिय भरतहि सम भाई॥","r":"Raghupati keenhi bahut badai,\ntum mam priya Bharatahi sam bhai.","m":"Raghupati praised you greatly: “You are as dear to me as my brother Bharat.”","h":"श्री रघुपति ने आपकी बहुत प्रशंसा की और कहा, “तुम मुझे भरत के समान प्रिय भाई हो।”"},{"d":"सहस बदन तुम्हरो जस गावैं।\nअस कहि श्रीपति कंठ लगावैं॥","r":"Sahas badan tumharo jas gavain,\nas kahi Shripati kanth lagavain.","m":"“May the thousand-mouthed Shesh sing your praise,” said the Lord, and embraced you.","h":"“हज़ार मुखों वाले शेषनाग तुम्हारा यश गाएँ,” ऐसा कहकर श्री राम ने आपको गले से लगा लिया।"},{"d":"सनकादिक ब्रह्मादि मुनीसा।\nनारद सारद सहित अहीसा॥","r":"Sanakadik Brahmadi munisa,\nNarad Sarad sahit Ahisa.","m":"Sanaka and the sages, Brahma and the gods, Narad, Saraswati and the king of serpents,","h":"सनक आदि ऋषि, ब्रह्मा आदि देवता, मुनीश्वर, नारद, सरस्वती और शेषनाग,"},{"d":"जम कुबेर दिगपाल जहाँ ते।\nकबि कोबिद कहि सके कहाँ ते॥","r":"Jam Kuber Digpal jahan te,\nkabi kobid kahi sake kahan te.","m":"Yama, Kuber and the guardians of the directions cannot describe your glory, so how could poets and scholars?","h":"यमराज, कुबेर और सब दिशाओं के रक्षक भी जब आपके यश का वर्णन नहीं कर सकते, तो कवि और विद्वान कैसे कर सकते हैं?"},{"d":"तुम उपकार सुग्रीवहिं कीन्हा।\nराम मिलाय राज पद दीन्हा॥","r":"Tum upkar Sugrivahin keenha,\nRam milay raj pad deenha.","m":"You did Sugriv a great service: you brought him to Ram, and he regained his throne.","h":"आपने सुग्रीव पर उपकार किया; उन्हें श्री राम से मिलाया और राजपद दिलाया।"},{"d":"तुम्हरो मंत्र बिभीषन माना।\nलंकेस्वर भए सब जग जाना॥","r":"Tumharo mantra Bibhishan mana,\nLankeshwar bhaye sab jag jana.","m":"Vibhishan took your advice and became king of Lanka, as the whole world knows.","h":"विभीषण ने आपकी सलाह मानी और वे लंका के राजा बने, यह सारा संसार जानता है।"},{"d":"जुग सहस्र जोजन पर भानू।\nलील्यो ताहि मधुर फल जानू॥","r":"Jug sahasra jojan par bhanu,\nleelyo tahi madhur phal janu.","m":"The sun, thousands of leagues away, you swallowed, taking it for a sweet fruit.","h":"हज़ारों योजन दूर स्थित सूर्य को आपने मीठा फल समझकर निगल लिया था।"},{"d":"प्रभु मुद्रिका मेलि मुख माहीं।\nजलधि लाँघि गये अचरज नाहीं॥","r":"Prabhu mudrika meli mukh mahin,\njaladhi laanghi gaye achraj nahin.","m":"With the Lord’s ring in your mouth you leapt across the ocean. No wonder in that!","h":"प्रभु की अँगूठी मुँह में रखकर आप समुद्र लाँघ गए, इसमें कोई आश्चर्य नहीं।"},{"d":"दुर्गम काज जगत के जेते।\nसुगम अनुग्रह तुम्हरे तेते॥","r":"Durgam kaj jagat ke jete,\nsugam anugrah tumhre tete.","m":"Every hard task in the world becomes easy by your grace.","h":"संसार के जितने भी कठिन काम हैं, वे आपकी कृपा से सरल हो जाते हैं।"},{"d":"राम दुआरे तुम रखवारे।\nहोत न आज्ञा बिनु पैसारे॥","r":"Ram duare tum rakhvare,\nhot na agya binu paisare.","m":"You guard Ram’s door; no one enters without your leave.","h":"आप श्री राम के द्वार के रखवाले हैं; आपकी आज्ञा के बिना कोई भीतर प्रवेश नहीं कर सकता।"},{"d":"सब सुख लहै तुम्हारी सरना।\nतुम रच्छक काहू को डर ना॥","r":"Sab sukh lahai tumhari sarna,\ntum rakshak kahu ko dar na.","m":"Those who take refuge in you find every happiness. With you as protector, there is nothing to fear.","h":"आपकी शरण में आने वाला सब सुख पाता है; जब आप रक्षक हैं, तो किसी का डर नहीं।"},{"d":"आपन तेज सम्हारो आपै।\nतीनों लोक हाँक तें काँपै॥","r":"Aapan tej samharo aapai,\nteenon lok haank te kaanpai.","m":"Only you can hold your own power; the three worlds tremble at your roar.","h":"अपने तेज को आप ही सँभाल सकते हैं; आपकी एक हाँक से तीनों लोक काँप उठते हैं।"},{"d":"भूत पिसाच निकट नहिं आवै।\nमहाबीर जब नाम सुनावै॥","r":"Bhoot pisach nikat nahin aavai,\nMahabir jab naam sunavai.","m":"Ghosts and evil spirits stay away when the great hero’s name is spoken.","h":"जहाँ महावीर हनुमान का नाम सुनाया जाता है, वहाँ भूत-पिशाच पास नहीं आते।"},{"d":"नासै रोग हरै सब पीरा।\nजपत निरंतर हनुमत बीरा॥","r":"Nasai rog harai sab peera,\njapat nirantar Hanumat beera.","m":"Illness ends and every pain is removed by constantly repeating the name of brave Hanuman.","h":"वीर हनुमान का निरन्तर जप करने से रोग नष्ट होते हैं और सब पीड़ा दूर होती है।"},{"d":"संकट तें हनुमान छुड़ावै।\nमन क्रम बचन ध्यान जो लावै॥","r":"Sankat te Hanuman chhudavai,\nman kram bachan dhyan jo lavai.","m":"Hanuman frees from trouble all who remember him in thought, deed and word.","h":"जो मन, कर्म और वचन से हनुमानजी का ध्यान करता है, उसे वे संकट से छुड़ाते हैं।"},{"d":"सब पर राम तपस्वी राजा।\nतिन के काज सकल तुम साजा॥","r":"Sab par Ram tapasvi raja,\ntin ke kaj sakal tum saja.","m":"Ram, the ascetic king, is above all, and you carried out all his work.","h":"तपस्वी राजा श्री राम सबसे ऊपर हैं, और आपने उनके सारे काम पूरे किए।"},{"d":"और मनोरथ जो कोई लावै।\nसोइ अमित जीवन फल पावै॥","r":"Aur manorath jo koi lavai,\nsoi amit jeevan phal pavai.","m":"Whoever comes to you with any wish receives the boundless fruit of life.","h":"जो कोई भी मनोरथ लेकर आपके पास आता है, वह जीवन का अपार फल पाता है।"},{"d":"चारों जुग परताप तुम्हारा।\nहै परसिद्ध जगत उजियारा॥","r":"Charon jug partap tumhara,\nhai parsiddh jagat ujiyara.","m":"Your glory shines through all four ages and lights up the world.","h":"चारों युगों में आपका प्रताप है, और आपकी कीर्ति संसार में प्रकाश की तरह प्रसिद्ध है।"},{"d":"साधु संत के तुम रखवारे।\nअसुर निकंदन राम दुलारे॥","r":"Sadhu sant ke tum rakhvare,\nasur nikandan Ram dulare.","m":"You protect the good and the saintly, destroy demons, and are dear to Ram.","h":"आप साधु-संतों के रखवाले, असुरों का नाश करने वाले और श्री राम के दुलारे हैं।"},{"d":"अष्ट सिद्धि नौ निधि के दाता।\nअस बर दीन जानकी माता॥","r":"Ashta siddhi nau nidhi ke data,\nas bar deen Janaki mata.","m":"Mother Janaki blessed you to be the giver of the eight powers and the nine treasures.","h":"माता जानकी ने आपको यह वरदान दिया है कि आप आठों सिद्धियाँ और नौ निधियाँ देने वाले होंगे।"},{"d":"राम रसायन तुम्हरे पासा।\nसदा रहो रघुपति के दासा॥","r":"Ram rasayan tumhre pasa,\nsada raho Raghupati ke dasa.","m":"You hold the healing nectar of Ram’s name, and remain forever Raghupati’s servant.","h":"आपके पास राम-नाम रूपी रसायन है; आप सदा श्री रघुपति के दास बने रहें।"},{"d":"तुम्हरे भजन राम को पावै।\nजनम जनम के दुख बिसरावै॥","r":"Tumhre bhajan Ram ko pavai,\njanam janam ke dukh bisravai.","m":"Through devotion to you one reaches Ram and forgets the sorrows of many lives.","h":"आपके भजन से श्री राम मिलते हैं और जन्म-जन्मान्तर के दुःख भूल जाते हैं।"},{"d":"अंत काल रघुबर पुर जाई।\nजहाँ जन्म हरि-भक्त कहाई॥","r":"Ant kaal Raghubar pur jai,\njahan janma Hari-bhakt kahai.","m":"At life’s end one goes to Ram’s abode, and wherever born again is known as a devotee of Hari.","h":"अन्त समय में भक्त श्री राम के धाम जाता है, और जहाँ भी जन्म लेता है, हरि-भक्त कहलाता है।"},{"d":"और देवता चित्त न धरई।\nहनुमत सेइ सर्ब सुख करई॥","r":"Aur devta chitt na dharai,\nHanumat sei sarb sukh karai.","m":"Even without turning the mind to other gods, serving Hanuman brings every happiness.","h":"दूसरे देवताओं का ध्यान न करते हुए भी, केवल हनुमानजी की सेवा से सब सुख मिल जाते हैं।"},{"d":"संकट कटै मिटै सब पीरा।\nजो सुमिरै हनुमत बलबीरा॥","r":"Sankat katai mitai sab peera,\njo sumirai Hanumat balbeera.","m":"Troubles are cut away and all pain ends for one who remembers mighty Hanuman.","h":"जो बलवान वीर हनुमान का स्मरण करता है, उसके संकट कट जाते हैं और सब पीड़ा मिट जाती है।"},{"d":"जै जै जै हनुमान गोसाईं।\nकृपा करहु गुरुदेव की नाईं॥","r":"Jai jai jai Hanuman Gosain,\nkripa karahu Gurudev ki nain.","m":"Victory, victory, victory to Lord Hanuman! Be gracious to me as a guru is to his disciple.","h":"हे स्वामी हनुमान, आपकी जय हो, जय हो, जय हो! गुरुदेव की तरह मुझ पर कृपा कीजिए।"},{"d":"जो सत बार पाठ कर कोई।\nछूटहि बंदि महा सुख होई॥","r":"Jo sat baar paath kar koi,\nchhootahi bandi maha sukh hoi.","m":"Whoever recites this a hundred times is freed from bondage and finds great joy.","h":"जो कोई इसका सौ बार पाठ करता है, वह बन्धनों से छूट जाता है और उसे महान सुख मिलता है।"},{"d":"जो यह पढ़ै हनुमान चालीसा।\nहोय सिद्धि साखी गौरीसा॥","r":"Jo yah padhai Hanuman Chalisa,\nhoy siddhi sakhi Gaurisa.","m":"Whoever reads this Hanuman Chalisa succeeds; Shiv, lord of Gauri, is witness to it.","h":"जो यह हनुमान चालीसा पढ़ता है, उसे सिद्धि मिलती है; इसके साक्षी स्वयं गौरीपति शिव हैं।"},{"d":"तुलसीदास सदा हरि चेरा।\nकीजै नाथ हृदय महँ डेरा॥","r":"Tulsidas sada Hari chera,\nkeejai nath hriday mahan dera.","m":"Tulsidas is forever Hari’s servant. Lord, make your home in my heart.","h":"तुलसीदास सदा श्री हरि के सेवक हैं। हे नाथ, मेरे हृदय में निवास कीजिए।"},{"d":"पवनतनय संकट हरन, मंगल मूरति रूप।\nराम लखन सीता सहित, हृदय बसहु सुर भूप॥","r":"Pavantanay sankat haran, mangal murati roop,\nRam Lakhan Sita sahit, hriday basahu sur bhoop.","m":"Son of the Wind, remover of troubles, form of all that is auspicious: king of the gods, live in my heart together with Ram, Lakshman and Sita.","h":"हे पवनपुत्र, संकट हरने वाले, मंगल मूर्ति स्वरूप, देवताओं के राजा, आप श्री राम, लक्ष्मण और सीता सहित मेरे हृदय में निवास कीजिए।","n":"दोहा"}]},{"id":"asato-ma-sadgamaya","kind":"mantra","deity":"ishvar","lang":"sa","language":"Sanskrit (Vedic)","region":"All of India","title":{"d":"असतो मा सद्गमय","r":"Asato Ma Sadgamaya","en":"From darkness to light"},"auth":{"t":"Brihadaranyaka Upanishad 1.3.28","c":"known"},"occ":["morning","daily"],"when":"Recited at the start of study, at school assemblies and at the opening of gatherings.","form":"Shanti mantra","refrain":null,"refrainFirst":true,"verses":[{"d":"ॐ असतो मा सद्गमय।\nतमसो मा ज्योतिर्गमय।\nमृत्योर्मा अमृतं गमय।\nॐ शान्तिः शान्तिः शान्तिः॥","r":"Om asato ma sadgamaya,\nTamaso ma jyotirgamaya,\nMrityorma amritam gamaya,\nOm shantih shantih shantih.","m":"Lead me from the unreal to the real. Lead me from darkness to light. Lead me from death to immortality. Om, peace, peace, peace.","h":"मुझे असत्य से सत्य की ओर ले चलो। मुझे अन्धकार से प्रकाश की ओर ले चलो। मुझे मृत्यु से अमरता की ओर ले चलो। ॐ शान्ति, शान्ति, शान्ति।"}]},{"id":"gayatri-mantra","kind":"mantra","deity":"surya","lang":"sa","language":"Sanskrit (Vedic)","region":"All of India","title":{"d":"गायत्री मंत्र","r":"Gayatri Mantra","en":"The Vedic prayer for a clear mind"},"auth":{"t":"Rishi Vishwamitra, Rigveda 3.62.10","c":"attributed"},"occ":["morning","daily"],"when":"Recited at sunrise and at the sandhya prayers, before study, and in japa of 108 repetitions.","notes":"The opening “ॐ भूर्भुवः स्वः” is added before the Rigvedic verse when it is chanted.","refrain":null,"refrainFirst":true,"verses":[{"d":"ॐ भूर्भुवः स्वः।\nतत्सवितुर्वरेण्यं भर्गो देवस्य धीमहि।\nधियो यो नः प्रचोदयात्॥","r":"Om bhur bhuvah svah,\nTat savitur varenyam bhargo devasya dhimahi,\nDhiyo yo nah prachodayat.","m":"Om. Earth, sky and heaven. We meditate on the glorious light of the divine Savitr, the Sun, worthy of all worship. May he inspire and guide our minds.","h":"ॐ। पृथ्वी, अन्तरिक्ष और स्वर्ग। हम सविता देव (सूर्य) के उस श्रेष्ठ और पूजनीय तेज का ध्यान करते हैं। वे हमारी बुद्धि को प्रेरित करें और सही मार्ग पर ले चलें।"}]},{"id":"hare-krishna-mahamantra","kind":"mantra","deity":"krishna","lang":"sa","language":"Sanskrit","region":"All of India and worldwide","title":{"d":"हरे राम हरे कृष्ण","r":"Hare Rama Hare Krishna","en":"The mahamantra of sixteen names"},"auth":{"t":"Kali-Santarana Upanishad","c":"known"},"occ":["janmashtami","daily"],"when":"Repeated in japa on a mala of 108 beads and sung in kirtan.","form":"Mahamantra","notes":"The Kali-Santarana Upanishad gives it beginning with “Hare Rama”; ISKCON and many kirtan groups begin with “Hare Krishna”.","refrain":null,"refrainFirst":true,"verses":[{"d":"हरे राम हरे राम राम राम हरे हरे।\nहरे कृष्ण हरे कृष्ण कृष्ण कृष्ण हरे हरे॥","r":"Hare Rama Hare Rama, Rama Rama Hare Hare,\nHare Krishna Hare Krishna, Krishna Krishna Hare Hare.","m":"A call to the Lord through his names Hari, Ram and Krishna, repeated with love until the mind rests in them.","h":"भगवान को उनके हरि, राम और कृष्ण नामों से प्रेमपूर्वक पुकारना, बार-बार, जब तक मन उन्हीं में न रम जाए।"}]},{"id":"karpur-gauram","kind":"mantra","deity":"shiv","lang":"sa","language":"Sanskrit","region":"All of India","title":{"d":"कर्पूरगौरं करुणावतारं","r":"Karpur Gauram Karunavataram","en":"Closing verse to Shiv"},"auth":{"t":"Traditional Sanskrit verse","c":"traditional"},"occ":["closing","mahashivratri","shravan"],"when":"Recited in many homes and temples as the flame is offered at the end of the aarti, whichever deity’s aarti came before it.","form":"Shloka","refrain":null,"refrainFirst":true,"verses":[{"d":"कर्पूरगौरं करुणावतारं संसारसारं भुजगेन्द्रहारम्।\nसदा वसन्तं हृदयारविन्दे भवं भवानीसहितं नमामि॥","r":"Karpuragauram karunavataram, samsarasaram bhujagendraharam,\nSada vasantam hridayaravinde, Bhavam Bhavanisahitam namami.","m":"I bow to Shiv, fair as camphor, compassion embodied, the essence of the world, garlanded with the king of serpents, who lives always in the lotus of the heart together with Bhavani.","h":"जो कपूर के समान गौर वर्ण वाले हैं, करुणा के अवतार हैं, संसार के सार हैं, सर्पराज को हार के रूप में धारण करते हैं, और भवानी के साथ सदा हृदय रूपी कमल में निवास करते हैं, उन भगवान शिव को मैं नमस्कार करता हूँ।"}]},{"id":"mahamrityunjaya-mantra","kind":"mantra","deity":"shiv","lang":"sa","language":"Sanskrit (Vedic)","region":"All of India","title":{"d":"महामृत्युंजय मंत्र","r":"Mahamrityunjaya Mantra","en":"The great prayer for victory over death"},"auth":{"t":"Rishi Vasishtha, Rigveda 7.59.12","c":"attributed"},"occ":["shravan","mahashivratri","daily"],"when":"Chanted for healing, protection and peace, especially when someone is unwell, often 108 times on a rudraksha mala.","refrain":null,"refrainFirst":true,"verses":[{"d":"ॐ त्र्यम्बकं यजामहे सुगन्धिं पुष्टिवर्धनम्।\nउर्वारुकमिव बन्धनान्मृत्योर्मुक्षीय माऽमृतात्॥","r":"Om tryambakam yajamahe sugandhim pushtivardhanam,\nUrvarukamiva bandhanan mrityor mukshiya ma’mritat.","m":"We worship the three-eyed one, fragrant, who nourishes all beings. As a ripe cucumber is freed from its vine, may he free us from death, and never from immortality.","h":"हम तीन नेत्रों वाले, सुगन्धित और सबका पोषण बढ़ाने वाले भगवान शिव की पूजा करते हैं। जैसे पका हुआ खरबूजा अपनी बेल के बन्धन से छूट जाता है, वैसे ही वे हमें मृत्यु के बन्धन से मुक्त करें, पर अमरता से नहीं।"}]},{"id":"navdurga-dhyan","kind":"mantra","deity":"durga","lang":"sa","language":"Sanskrit","region":"All of India","title":{"d":"नवदुर्गा ध्यान मन्त्र","r":"Navdurga Dhyan Mantra","en":"Meditation verses for the nine forms of Durga"},"auth":{"t":"Traditional. The naming verse is from the Devi Kavach recited before the Durga Saptashati.","c":"traditional"},"occ":["navratri"],"when":"On each night of Navratri the verse for that night’s goddess is recited before her puja, after the kalash and the lamp are worshipped. Verse 1 is for the first night, verse 9 for the ninth.","form":"Dhyana shlokas","notes":"The opening verse, naming all nine forms in order, comes from the Devi Kavach. The nine meditation verses are the ones most often printed in Navratri puja books; a few books give different verses for some goddesses, especially Kalaratri.","refrain":null,"refrainFirst":true,"verses":[{"d":"प्रथमं शैलपुत्री च द्वितीयं ब्रह्मचारिणी।\nतृतीयं चन्द्रघण्टेति कूष्माण्डेति चतुर्थकम्॥\nपञ्चमं स्कन्दमातेति षष्ठं कात्यायनीति च।\nसप्तमं कालरात्रीति महागौरीति चाष्टमम्॥\nनवमं सिद्धिदात्री च नवदुर्गाः प्रकीर्तिताः।\nउक्तान्येतानि नामानि ब्रह्मणैव महात्मना॥","r":"Prathamam Shailaputri cha, dvitiyam Brahmacharini,\nTritiyam Chandraghanteti, Kushmandeti chaturthakam.\nPanchamam Skandamateti, shashtham Katyayaniti cha,\nSaptamam Kalaratriti, Mahagauriti chashtamam.\nNavamam Siddhidatri cha, Navadurgah prakirtitah,\nUktanyetani namani Brahmanaiva mahatmana.","m":"First is Shailputri, second Brahmacharini, third Chandraghanta and fourth Kushmanda; fifth Skandamata, sixth Katyayani, seventh Kalaratri and eighth Mahagauri; ninth is Siddhidatri. These are the nine Durgas, and these names were spoken by the great Brahma himself.","h":"पहली शैलपुत्री, दूसरी ब्रह्मचारिणी, तीसरी चन्द्रघण्टा और चौथी कूष्माण्डा; पाँचवीं स्कन्दमाता, छठी कात्यायनी, सातवीं कालरात्रि और आठवीं महागौरी; नौवीं सिद्धिदात्री। ये नवदुर्गा कहलाती हैं, और ये नाम स्वयं महात्मा ब्रह्माजी ने बताए हैं।","n":"ॐ"},{"d":"वन्दे वाञ्छितलाभाय चन्द्रार्धकृतशेखराम्।\nवृषारूढां शूलधरां शैलपुत्रीं यशस्विनीम्॥","r":"Vande vanchhitalabhaya chandrardhakritashekharam,\nVrisharudham shuladharam Shailaputrim yashasvinim.","m":"For the fulfilment of my wishes I bow to glorious Shailputri, who wears the half-moon on her crown, rides a bull and holds a trident.","h":"मनचाहे फल की प्राप्ति के लिए मैं यशस्विनी शैलपुत्री को प्रणाम करता हूँ, जिनके मस्तक पर अर्धचन्द्र शोभित है, जो वृषभ पर सवार हैं और त्रिशूल धारण करती हैं।","sp":{"d":"शैलपुत्री","r":"Shailputri, the first night"}},{"d":"दधाना करपद्माभ्यामक्षमालाकमण्डलू।\nदेवी प्रसीदतु मयि ब्रह्मचारिण्यनुत्तमा॥","r":"Dadhana karapadmabhyam akshamalakamandalu,\nDevi prasidatu mayi Brahmacharinyanuttama.","m":"May the incomparable goddess Brahmacharini, who holds a rosary and a water-pot in her lotus hands, be gracious to me.","h":"जो अपने कमल जैसे हाथों में जप की माला और कमण्डलु धारण करती हैं, वे सर्वश्रेष्ठ देवी ब्रह्मचारिणी मुझ पर प्रसन्न हों।","sp":{"d":"ब्रह्मचारिणी","r":"Brahmacharini, the second night"}},{"d":"पिण्डजप्रवरारूढा चण्डकोपास्त्रकैर्युता।\nप्रसादं तनुते मह्यं चन्द्रघण्टेति विश्रुता॥","r":"Pindajapravararudha chandakopastrakairyuta,\nPrasadam tanute mahyam Chandraghanteti vishruta.","m":"She who rides the noblest of beasts and bears weapons of fierce wrath, renowned as Chandraghanta, extends her grace to me.","h":"जो श्रेष्ठ वाहन (सिंह) पर सवार हैं और प्रचण्ड क्रोध वाले अस्त्र-शस्त्र धारण करती हैं, वे चन्द्रघण्टा नाम से प्रसिद्ध देवी मुझ पर कृपा करें।","sp":{"d":"चन्द्रघण्टा","r":"Chandraghanta, the third night"}},{"d":"सुरासम्पूर्णकलशं रुधिराप्लुतमेव च।\nदधाना हस्तपद्माभ्यां कूष्माण्डा शुभदास्तु मे॥","r":"Surasampurnakalasham rudhiraplutameva cha,\nDadhana hastapadmabhyam Kushmanda shubhadastu me.","m":"May Kushmanda, who holds in her lotus hands one pitcher brimming with nectar and another steeped in blood, bring me good fortune.","h":"जो अपने कमल जैसे हाथों में अमृत से भरा कलश और रक्त से भरा कलश धारण करती हैं, वे देवी कूष्माण्डा मेरा कल्याण करें।","sp":{"d":"कूष्माण्डा","r":"Kushmanda, the fourth night"}},{"d":"सिंहासनगता नित्यं पद्माश्रितकरद्वया।\nशुभदास्तु सदा देवी स्कन्दमाता यशस्विनी॥","r":"Simhasanagata nityam padmashritakaradvaya,\nShubhadastu sada Devi Skandamata yashasvini.","m":"Ever seated on her lion throne, a lotus in each of two hands, may the glorious goddess Skandamata always bring me good fortune.","h":"जो सदा सिंहासन पर विराजमान रहती हैं और दोनों हाथों में कमल धारण करती हैं, वे यशस्विनी देवी स्कन्दमाता सदा मेरा कल्याण करें।","sp":{"d":"स्कन्दमाता","r":"Skandamata, the fifth night"}},{"d":"चन्द्रहासोज्ज्वलकरा शार्दूलवरवाहना।\nकात्यायनी शुभं दद्याद्देवी दानवघातिनी॥","r":"Chandrahasojjvalakara shardulavaravahana,\nKatyayani shubham dadyad Devi danavaghatini.","m":"Her hand shining with the Chandrahas sword, riding the noblest of great cats, may Katyayani, the goddess who slays demons, grant me good fortune.","h":"जिनका हाथ चन्द्रहास खड्ग से चमक रहा है और जो श्रेष्ठ सिंह पर सवार हैं, वे दानवों का नाश करने वाली देवी कात्यायनी मेरा कल्याण करें।","sp":{"d":"कात्यायनी","r":"Katyayani, the sixth night"}},{"d":"एकवेणी जपाकर्णपूरा नग्ना खरास्थिता।\nलम्बोष्ठी कर्णिकाकर्णी तैलाभ्यक्तशरीरिणी॥\nवामपादोल्लसल्लोहलताकण्टकभूषणा।\nवर्धनमूर्धध्वजा कृष्णा कालरात्रिर्भयङ्करी॥","r":"Ekaveni japakarnapura nagna kharasthita,\nLambaushthi karnikakarni tailabhyaktasharirini.\nVamapadollasallohalatakantakabhushana,\nVardhanamurdhadhvaja Krishna Kalaratrirbhayankari.","m":"With a single braid, hibiscus flowers at her ears, unclothed and riding a donkey, with long lips, ornaments in her ears and her body anointed with oil; her left foot shining with an anklet of iron thorns, her banner raised high, dark in colour: this is Kalaratri, the terrifying, who drives away all fear.","h":"एक वेणी वाली, कानों में जपा (गुड़हल) के फूल पहने, वस्त्रहीन, गधे पर सवार, लम्बे होंठों वाली, कानों में कर्णफूल पहने, तेल से लिप्त शरीर वाली; बाएँ पैर में चमकते लोहे के काँटेदार आभूषण वाली, ऊँची ध्वजा वाली, श्याम वर्ण वाली: ऐसी भयंकर रूप वाली देवी कालरात्रि हैं, जो भक्तों का सारा भय दूर करती हैं।","sp":{"d":"कालरात्रि","r":"Kalaratri, the seventh night"}},{"d":"श्वेते वृषे समारूढा श्वेताम्बरधरा शुचिः।\nमहागौरी शुभं दद्यान्महादेवप्रमोददा॥","r":"Shvete vrishe samarudha shvetambaradhara shuchih,\nMahagauri shubham dadyan Mahadevapramodada.","m":"Mounted on a white bull and dressed in white, pure, the delight of Mahadev: may Mahagauri grant me good fortune.","h":"श्वेत वृषभ पर सवार, श्वेत वस्त्र धारण करने वाली, पवित्र और महादेव को आनन्द देने वाली महागौरी मेरा कल्याण करें।","sp":{"d":"महागौरी","r":"Mahagauri, the eighth night"}},{"d":"सिद्धगन्धर्वयक्षाद्यैरसुरैरमरैरपि।\nसेव्यमाना सदा भूयात् सिद्धिदा सिद्धिदायिनी॥","r":"Siddhagandharvayakshadyair asurair amarairapi,\nSevyamana sada bhuyat siddhida siddhidayini.","m":"Served by siddhas, gandharvas and yakshas, by demons and gods alike, may Siddhidatri, the giver of perfection, always grant perfection.","h":"सिद्ध, गन्धर्व, यक्ष, असुर और देवता भी जिनकी सदा सेवा करते हैं, वे सिद्धियाँ देने वाली देवी सिद्धिदात्री सदा सिद्धि प्रदान करें।","sp":{"d":"सिद्धिदात्री","r":"Siddhidatri, the ninth night"}}]},{"id":"saraswati-vandana","kind":"mantra","deity":"saraswati","lang":"sa","language":"Sanskrit","region":"All of India","title":{"d":"या कुन्देन्दुतुषारहारधवला","r":"Ya Kundendu Tushar Haar Dhavala","en":"Saraswati Vandana"},"auth":{"t":"Traditional Sanskrit shloka","c":"traditional"},"occ":["basant-panchami","morning","daily"],"when":"Recited at school assemblies, before study and exams, and in Saraswati Puja on Basant Panchami.","form":"Vandana","refrain":null,"refrainFirst":true,"verses":[{"d":"या कुन्देन्दुतुषारहारधवला या शुभ्रवस्त्रावृता।\nया वीणावरदण्डमण्डितकरा या श्वेतपद्मासना॥\nया ब्रह्माच्युतशंकरप्रभृतिभिर्देवैः सदा वन्दिता।\nसा मां पातु सरस्वती भगवती निःशेषजाड्यापहा॥","r":"Ya kundendu tushara hara dhavala, ya shubhra vastravrita,\nYa veena varadanda manditakara, ya shveta padmasana,\nYa Brahmachyuta Shankara prabhritibhir devaih sada vandita,\nSa mam patu Saraswati Bhagavati nihshesha jadyapaha.","m":"She who is white as jasmine, the moon, snow and a string of pearls, dressed in white; whose hands are graced by the veena and the staff of blessing; who sits on a white lotus; who is always worshipped by Brahma, Vishnu, Shiv and all the gods: may that Goddess Saraswati, who removes all dullness of mind, protect me.","h":"जो कुन्द के फूल, चन्द्रमा, बर्फ और मोतियों के हार जैसी श्वेत हैं, जो श्वेत वस्त्र पहनती हैं, जिनके हाथ वीणा और वरदण्ड से सुशोभित हैं, जो श्वेत कमल पर विराजती हैं, और ब्रह्मा, विष्णु, शंकर आदि देवता जिनकी सदा वन्दना करते हैं, वे सारी जड़ता दूर करने वाली भगवती सरस्वती मेरी रक्षा करें।"}]},{"id":"sarva-mangala-mangalye","kind":"mantra","deity":"durga","lang":"sa","language":"Sanskrit","region":"All of India","title":{"d":"सर्वमङ्गलमङ्गल्ये","r":"Sarva Mangala Mangalye","en":"The Narayani verse"},"auth":{"t":"From the Devi Mahatmya (Durga Saptashati), chapter 11","c":"known"},"occ":["navratri","closing","daily"],"when":"The most recited verse of the Durga Saptashati, said at the end of Devi puja, at weddings and before any auspicious beginning. Many recite it 108 times in Navratri.","form":"Shloka","notes":"In Gita Press editions it is verse 10 of chapter 11, the Narayani Stuti, which the gods sing after Shumbh is slain.","refrain":null,"refrainFirst":true,"verses":[{"d":"सर्वमङ्गलमङ्गल्ये शिवे सर्वार्थसाधिके।\nशरण्ये त्र्यम्बके गौरि नारायणि नमोऽस्तु ते॥","r":"Sarvamangalamangalye Shive sarvarthasadhike,\nSharanye Tryambake Gauri Narayani namo’stu te.","m":"Most auspicious of all that is auspicious, gracious one who fulfils every aim, giver of refuge, three-eyed Gauri: Narayani, I bow to you.","h":"हे सभी मंगलों में सबसे मंगलमयी, कल्याण करने वाली शिवा, सब कामनाएँ पूरी करने वाली, शरण देने वाली, तीन नेत्रों वाली गौरी, हे नारायणी, आपको नमस्कार है।"}]},{"id":"sarve-bhavantu-sukhinah","kind":"mantra","deity":"ishvar","lang":"sa","language":"Sanskrit","region":"All of India","title":{"d":"सर्वे भवन्तु सुखिनः","r":"Sarve Bhavantu Sukhinah","en":"A prayer for the happiness of all"},"auth":{"t":"Traditional Sanskrit prayer","c":"traditional"},"occ":["closing","meals","daily"],"when":"A prayer for the welfare of every being, said at the end of puja, satsang or a meal.","form":"Shanti mantra","refrain":null,"refrainFirst":true,"verses":[{"d":"ॐ सर्वे भवन्तु सुखिनः सर्वे सन्तु निरामयाः।\nसर्वे भद्राणि पश्यन्तु मा कश्चिद्दुःखभाग्भवेत्॥\nॐ शान्तिः शान्तिः शान्तिः॥","r":"Om sarve bhavantu sukhinah, sarve santu niramayah,\nSarve bhadrani pashyantu, ma kashchid duhkhabhagbhavet.\nOm shantih shantih shantih.","m":"May all be happy; may all be free from illness. May all see only what is good, and may no one suffer. Om, peace, peace, peace.","h":"सब सुखी हों, सब रोगरहित हों। सब कल्याण देखें और कोई भी दुःख का भागी न हो। ॐ शान्ति, शान्ति, शान्ति।"}]},{"id":"tvameva-mata","kind":"mantra","deity":"ishvar","lang":"sa","language":"Sanskrit","region":"All of India","title":{"d":"त्वमेव माता च पिता त्वमेव","r":"Tvameva Mata Cha Pita Tvameva","en":"You alone are everything to me"},"auth":{"t":"Traditional Sanskrit verse, also found in the Pandava Gita","c":"traditional"},"occ":["closing","morning","daily"],"when":"Sung at the end of the aarti in many homes, and as a morning prayer in schools.","form":"Shloka","refrain":null,"refrainFirst":true,"verses":[{"d":"त्वमेव माता च पिता त्वमेव। त्वमेव बन्धुश्च सखा त्वमेव॥\nत्वमेव विद्या द्रविणं त्वमेव। त्वमेव सर्वं मम देव देव॥","r":"Tvameva mata cha pita tvameva, tvameva bandhushcha sakha tvameva,\nTvameva vidya dravinam tvameva, tvameva sarvam mama deva deva.","m":"You alone are my mother and my father, you alone my family and my friend. You alone are my knowledge and my wealth. You are everything to me, God of gods.","h":"आप ही मेरी माता हैं और आप ही पिता, आप ही मेरे बन्धु और आप ही सखा हैं। आप ही मेरी विद्या और आप ही मेरा धन हैं। हे देवों के देव, आप ही मेरे सब कुछ हैं।"}]},{"id":"vakratunda-mahakaya","kind":"mantra","deity":"ganesh","lang":"sa","language":"Sanskrit","region":"All of India","title":{"d":"वक्रतुण्ड महाकाय","r":"Vakratunda Mahakaya","en":"Prayer to Ganesh before any work"},"auth":{"t":"Traditional Sanskrit shloka","c":"traditional"},"occ":["morning","ganesh-chaturthi","daily"],"when":"Said before starting any work, journey, exam or puja, so that it goes ahead without obstacles.","form":"Shloka","refrain":null,"refrainFirst":true,"verses":[{"d":"वक्रतुण्ड महाकाय सूर्यकोटि समप्रभ।\nनिर्विघ्नं कुरु मे देव सर्वकार्येषु सर्वदा॥","r":"Vakratunda mahakaya suryakoti samaprabha,\nNirvighnam kuru me deva sarvakaryeshu sarvada.","m":"O Lord with the curved trunk and mighty body, radiant as millions of suns: keep every obstacle away from all that I do, always.","h":"हे टेढ़ी सूँड वाले, विशाल शरीर वाले, करोड़ों सूर्यों के समान तेजस्वी देव, मेरे सब कार्यों को सदा विघ्नरहित कीजिए।"}]},{"id":"ya-devi-sarvabhuteshu","kind":"mantra","deity":"durga","lang":"sa","language":"Sanskrit","region":"All of India","title":{"d":"या देवी सर्वभूतेषु","r":"Ya Devi Sarvabhuteshu","en":"To the Goddess present in every being"},"auth":{"t":"From the Devi Mahatmya (Durga Saptashati), chapter 5","c":"known"},"occ":["navratri","daily"],"when":"Chanted through Navratri, often as the opening of Devi puja. In the Saptashati the same verse is repeated for twenty-one forms of the Goddess; the five here are the ones most often chanted on their own. The full hymn is in the Durga Saptashati, chapter 5.","form":"Shloka","notes":"Each verse is recited with the line “नमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः” three times over, which is why printed editions give every verse three numbers.","refrain":null,"refrainFirst":true,"verses":[{"d":"या देवी सर्वभूतेषु शक्तिरूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Ya Devi sarvabhuteshu shaktirupena sansthita,\nNamastasyai namastasyai namastasyai namo namah.","m":"To the Goddess who dwells in all beings as power: salutations to her, salutations to her, salutations to her, again and again.","h":"जो देवी सब प्राणियों में शक्ति के रूप में स्थित हैं, उनको नमस्कार है, उनको नमस्कार है, उनको बार-बार नमस्कार है।"},{"d":"या देवी सर्वभूतेषु मातृरूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Ya Devi sarvabhuteshu matrirupena sansthita,\nNamastasyai namastasyai namastasyai namo namah.","m":"To the Goddess who dwells in all beings as mother: salutations to her, again and again.","h":"जो देवी सब प्राणियों में माता के रूप में स्थित हैं, उनको बार-बार नमस्कार है।"},{"d":"या देवी सर्वभूतेषु लक्ष्मीरूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Ya Devi sarvabhuteshu Lakshmirupena sansthita,\nNamastasyai namastasyai namastasyai namo namah.","m":"To the Goddess who dwells in all beings as prosperity: salutations to her, again and again.","h":"जो देवी सब प्राणियों में लक्ष्मी (समृद्धि) के रूप में स्थित हैं, उनको बार-बार नमस्कार है।"},{"d":"या देवी सर्वभूतेषु बुद्धिरूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Ya Devi sarvabhuteshu buddhirupena sansthita,\nNamastasyai namastasyai namastasyai namo namah.","m":"To the Goddess who dwells in all beings as intelligence: salutations to her, again and again.","h":"जो देवी सब प्राणियों में बुद्धि के रूप में स्थित हैं, उनको बार-बार नमस्कार है।"},{"d":"या देवी सर्वभूतेषु शान्तिरूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Ya Devi sarvabhuteshu shantirupena sansthita,\nNamastasyai namastasyai namastasyai namo namah.","m":"To the Goddess who dwells in all beings as peace: salutations to her, again and again.","h":"जो देवी सब प्राणियों में शान्ति के रूप में स्थित हैं, उनको बार-बार नमस्कार है।"}]},{"id":"bhavani-ashtakam","kind":"stotra","deity":"durga","lang":"sa","language":"Sanskrit","region":"All of India","title":{"d":"भवान्यष्टकम्","r":"Bhavani Ashtakam","en":"Eight verses of surrender to Bhavani"},"auth":{"t":"Adi Shankaracharya, 8th century","c":"attributed"},"occ":["navratri","daily"],"when":"A prayer of complete surrender, recited in Navratri and whenever one feels helpless. Every verse ends with the same line: you alone are my refuge, Bhavani.","form":"Ashtakam","notes":"The refrain “गतिस्त्वं गतिस्त्वं त्वमेका भवानि” closes all eight verses. Some editions add a ninth verse giving the benefit of reciting it.","refrain":null,"refrainFirst":true,"verses":[{"d":"न तातो न माता न बन्धुर्न दाता\nन पुत्रो न पुत्री न भृत्यो न भर्ता।\nन जाया न विद्या न वृत्तिर्ममैव\nगतिस्त्वं गतिस्त्वं त्वमेका भवानि॥","r":"Na tato na mata na bandhurna data,\nNa putro na putri na bhrityo na bharta.\nNa jaya na vidya na vrittirmamaiva,\nGatistvam gatistvam tvameka Bhavani.","m":"No father, no mother, no kinsman, no benefactor; no son, no daughter, no servant, no master; no wife, no learning, no livelihood is truly mine. You are my refuge, you are my refuge, you alone, Bhavani.","h":"न पिता, न माता, न भाई-बन्धु, न दाता; न पुत्र, न पुत्री, न सेवक, न स्वामी; न पत्नी, न विद्या, न आजीविका, कुछ भी सचमुच मेरा नहीं है। हे भवानी, आप ही मेरी गति हैं, आप ही मेरी गति हैं, केवल आप।"},{"d":"भवाब्धावपारे महादुःखभीरुः\nपपात प्रकामी प्रलोभी प्रमत्तः।\nकुसंसारपाशप्रबद्धः सदाहं\nगतिस्त्वं गतिस्त्वं त्वमेका भवानि॥","r":"Bhavabdhavapare mahaduhkhabhiruh,\nPapata prakami pralobhi pramattah.\nKusansarapashaprabaddhah sadaham,\nGatistvam gatistvam tvameka Bhavani.","m":"In the shoreless ocean of worldly life I have fallen, terrified of its great sorrows, full of desire, greed and heedlessness, and always bound by the noose of this wretched world. You are my refuge, you alone, Bhavani.","h":"इस अपार संसार-सागर में मैं गिर पड़ा हूँ, बड़े दुःखों से डरा हुआ, कामना, लोभ और प्रमाद से भरा हुआ, और सदा इस बुरे संसार के बन्धन में बँधा हुआ। हे भवानी, केवल आप ही मेरी गति हैं।"},{"d":"न जानामि दानं न च ध्यानयोगं\nन जानामि तन्त्रं न च स्तोत्रमन्त्रम्।\nन जानामि पूजां न च न्यासयोगं\nगतिस्त्वं गतिस्त्वं त्वमेका भवानि॥","r":"Na janami danam na cha dhyanayogam,\nNa janami tantram na cha stotramantram.\nNa janami pujam na cha nyasayogam,\nGatistvam gatistvam tvameka Bhavani.","m":"I know nothing of charity or the discipline of meditation, nothing of tantra, hymns or mantras, nothing of worship or the placing of mantras on the body. You are my refuge, you alone, Bhavani.","h":"मैं न दान जानता हूँ, न ध्यान-योग; न तन्त्र जानता हूँ, न स्तोत्र और मन्त्र; न पूजा जानता हूँ, न न्यास की विधि। हे भवानी, केवल आप ही मेरी गति हैं।"},{"d":"न जानामि पुण्यं न जानामि तीर्थं\nन जानामि मुक्तिं लयं वा कदाचित्।\nन जानामि भक्तिं व्रतं वापि मातर्\nगतिस्त्वं गतिस्त्वं त्वमेका भवानि॥","r":"Na janami punyam na janami tirtham,\nNa janami muktim layam va kadachit.\nNa janami bhaktim vratam vapi matar,\nGatistvam gatistvam tvameka Bhavani.","m":"I know nothing of merit or of pilgrimage, nothing ever of liberation or of merging into the divine, nothing of devotion or of vows, Mother. You are my refuge, you alone, Bhavani.","h":"मैं न पुण्य जानता हूँ, न तीर्थ; न कभी मुक्ति जानी, न लय; हे माता, न भक्ति जानता हूँ, न व्रत। हे भवानी, केवल आप ही मेरी गति हैं।"},{"d":"कुकर्मी कुसङ्गी कुबुद्धिः कुदासः\nकुलाचारहीनः कदाचारलीनः।\nकुदृष्टिः कुवाक्यप्रबन्धः सदाहं\nगतिस्त्वं गतिस्त्वं त्वमेका भवानि॥","r":"Kukarmi kusangi kubuddhih kudasah,\nKulacharahinah kadacharalinah.\nKudrishtih kuvakyaprabandhah sadaham,\nGatistvam gatistvam tvameka Bhavani.","m":"I do wrong, keep bad company, think badly and serve poorly; I have abandoned the ways of my family and sunk into bad conduct; my eyes look on evil and my words are always harsh. You are my refuge, you alone, Bhavani.","h":"मैं बुरे कर्म करने वाला, बुरी संगति वाला, दुर्बुद्धि और बुरा सेवक हूँ; कुल के आचार से हीन और दुराचार में डूबा हुआ हूँ; मेरी दृष्टि बुरी है और मैं सदा कटु वचन बोलता हूँ। हे भवानी, केवल आप ही मेरी गति हैं।"},{"d":"प्रजेशं रमेशं महेशं सुरेशं\nदिनेशं निशीथेश्वरं वा कदाचित्।\nन जानामि चान्यत् सदाहं शरण्ये\nगतिस्त्वं गतिस्त्वं त्वमेका भवानि॥","r":"Prajesham Ramesham Mahesham Suresham,\nDinesham nishitheshvaram va kadachit.\nNa janami chanyat sadaham sharanye,\nGatistvam gatistvam tvameka Bhavani.","m":"I have never known Brahma, Vishnu, Shiv or Indra, the Sun or the Moon, nor anyone else; giver of refuge, you are my refuge, you alone, Bhavani.","h":"मैं ब्रह्मा, विष्णु, महेश, इन्द्र, सूर्य या चन्द्रमा को कभी नहीं जानता, न किसी और को; हे शरण देने वाली, केवल आप ही मेरी गति हैं, हे भवानी।"},{"d":"विवादे विषादे प्रमादे प्रवासे\nजले चानले पर्वते शत्रुमध्ये।\nअरण्ये शरण्ये सदा मां प्रपाहि\nगतिस्त्वं गतिस्त्वं त्वमेका भवानि॥","r":"Vivade vishade pramade pravase,\nJale chanale parvate shatrumadhye.\nAranye sharanye sada mam prapahi,\nGatistvam gatistvam tvameka Bhavani.","m":"In quarrels and in grief, in carelessness and far from home, in water and in fire, on mountains and among enemies, in the forest: giver of refuge, protect me always. You are my refuge, you alone, Bhavani.","h":"विवाद में, दुःख में, भूल में, परदेस में, जल में, आग में, पर्वत पर, शत्रुओं के बीच और वन में, हे शरण देने वाली, सदा मेरी रक्षा कीजिए। हे भवानी, केवल आप ही मेरी गति हैं।"},{"d":"अनाथो दरिद्रो जरारोगयुक्तो\nमहाक्षीणदीनः सदा जाड्यवक्त्रः।\nविपत्तौ प्रविष्टः प्रणष्टः सदाहं\nगतिस्त्वं गतिस्त्वं त्वमेका भवानि॥","r":"Anatho daridro jararogayukto,\nMahakshinadinah sada jadyavaktrah.\nVipattau pravishtah pranashtah sadaham,\nGatistvam gatistvam tvameka Bhavani.","m":"Helpless and poor, worn by age and illness, utterly weak and wretched, always dull of speech, sunk in misfortune and lost: you are my refuge, you alone, Bhavani.","h":"मैं अनाथ हूँ, दरिद्र हूँ, बुढ़ापे और रोग से घिरा हूँ, अत्यन्त दुर्बल और दीन हूँ, सदा जड़ बुद्धि वाला, विपत्ति में पड़ा और नष्ट हुआ हूँ। हे भवानी, केवल आप ही मेरी गति हैं।"}]},{"id":"madhurashtakam","kind":"stotra","deity":"krishna","lang":"sa","language":"Sanskrit","region":"All of India, especially the Pushti Marg tradition","title":{"d":"मधुराष्टकम्","r":"Madhurashtakam (Adharam Madhuram)","en":"Eight verses on Krishna’s sweetness"},"auth":{"t":"Shri Vallabhacharya, around 1500","c":"attributed"},"occ":["janmashtami","holi","daily"],"when":"Sung in Krishna worship, on Janmashtami and at satsangs. Its simple repeating pattern makes it easy for children to learn.","form":"Ashtakam","notes":"Every verse ends “मधुराधिपतेरखिलं मधुरम्”: everything about the Lord of sweetness is sweet.","refrain":null,"refrainFirst":true,"verses":[{"d":"अधरं मधुरं वदनं मधुरं नयनं मधुरं हसितं मधुरम्।\nहृदयं मधुरं गमनं मधुरं मधुराधिपतेरखिलं मधुरम्॥","r":"Adharam madhuram vadanam madhuram, nayanam madhuram hasitam madhuram,\nHridayam madhuram gamanam madhuram, Madhuradhipaterakhilam madhuram.","m":"Sweet are his lips, sweet his face, sweet his eyes, sweet his smile; sweet his heart, sweet his walk. Everything about the Lord of sweetness is sweet.","h":"उनके होंठ मधुर हैं, मुख मधुर है, नेत्र मधुर हैं, मुस्कान मधुर है; हृदय मधुर है, चाल मधुर है। मधुरता के स्वामी का सब कुछ मधुर है।"},{"d":"वचनं मधुरं चरितं मधुरं वसनं मधुरं वलितं मधुरम्।\nचलितं मधुरं भ्रमितं मधुरं मधुराधिपतेरखिलं मधुरम्॥","r":"Vachanam madhuram charitam madhuram, vasanam madhuram valitam madhuram,\nChalitam madhuram bhramitam madhuram, Madhuradhipaterakhilam madhuram.","m":"Sweet are his words, his deeds, his clothes and the way he turns; sweet his movements and his wanderings. Everything about the Lord of sweetness is sweet.","h":"उनके वचन मधुर हैं, चरित्र मधुर है, वस्त्र मधुर हैं, मुड़ना मधुर है; चलना मधुर है, घूमना मधुर है। मधुरता के स्वामी का सब कुछ मधुर है।"},{"d":"वेणुर्मधुरो रेणुर्मधुरः पाणिर्मधुरः पादौ मधुरौ।\nनृत्यं मधुरं सख्यं मधुरं मधुराधिपतेरखिलं मधुरम्॥","r":"Venurmadhuro renurmadhurah, panirmadhurah padau madhurau,\nNrityam madhuram sakhyam madhuram, Madhuradhipaterakhilam madhuram.","m":"Sweet is his flute, sweet the dust of his feet; sweet his hands, sweet his feet; sweet his dance and his friendship. Everything about the Lord of sweetness is sweet.","h":"उनकी बाँसुरी मधुर है, चरणों की धूल मधुर है, हाथ मधुर हैं, चरण मधुर हैं; नृत्य मधुर है, मित्रता मधुर है। मधुरता के स्वामी का सब कुछ मधुर है।"},{"d":"गीतं मधुरं पीतं मधुरं भुक्तं मधुरं सुप्तं मधुरम्।\nरूपं मधुरं तिलकं मधुरं मधुराधिपतेरखिलं मधुरम्॥","r":"Gitam madhuram pitam madhuram, bhuktam madhuram suptam madhuram,\nRoopam madhuram tilakam madhuram, Madhuradhipaterakhilam madhuram.","m":"Sweet is his singing, his drinking, his eating and his sleep; sweet his form, sweet the tilak on his brow. Everything about the Lord of sweetness is sweet.","h":"उनका गाना मधुर है, पीना मधुर है, खाना मधुर है, सोना मधुर है; रूप मधुर है, तिलक मधुर है। मधुरता के स्वामी का सब कुछ मधुर है।"},{"d":"करणं मधुरं तरणं मधुरं हरणं मधुरं रमणं मधुरम्।\nवमितं मधुरं शमितं मधुरं मधुराधिपतेरखिलं मधुरम्॥","r":"Karanam madhuram taranam madhuram, haranam madhuram ramanam madhuram,\nVamitam madhuram shamitam madhuram, Madhuradhipaterakhilam madhuram.","m":"Sweet are his doings, his rescues, the way he steals hearts and his play; sweet what he gives away and his calm. Everything about the Lord of sweetness is sweet.","h":"उनके कार्य मधुर हैं, तारना मधुर है, मन हरना मधुर है, रमण मधुर है; उनका त्याग मधुर है, शान्ति मधुर है। मधुरता के स्वामी का सब कुछ मधुर है।"},{"d":"गुञ्जा मधुरा माला मधुरा यमुना मधुरा वीची मधुरा।\nसलिलं मधुरं कमलं मधुरं मधुराधिपतेरखिलं मधुरम्॥","r":"Gunja madhura mala madhura, Yamuna madhura vichi madhura,\nSalilam madhuram kamalam madhuram, Madhuradhipaterakhilam madhuram.","m":"Sweet is his necklace of gunja berries, sweet his garland; sweet the Yamuna and her ripples, sweet her water and her lotuses. Everything about the Lord of sweetness is sweet.","h":"उनकी गुंजा मधुर है, माला मधुर है, यमुना मधुर है, उसकी लहरें मधुर हैं; जल मधुर है, कमल मधुर है। मधुरता के स्वामी का सब कुछ मधुर है।"},{"d":"गोपी मधुरा लीला मधुरा युक्तं मधुरं मुक्तं मधुरम्।\nदृष्टं मधुरं शिष्टं मधुरं मधुराधिपतेरखिलं मधुरम्॥","r":"Gopi madhura lila madhura, yuktam madhuram muktam madhuram,\nDrishtam madhuram shishtam madhuram, Madhuradhipaterakhilam madhuram.","m":"Sweet are the gopis and his play with them; sweet his meetings and his partings; sweet his glance and his courtesy. Everything about the Lord of sweetness is sweet.","h":"गोपियाँ मधुर हैं, लीला मधुर है, मिलन मधुर है, विदा मधुर है; उनकी दृष्टि मधुर है, शिष्टता मधुर है। मधुरता के स्वामी का सब कुछ मधुर है।"},{"d":"गोपा मधुरा गावो मधुरा यष्टिर्मधुरा सृष्टिर्मधुरा।\nदलितं मधुरं फलितं मधुरं मधुराधिपतेरखिलं मधुरम्॥","r":"Gopa madhura gavo madhura, yashtirmadhura srishtirmadhura,\nDalitam madhuram phalitam madhuram, Madhuradhipaterakhilam madhuram.","m":"Sweet are the cowherds, sweet the cows, sweet his staff and all creation; sweet what he crushes and what he brings to fruit. Everything about the Lord of sweetness is sweet.","h":"ग्वाले मधुर हैं, गायें मधुर हैं, लाठी मधुर है, सृष्टि मधुर है; उनका दलन मधुर है, फल देना मधुर है। मधुरता के स्वामी का सब कुछ मधुर है।"}]},{"id":"nirvana-shatakam","kind":"stotra","deity":"shiv","lang":"sa","language":"Sanskrit","region":"All of India","title":{"d":"निर्वाणषट्कम्","r":"Nirvana Shatakam (Shivoham)","en":"Six verses on the true Self"},"auth":{"t":"Traditionally attributed to Adi Shankaracharya","c":"attributed"},"occ":["mahashivratri","daily"],"when":"A hymn of Advaita Vedanta, chanted in meditation and on Maha Shivratri. Here “Shiv” means the pure Self, beyond body and mind.","notes":"Also called Atma Shatakam. The last verse has variants, such as “न चासङ्गतं नैव मुक्तिर्न मेयः”.","refrain":null,"refrainFirst":true,"verses":[{"d":"मनोबुद्ध्यहङ्कारचित्तानि नाहं न च श्रोत्रजिह्वे न च घ्राणनेत्रे।\nन च व्योम भूमिर्न तेजो न वायुः चिदानन्दरूपः शिवोऽहं शिवोऽहम्॥","r":"Mano buddhyahankara chittani naham, na cha shrotra jihve na cha ghrana netre,\nNa cha vyoma bhumir na tejo na vayuh, chidananda roopah Shivo’ham Shivo’ham.","m":"I am not the mind, intellect, ego or memory; not the ears, tongue, nose or eyes; not space, earth, fire or air. I am consciousness and bliss. I am Shiv, I am Shiv.","h":"मैं न मन हूँ, न बुद्धि, न अहंकार, न चित्त; न कान हूँ, न जीभ, न नाक, न आँखें; न आकाश हूँ, न पृथ्वी, न अग्नि, न वायु। मैं चेतना और आनन्द स्वरूप हूँ, मैं शिव हूँ, मैं शिव हूँ।"},{"d":"न च प्राणसंज्ञो न वै पञ्चवायुः न वा सप्तधातुर्न वा पञ्चकोशः।\nन वाक्पाणिपादं न चोपस्थपायू चिदानन्दरूपः शिवोऽहं शिवोऽहम्॥","r":"Na cha prana sanjno na vai panchavayuh, na va saptadhatur na va panchakoshah,\nNa vak pani padam na chopasthapayu, chidananda roopah Shivo’ham Shivo’ham.","m":"I am not the breath of life nor the five vital airs, not the seven elements of the body nor its five sheaths, not speech, hands, feet or any organ of action. I am consciousness and bliss. I am Shiv, I am Shiv.","h":"मैं न प्राण हूँ, न पाँच वायु; न शरीर की सात धातुएँ, न पाँच कोश; न वाणी, न हाथ, न पैर, न कोई कर्मेन्द्रिय। मैं चेतना और आनन्द स्वरूप हूँ, मैं शिव हूँ, मैं शिव हूँ।"},{"d":"न मे द्वेषरागौ न मे लोभमोहौ मदो नैव मे नैव मात्सर्यभावः।\nन धर्मो न चार्थो न कामो न मोक्षः चिदानन्दरूपः शिवोऽहं शिवोऽहम्॥","r":"Na me dvesharagau na me lobhamohau, mado naiva me naiva matsarya bhavah,\nNa dharmo na chartho na kamo na mokshah, chidananda roopah Shivo’ham Shivo’ham.","m":"I have no hatred or attachment, no greed or delusion, no pride and no envy. I am not duty, wealth, desire, or even liberation. I am consciousness and bliss. I am Shiv, I am Shiv.","h":"मुझमें न द्वेष है न राग, न लोभ है न मोह, न मद है न ईर्ष्या। मैं न धर्म हूँ, न अर्थ, न काम, न मोक्ष। मैं चेतना और आनन्द स्वरूप हूँ, मैं शिव हूँ, मैं शिव हूँ।"},{"d":"न पुण्यं न पापं न सौख्यं न दुःखं न मन्त्रो न तीर्थं न वेदा न यज्ञाः।\nअहं भोजनं नैव भोज्यं न भोक्ता चिदानन्दरूपः शिवोऽहं शिवोऽहम्॥","r":"Na punyam na papam na saukhyam na duhkham, na mantro na tirtham na veda na yajnah,\nAham bhojanam naiva bhojyam na bhokta, chidananda roopah Shivo’ham Shivo’ham.","m":"Not merit or sin, not pleasure or pain; not mantra, pilgrimage, scripture or sacrifice. I am not the eating, the food, or the one who eats. I am consciousness and bliss. I am Shiv, I am Shiv.","h":"न पुण्य, न पाप, न सुख, न दुःख; न मन्त्र, न तीर्थ, न वेद, न यज्ञ। मैं न भोजन हूँ, न भोजन की वस्तु, न भोजन करने वाला। मैं चेतना और आनन्द स्वरूप हूँ, मैं शिव हूँ, मैं शिव हूँ।"},{"d":"न मे मृत्युशङ्का न मे जातिभेदः पिता नैव मे नैव माता न जन्म।\nन बन्धुर्न मित्रं गुरुर्नैव शिष्यः चिदानन्दरूपः शिवोऽहं शिवोऽहम्॥","r":"Na me mrityushanka na me jatibhedah, pita naiva me naiva mata na janma,\nNa bandhur na mitram gurur naiva shishyah, chidananda roopah Shivo’ham Shivo’ham.","m":"I have no fear of death and no divisions of birth; no father, no mother, no birth at all; no kin, no friend, no teacher and no disciple. I am consciousness and bliss. I am Shiv, I am Shiv.","h":"मुझे न मृत्यु का भय है, न जाति का भेद; न मेरा कोई पिता है, न माता, न जन्म; न बन्धु, न मित्र, न गुरु, न शिष्य। मैं चेतना और आनन्द स्वरूप हूँ, मैं शिव हूँ, मैं शिव हूँ।"},{"d":"अहं निर्विकल्पो निराकाररूपो विभुत्वाच्च सर्वत्र सर्वेन्द्रियाणाम्।\nसदा मे समत्वं न मुक्तिर्न बन्धः चिदानन्दरूपः शिवोऽहं शिवोऽहम्॥","r":"Aham nirvikalpo nirakara roopo, vibhutvachcha sarvatra sarvendriyanam,\nSada me samatvam na muktir na bandhah, chidananda roopah Shivo’ham Shivo’ham.","m":"I am free of all doubt and without form, present everywhere and behind every sense. I am always the same; for me there is no freedom and no bondage. I am consciousness and bliss. I am Shiv, I am Shiv.","h":"मैं सब संशयों से रहित और निराकार हूँ; सर्वव्यापक होने से मैं हर जगह और सब इन्द्रियों में हूँ। मैं सदा सम हूँ; मेरे लिए न मुक्ति है, न बन्धन। मैं चेतना और आनन्द स्वरूप हूँ, मैं शिव हूँ, मैं शिव हूँ।"}]},{"id":"shiv-rudrashtakam","kind":"stotra","deity":"shiv","lang":"sa","language":"Sanskrit","region":"All of India","title":{"d":"श्री रुद्राष्टकम्","r":"Shri Rudrashtakam (Namamishamishan)","en":"Eight verses to Shiv as Rudra"},"auth":{"t":"Goswami Tulsidas, from the Uttar Kand of the Ramcharitmanas","c":"known"},"occ":["mahashivratri","shravan","daily"],"when":"Sung in Shiv puja, on Mondays, through Sawan and on Maha Shivratri. In the Manas, a Brahmin sings it to win Shiv’s mercy for his disciple.","form":"Stuti","notes":"Unlike the rest of the Manas it is in Sanskrit. Some editions print the second verse as “गिरा ग्यान गोतीतमीशं गिरीशं”.","refrain":null,"refrainFirst":true,"verses":[{"d":"नमामीशमीशान निर्वाणरूपं। विभुं व्यापकं ब्रह्म वेदस्वरूपं॥\nनिजं निर्गुणं निर्विकल्पं निरीहं। चिदाकाशमाकाशवासं भजेऽहं॥","r":"Namamishamishan nirvanaroopam, vibhum vyapakam Brahma Vedasvaroopam,\nNijam nirgunam nirvikalpam niriham, chidakashamakashavasam bhaje’ham.","m":"I bow to the Lord of all, whose very form is liberation: all-pervading, the Brahman whose form is the Veda. I worship him who is the Self, beyond qualities, doubt and desire, pure consciousness spread like the sky.","h":"मैं उन ईशान को नमस्कार करता हूँ जो मोक्ष स्वरूप हैं, सर्वव्यापक हैं, वेदस्वरूप ब्रह्म हैं। मैं उन्हें भजता हूँ जो आत्मस्वरूप, निर्गुण, संशयरहित, इच्छारहित हैं और आकाश की तरह फैली चेतना हैं।"},{"d":"निराकारमोंकारमूलं तुरीयं। गिरा ज्ञान गोतीतमीशं गिरीशं॥\nकरालं महाकाल कालं कृपालं। गुणागार संसारपारं नतोऽहं॥","r":"Nirakaram Omkaramoolam turiyam, gira gyan gotitamisham Girisham,\nKaralam Mahakal kalam kripalam, gunagar sansaraparam nato’ham.","m":"Formless, the root of Om, beyond the three states of waking, dream and sleep; beyond speech, thought and the senses, lord of the mountain. Fearsome, the death of Death, yet full of mercy, home of all virtues, beyond the world: to him I bow.","h":"जो निराकार हैं, ओंकार के मूल हैं, तुरीय अवस्था (जाग्रत, स्वप्न, सुषुप्ति से परे) हैं; वाणी, ज्ञान और इन्द्रियों से परे हैं, कैलाशपति हैं; जो विकराल हैं, महाकाल के भी काल हैं, फिर भी कृपालु हैं, गुणों के धाम और संसार से परे हैं, उन्हें मैं नमस्कार करता हूँ।"},{"d":"तुषाराद्रि संकाश गौरं गभीरं। मनोभूत कोटि प्रभा श्री शरीरं॥\nस्फुरन्मौलि कल्लोलिनी चारु गंगा। लसद्भालबालेन्दु कंठे भुजंगा॥","r":"Tusharadri sankash gauram gabhiram, manobhoot koti prabha shri shariram,\nSphuranmauli kallolini charu Ganga, lasadbhalabalendu kanthe bhujanga.","m":"Fair as the snowy Himalaya and deep beyond measure, his body shines with the beauty of millions of Kamadevs. The lovely Ganga ripples on his head, the young moon glows on his brow, and serpents circle his neck.","h":"जो हिमालय के समान गौर और गम्भीर हैं, जिनके शरीर में करोड़ों कामदेवों जैसी शोभा है; जिनके सिर पर सुन्दर गंगा लहराती हैं, मस्तक पर बाल चन्द्रमा चमकता है और गले में सर्प हैं।"},{"d":"चलत्कुण्डलं भ्रू सुनेत्रं विशालं। प्रसन्नाननं नीलकंठं दयालं॥\nमृगाधीशचर्माम्बरं मुण्डमालं। प्रियं शंकरं सर्वनाथं भजामि॥","r":"Chalatkundalam bhru sunetram vishalam, prasannananam Neelkantham dayalam,\nMrigadhishacharmambaram mundamalam, priyam Shankaram sarvanatham bhajami.","m":"Earrings swaying, fine brows and wide, lovely eyes, a joyful face, a blue throat and a kind heart; clothed in a lion’s skin and garlanded with skulls: I worship beloved Shankar, lord of all.","h":"जिनके कानों में कुण्डल हिलते हैं, भौंहें और नेत्र सुन्दर और विशाल हैं, मुख प्रसन्न है, कण्ठ नीला है और जो दयालु हैं; जो सिंह की खाल पहनते हैं और मुण्डमाला धारण करते हैं, उन सबके स्वामी प्रिय शंकर को मैं भजता हूँ।"},{"d":"प्रचंडं प्रकृष्टं प्रगल्भं परेशं। अखंडं अजं भानुकोटिप्रकाशं॥\nत्रयः शूल निर्मूलनं शूलपाणिं। भजेऽहं भवानीपतिं भावगम्यं॥","r":"Prachandam prakrishtam pragalbham paresham, akhandam ajam bhanukotiprakasham,\nTrayah shool nirmoolanam shoolapanim, bhaje’ham Bhavanipatim bhavagamyam.","m":"Fierce, supreme, fearless, the highest lord; whole, unborn, bright as millions of suns; the trident-holder who uproots the three kinds of suffering. I worship Bhavani’s lord, who is reached through love.","h":"जो प्रचण्ड, श्रेष्ठ, निर्भय और परमेश्वर हैं; अखण्ड, अजन्मा और करोड़ों सूर्यों के समान प्रकाशमान हैं; जो त्रिशूलधारी तीनों प्रकार के दुःखों को जड़ से मिटाते हैं, भाव से प्राप्त होने वाले उन भवानीपति को मैं भजता हूँ।"},{"d":"कलातीत कल्याण कल्पान्तकारी। सदा सज्जनानन्ददाता पुरारी॥\nचिदानंदसंदोह मोहापहारी। प्रसीद प्रसीद प्रभो मन्मथारी॥","r":"Kalatit kalyan kalpantakari, sada sajjanananda data Purari,\nChidananda sandoha mohapahari, prasida prasida prabho Manmathari.","m":"Beyond time and parts, all goodness, who brings each age to its close; giver of joy to the good, destroyer of Tripura; mass of consciousness and bliss who removes delusion: be pleased, be pleased, O Lord who burned Kamadev.","h":"जो कलाओं से परे हैं, कल्याण स्वरूप हैं, कल्प का अन्त करने वाले हैं, सज्जनों को सदा आनन्द देने वाले त्रिपुरारि हैं, चेतना और आनन्द के समूह हैं और मोह को हरने वाले हैं; हे कामदेव को भस्म करने वाले प्रभु, प्रसन्न होइए, प्रसन्न होइए।"},{"d":"न यावत् उमानाथ पादारविन्दं। भजन्तीह लोके परे वा नराणां॥\nन तावत्सुखं शान्ति सन्तापनाशं। प्रसीद प्रभो सर्वभूताधिवासं॥","r":"Na yavat Umanath padaravindam, bhajantiha loke pare va naranam,\nNa tavat sukham shanti santapanasham, prasida prabho sarvabhootadhivasam.","m":"Until people worship the lotus feet of Uma’s lord, they find no happiness or peace in this world or the next, and their pain does not end. Be pleased, Lord who lives in every being.","h":"जब तक मनुष्य उमापति के चरणकमलों को नहीं भजते, तब तक उन्हें इस लोक या परलोक में न सुख मिलता है, न शान्ति, और न उनके कष्ट मिटते हैं। हे सब प्राणियों में निवास करने वाले प्रभु, प्रसन्न होइए।"},{"d":"न जानामि योगं जपं नैव पूजां। नतोऽहं सदा सर्वदा शम्भु तुभ्यं॥\nजरा जन्म दुःखौघ तातप्यमानं। प्रभो पाहि आपन्नमामीश शंभो॥","r":"Na janami yogam japam naiva pujam, nato’ham sada sarvada Shambhu tubhyam,\nJara janma duhkhaugha tatapyamanam, prabho pahi apannamamisha Shambho.","m":"I know no yoga, no japa, no proper worship; I only bow to you, always, Shambhu. I burn in the flood of sorrow of birth and old age: protect me, Lord, for I have come to you in distress.","h":"मैं न योग जानता हूँ, न जप, न पूजा; हे शम्भु, मैं तो सदा-सर्वदा आपको ही नमस्कार करता हूँ। बुढ़ापे और जन्म के दुःखों की बाढ़ में जलते हुए मुझ दुखी की, हे प्रभु शम्भु, रक्षा कीजिए।"},{"d":"रुद्राष्टकमिदं प्रोक्तं विप्रेण हरतोषये।\nये पठन्ति नरा भक्त्या तेषां शम्भुः प्रसीदति॥","r":"Rudrashtakamidam proktam viprena haratoshaye,\nye pathanti nara bhaktya tesham Shambhuh prasidati.","m":"This Rudrashtakam was sung by a Brahmin to please Shiv. Shambhu is pleased with all who recite it with devotion.","h":"भगवान शिव को प्रसन्न करने के लिए एक ब्राह्मण ने यह रुद्राष्टक गाया था। जो मनुष्य इसे भक्तिपूर्वक पढ़ते हैं, उन पर शम्भु प्रसन्न होते हैं।","n":"फल"}]},{"id":"shiva-panchakshara-stotram","kind":"stotra","deity":"shiv","lang":"sa","language":"Sanskrit","region":"All of India","title":{"d":"शिवपञ्चाक्षर स्तोत्रम्","r":"Shiva Panchakshara Stotram","en":"A hymn on the five syllables of Namah Shivaya"},"auth":{"t":"Traditionally attributed to Adi Shankaracharya","c":"attributed"},"occ":["mahashivratri","shravan","daily"],"when":"Recited in Shiv puja and on Mondays. Each verse is built on one syllable of the mantra: न, म, शि, वा, य.","notes":"Verse three is sometimes printed with “गौरीवदनाब्जबृन्द”.","refrain":null,"refrainFirst":true,"verses":[{"d":"नागेन्द्रहाराय त्रिलोचनाय भस्माङ्गरागाय महेश्वराय।\nनित्याय शुद्धाय दिगम्बराय तस्मै नकाराय नमः शिवाय॥","r":"Nagendraharaya trilochanaya, bhasmangaragaya Maheshwaraya,\nNityaya shuddhaya digambaraya, tasmai nakaraya namah Shivaya.","m":"To the three-eyed great lord who wears the king of serpents as a garland and sacred ash on his body; eternal, pure, clothed only by the directions: to that Shiv, the syllable “Na”, I bow.","h":"जो सर्पराज को हार के रूप में पहनते हैं, तीन नेत्रों वाले हैं, शरीर पर भस्म लगाते हैं, महेश्वर हैं; जो नित्य, शुद्ध और दिगम्बर हैं, उन “न” अक्षर स्वरूप शिव को नमस्कार है।"},{"d":"मन्दाकिनीसलिलचन्दनचर्चिताय नन्दीश्वरप्रमथनाथमहेश्वराय।\nमन्दारपुष्पबहुपुष्पसुपूजिताय तस्मै मकाराय नमः शिवाय॥","r":"Mandakinisalila chandana charchitaya, Nandishwara pramathanatha Maheshwaraya,\nMandara pushpa bahupushpa supujitaya, tasmai makaraya namah Shivaya.","m":"Bathed in the Ganga and anointed with sandal paste, lord of Nandi and of his hosts, worshipped with mandara and countless other flowers: to that Shiv, the syllable “Ma”, I bow.","h":"जो गंगाजल और चन्दन से चर्चित हैं, नन्दी और प्रमथगणों के स्वामी महेश्वर हैं, मन्दार और अनेक पुष्पों से पूजित हैं, उन “म” अक्षर स्वरूप शिव को नमस्कार है।"},{"d":"शिवाय गौरीवदनाब्जवृन्दसूर्याय दक्षाध्वरनाशकाय।\nश्रीनीलकण्ठाय वृषध्वजाय तस्मै शिकाराय नमः शिवाय॥","r":"Shivaya Gauri vadanabja vrinda suryaya, Dakshadhvara nashakaya,\nShri Neelakanthaya vrishadhvajaya, tasmai shikaraya namah Shivaya.","m":"To the auspicious one, the sun at whose rising Gauri’s lotus face blooms, who ended Daksha’s sacrifice; to the blue-throated one whose banner bears the bull: to that Shiv, the syllable “Shi”, I bow.","h":"जो कल्याण स्वरूप हैं, गौरी के मुखकमल को खिलाने वाले सूर्य हैं, दक्ष के यज्ञ का नाश करने वाले हैं, नीलकण्ठ हैं और जिनकी ध्वजा पर वृषभ है, उन “शि” अक्षर स्वरूप शिव को नमस्कार है।"},{"d":"वसिष्ठकुम्भोद्भवगौतमार्यमुनीन्द्रदेवार्चितशेखराय।\nचन्द्रार्कवैश्वानरलोचनाय तस्मै वकाराय नमः शिवाय॥","r":"Vasishtha kumbhodbhava Gautamarya munindra devarchita shekharaya,\nChandrarka vaishvanara lochanaya, tasmai vakaraya namah Shivaya.","m":"Whose head is worshipped by Vasishtha, Agastya, Gautam and the great sages and gods; whose three eyes are the moon, the sun and fire: to that Shiv, the syllable “Va”, I bow.","h":"वसिष्ठ, अगस्त्य, गौतम आदि श्रेष्ठ मुनि और देवता जिनके मस्तक की पूजा करते हैं, चन्द्रमा, सूर्य और अग्नि जिनके नेत्र हैं, उन “व” अक्षर स्वरूप शिव को नमस्कार है।"},{"d":"यक्षस्वरूपाय जटाधराय पिनाकहस्ताय सनातनाय।\nदिव्याय देवाय दिगम्बराय तस्मै यकाराय नमः शिवाय॥","r":"Yakshasvaroopaya jatadharaya, pinakahastaya sanatanaya,\nDivyaya devaya digambaraya, tasmai yakaraya namah Shivaya.","m":"Who appeared as a yaksha, wears matted hair and holds the Pinaka bow, the eternal one; divine, radiant, clothed by the directions: to that Shiv, the syllable “Ya”, I bow.","h":"जो यक्ष रूप धारण करते हैं, जटाधारी हैं, हाथ में पिनाक धनुष रखते हैं, सनातन हैं, दिव्य, देव और दिगम्बर हैं, उन “य” अक्षर स्वरूप शिव को नमस्कार है।"},{"d":"पञ्चाक्षरमिदं पुण्यं यः पठेच्छिवसन्निधौ।\nशिवलोकमवाप्नोति शिवेन सह मोदते॥","r":"Panchaksharamidam punyam yah pathechchhivasannidhau,\nShivalokamavapnoti Shivena saha modate.","m":"Whoever recites this sacred hymn of the five syllables near Shiv reaches Shiv’s world and rejoices with him.","h":"जो शिवजी के समीप इस पवित्र पञ्चाक्षर स्तोत्र का पाठ करता है, वह शिवलोक को प्राप्त करता है और शिवजी के साथ आनन्द करता है।","n":"फल"}]},{"id":"shri-ramchandra-kripalu","kind":"stotra","deity":"ram","lang":"hi","language":"Hindi","region":"North India","title":{"d":"श्रीरामचन्द्र कृपालु भजु मन","r":"Shri Ramchandra Kripalu Bhaju Man","en":"Hymn to Shri Ram"},"auth":{"t":"Goswami Tulsidas, from the Vinaya Patrika","c":"known"},"occ":["ram-navami","dussehra","diwali","sundarkand"],"when":"Strictly a stuti, not an aarti, but it is the piece most often sung at Ram’s aarti, at Ramayan path and on Ram Navami.","form":"Stuti","dialect":"Braj Bhasha, heavily Sanskritised","refrain":null,"refrainFirst":true,"verses":[{"d":"श्रीरामचन्द्र कृपालु भजु मन, हरण भवभय दारुणम्।\nनवकंज लोचन कंज मुख, कर कंज पद कंजारुणम्॥","r":"Shri Ramchandra kripalu bhaju man, haran bhavbhay daarunam,\nNavkanj lochan kanj mukh, kar kanj pad kanjarunam.","m":"O mind, worship the compassionate Shri Ramchandra, who removes the terrible fear of worldly life: eyes like fresh lotuses, a lotus face, lotus hands and feet like red lotuses.","h":"हे मन, कृपालु श्री रामचन्द्र का भजन कर, जो संसार के भयंकर भय को हरने वाले हैं; जिनके नेत्र नए खिले कमल जैसे हैं, मुख कमल जैसा है, और हाथ-पैर लाल कमल जैसे हैं।"},{"d":"कंदर्प अगणित अमित छवि, नवनील नीरद सुन्दरम्।\nपट पीत मानहुँ तड़ित रुचि, शुचि नौमि जनक सुतावरम्॥","r":"Kandarp aganit amit chhavi, navneel neerad sundaram,\nPat peet maanahun tadit ruchi, shuchi naumi Janak sutavaram.","m":"His beauty outshines countless Kamadevs; he is lovely as a fresh dark rain-cloud, and his yellow robe gleams like lightning. I bow to that pure one, husband of Janak’s daughter.","h":"उनकी छवि अनगिनत कामदेवों से भी बढ़कर है; वे नए नीले बादल जैसे सुन्दर हैं, और उनका पीताम्बर बिजली जैसा चमकता है। जनकपुत्री सीता के पति उन पवित्र प्रभु को मैं नमस्कार करता हूँ।"},{"d":"भजु दीनबन्धु दिनेश दानव, दैत्यवंश निकन्दनम्।\nरघुनन्द आनन्दकन्द कोशलचन्द, दशरथ नन्दनम्॥","r":"Bhaju deenbandhu dinesh daanav, daityavansh nikandanam,\nRaghunand anandkand Koshalchand, Dashrath nandanam.","m":"Worship the friend of the humble, radiant as the sun, who uprooted the clans of demons: joy of the Raghus, root of bliss, moon of Koshal, son of Dasharath.","h":"दीनों के बन्धु, सूर्य जैसे तेजस्वी, दानवों और दैत्यों के वंश का नाश करने वाले, रघुकुल के आनन्द, आनन्द के मूल, कोसल के चन्द्रमा, दशरथनन्दन का भजन कर।"},{"d":"सिर मुकुट कुण्डल तिलक चारु, उदारु अंग विभूषणम्।\nआजानुभुज शर चाप धर, संग्राम जित खरदूषणम्॥","r":"Sir mukut kundal tilak chaaru, udaaru ang vibhooshanam,\nAajanubhuj shar chaap dhar, sangram jit Khar-Dooshanam.","m":"A crown on his head, earrings and a graceful tilak, fine ornaments on every limb; arms reaching to his knees, holding bow and arrows, he defeated Khar and Dooshan in battle.","h":"सिर पर मुकुट, कानों में कुण्डल, माथे पर सुन्दर तिलक और सब अंगों पर सुन्दर आभूषण हैं; घुटनों तक लम्बी भुजाओं में धनुष-बाण हैं, और उन्होंने युद्ध में खर-दूषण को जीता।"},{"d":"इति वदति तुलसीदास शंकर, शेष मुनि मन रंजनम्।\nमम हृदय कंज निवास कुरु, कामादि खलदल गंजनम्॥","r":"Iti vadati Tulsidas Shankar, Shesh muni man ranjanam,\nMam hriday kanj nivaas kuru, kaamaadi khaldal ganjanam.","m":"So says Tulsidas: delight of the hearts of Shankar, Shesh and the sages, make your home in the lotus of my heart and destroy the wicked host of desire and the other vices.","h":"तुलसीदास कहते हैं: हे शंकर, शेष और मुनियों के मन को आनन्द देने वाले, मेरे हृदय-कमल में निवास कीजिए और काम आदि दुष्टों के दल का नाश कीजिए।"}]},{"id":"bhagavad-gita","kind":"granth","deity":"krishna","lang":"sa","language":"Sanskrit","region":"All of India","title":{"d":"श्रीमद्भगवद्गीता","r":"Shrimad Bhagavad Gita","en":"Krishna’s teaching to Arjun on the field of Kurukshetra"},"auth":{"t":"Ved Vyas, in the Bhishma Parva of the Mahabharata","c":"attributed"},"occ":["gita-jayanti","daily"],"when":"Many read a chapter a day, recite the whole Gita on Gita Jayanti, and return to it all their lives.","notes":"700 verses in 18 chapters. Chapters are added one at a time, each with the Sanskrit, a singable Roman version and an English meaning for every verse.","chapters":[{"n":1,"d":"अर्जुनविषादयोग","r":"Arjun Vishad Yog","en":"Arjun’s despair","count":47},{"n":2,"d":"सांख्ययोग","r":"Sankhya Yog","en":"The yoga of knowledge","count":72},{"n":3,"d":"कर्मयोग","r":"Karma Yog","en":"The yoga of action","count":43},{"n":4,"d":"ज्ञानकर्मसंन्यासयोग","r":"Gyan Karma Sanyas Yog","en":"Knowledge and the renunciation of action","count":42},{"n":5,"d":"कर्मसंन्यासयोग","r":"Karma Sanyas Yog","en":"The yoga of renunciation","count":29},{"n":6,"d":"आत्मसंयमयोग","r":"Atma Sanyam Yog","en":"The yoga of meditation","count":47},{"n":7,"d":"ज्ञानविज्ञानयोग","r":"Gyan Vigyan Yog","en":"Knowledge and realisation","count":30},{"n":8,"d":"अक्षरब्रह्मयोग","r":"Akshar Brahma Yog","en":"The imperishable Brahman","count":28},{"n":9,"d":"राजविद्याराजगुह्ययोग","r":"Rajvidya Rajguhya Yog","en":"The royal knowledge and the royal secret","count":34},{"n":10,"d":"विभूतियोग","r":"Vibhuti Yog","en":"The divine glories","count":42},{"n":11,"d":"विश्वरूपदर्शनयोग","r":"Vishwaroop Darshan Yog","en":"The vision of the cosmic form","count":55},{"n":12,"d":"भक्तियोग","r":"Bhakti Yog","en":"The yoga of devotion","count":20,"verses":[{"d":"एवं सततयुक्ता ये भक्तास्त्वां पर्युपासते।\nये चाप्यक्षरमव्यक्तं तेषां के योगवित्तमाः॥","r":"Evam satatayukta ye bhaktastvam paryupasate,\nYe chapyaksharamavyaktam tesham ke yogavittamah.","m":"Some devotees worship you this way, always united with you; others worship the imperishable, the unmanifest. Which of them know yoga best?","h":"जो भक्त इस प्रकार निरन्तर आपमें लगे रहकर आपकी उपासना करते हैं, और जो अविनाशी, अव्यक्त ब्रह्म की उपासना करते हैं, उनमें योग को सबसे अच्छी तरह जानने वाले कौन हैं?","n":"१२.१","sp":{"d":"अर्जुन उवाच","r":"Arjun said"}},{"d":"मय्यावेश्य मनो ये मां नित्ययुक्ता उपासते।\nश्रद्धया परयोपेतास्ते मे युक्ततमा मताः॥","r":"Mayyaveshya mano ye mam nityayukta upasate,\nShraddhaya parayopetaste me yuktatama matah.","m":"Those who fix their minds on me and worship me, always devoted and filled with the highest faith: I consider them the most perfect in yoga.","h":"जो मुझमें मन लगाकर, सदा मुझसे जुड़े रहकर और परम श्रद्धा से युक्त होकर मेरी उपासना करते हैं, वे मेरे मत में सबसे श्रेष्ठ योगी हैं।","n":"१२.२","sp":{"d":"श्रीभगवानुवाच","r":"The Lord said"}},{"d":"ये त्वक्षरमनिर्देश्यमव्यक्तं पर्युपासते।\nसर्वत्रगमचिन्त्यं च कूटस्थमचलं ध्रुवम्॥","r":"Ye tvaksharamanirdeshyamavyaktam paryupasate,\nSarvatragamachintyam cha kootasthamachalam dhruvam.","m":"But those who worship the imperishable, the indescribable, the unmanifest, present everywhere, beyond thought, unchanging, unmoving and eternal,","h":"परन्तु जो अविनाशी, अवर्णनीय, अव्यक्त, सर्वव्यापी, अचिन्त्य, कूटस्थ, अचल और नित्य ब्रह्म की उपासना करते हैं,","n":"१२.३"},{"d":"संनियम्येन्द्रियग्रामं सर्वत्र समबुद्धयः।\nते प्राप्नुवन्ति मामेव सर्वभूतहिते रताः॥","r":"Sanniyamyendriyagramam sarvatra samabuddhayah,\nTe prapnuvanti mameva sarvabhootahite ratah.","m":"who restrain all their senses, stay even-minded everywhere and delight in the good of all beings: they too come to me.","h":"जो सब इन्द्रियों को वश में करके, सब जगह समबुद्धि रखते हुए, सब प्राणियों के हित में लगे रहते हैं, वे भी मुझे ही प्राप्त होते हैं।","n":"१२.४"},{"d":"क्लेशोऽधिकतरस्तेषामव्यक्तासक्तचेतसाम्।\nअव्यक्ता हि गतिर्दुःखं देहवद्भिरवाप्यते॥","r":"Klesho’dhikatarasteshamavyaktasaktachetasam,\nAvyakta hi gatirduhkham dehavadbhiravapyate.","m":"But the way is harder for those whose minds are set on the unmanifest, for embodied beings reach that formless goal only with great difficulty.","h":"किन्तु जिनका चित्त अव्यक्त में आसक्त है, उनके लिए कष्ट अधिक है, क्योंकि देहधारियों के लिए अव्यक्त की गति बड़ी कठिनाई से प्राप्त होती है।","n":"१२.५"},{"d":"ये तु सर्वाणि कर्माणि मयि संन्यस्य मत्पराः।\nअनन्येनैव योगेन मां ध्यायन्त उपासते॥","r":"Ye tu sarvani karmani mayi sannyasya matparah,\nAnanyenaiva yogena mam dhyayanta upasate.","m":"Those who offer all their actions to me, hold me as their highest goal, and worship me with undivided devotion, meditating on me,","h":"परन्तु जो सब कर्मों को मुझे अर्पित करके, मुझे ही परम लक्ष्य मानकर, अनन्य भक्तियोग से मेरा ध्यान करते हुए मेरी उपासना करते हैं,","n":"१२.६"},{"d":"तेषामहं समुद्धर्ता मृत्युसंसारसागरात्।\nभवामि नचिरात्पार्थ मय्यावेशितचेतसाम्॥","r":"Teshamaham samuddharta mrityusamsarasagarat,\nBhavami nachiratpartha mayyaveshitachetasam.","m":"for them, whose minds have entered into me, I soon become the one who lifts them out of the ocean of death and rebirth, Partha.","h":"हे पार्थ, मुझमें चित्त लगाने वाले उन भक्तों का मैं शीघ्र ही मृत्युरूपी संसार-सागर से उद्धार करने वाला बन जाता हूँ।","n":"१२.७"},{"d":"मय्येव मन आधत्स्व मयि बुद्धिं निवेशय।\nनिवसिष्यसि मय्येव अत ऊर्ध्वं न संशयः॥","r":"Mayyeva mana adhatsva mayi buddhim niveshaya,\nNivasishyasi mayyeva ata urdhvam na samshayah.","m":"Fix your mind on me alone and let your understanding rest in me. From then on you will live in me; of this there is no doubt.","h":"अपना मन मुझमें ही लगाओ और अपनी बुद्धि मुझमें ही स्थिर करो। इसके बाद तुम मुझमें ही निवास करोगे, इसमें कोई संशय नहीं।","n":"१२.८"},{"d":"अथ चित्तं समाधातुं न शक्नोषि मयि स्थिरम्।\nअभ्यासयोगेन ततो मामिच्छाप्तुं धनञ्जय॥","r":"Atha chittam samadhatum na shaknoshi mayi sthiram,\nAbhyasayogena tato mamichchhaptum Dhananjaya.","m":"If you cannot hold your mind steadily on me, then seek to reach me through the yoga of regular practice, Dhananjay.","h":"हे धनंजय, यदि तुम अपने चित्त को मुझमें स्थिर नहीं रख सकते, तो अभ्यासयोग के द्वारा मुझे प्राप्त करने की इच्छा करो।","n":"१२.९"},{"d":"अभ्यासेऽप्यसमर्थोऽसि मत्कर्मपरमो भव।\nमदर्थमपि कर्माणि कुर्वन्सिद्धिमवाप्स्यसि॥","r":"Abhyase’pyasamartho’si matkarmaparamo bhava,\nMadarthamapi karmani kurvansiddhimavapsyasi.","m":"If you cannot even practise, make work done for me your highest aim. Even by doing your actions for my sake, you will reach perfection.","h":"यदि तुम अभ्यास में भी असमर्थ हो, तो मेरे लिए कर्म करने को ही परम लक्ष्य बना लो। मेरे लिए कर्म करते हुए भी तुम सिद्धि प्राप्त करोगे।","n":"१२.१०"},{"d":"अथैतदप्यशक्तोऽसि कर्तुं मद्योगमाश्रितः।\nसर्वकर्मफलत्यागं ततः कुरु यतात्मवान्॥","r":"Athaitadapyashakto’si kartum madyogamashritah,\nSarvakarmaphalatyagam tatah kuru yatatmavan.","m":"And if you cannot do even this, then take refuge in me, master yourself, and let go of the fruits of all your actions.","h":"और यदि यह भी नहीं कर सकते, तो मेरी शरण लेकर, मन को वश में करके, सब कर्मों के फल का त्याग करो।","n":"१२.११"},{"d":"श्रेयो हि ज्ञानमभ्यासाज्ज्ञानाद्ध्यानं विशिष्यते।\nध्यानात्कर्मफलत्यागस्त्यागाच्छान्तिरनन्तरम्॥","r":"Shreyo hi jnanamabhyasajjnanaddhyanam vishishyate,\nDhyanatkarmaphalatyagastyagachchhantiranantaram.","m":"Knowledge is better than mere practice, and meditation better than knowledge. Better still is letting go of the fruits of action, for peace follows at once.","h":"अभ्यास से ज्ञान श्रेष्ठ है, ज्ञान से ध्यान श्रेष्ठ है, और ध्यान से कर्मफल का त्याग श्रेष्ठ है, क्योंकि त्याग से तुरन्त शान्ति मिलती है।","n":"१२.१२"},{"d":"अद्वेष्टा सर्वभूतानां मैत्रः करुण एव च।\nनिर्ममो निरहङ्कारः समदुःखसुखः क्षमी॥","r":"Adveshta sarvabhootanam maitrah karuna eva cha,\nNirmamo nirahankarah samaduhkhasukhah kshami.","m":"One who hates no being, who is friendly and compassionate, free of possessiveness and ego, the same in pain and pleasure, and forgiving,","h":"जो किसी प्राणी से द्वेष नहीं करता, सबका मित्र और दयालु है, ममता और अहंकार से रहित है, सुख-दुःख में समान और क्षमाशील है,","n":"१२.१३"},{"d":"सन्तुष्टः सततं योगी यतात्मा दृढनिश्चयः।\nमय्यर्पितमनोबुद्धिर्यो मद्भक्तः स मे प्रियः॥","r":"Santushtah satatam yogi yatatma dridhanishchayah,\nMayyarpitamanobuddhiryo madbhaktah sa me priyah.","m":"always content, steady in yoga, self-controlled and firm in resolve, with mind and understanding offered to me: that devotee is dear to me.","h":"जो सदा सन्तुष्ट है, योगी है, मन को वश में रखता है, दृढ़ निश्चय वाला है, और जिसने अपना मन और बुद्धि मुझे अर्पित कर दी है, वह मेरा भक्त मुझे प्रिय है।","n":"१२.१४"},{"d":"यस्मान्नोद्विजते लोको लोकान्नोद्विजते च यः।\nहर्षामर्षभयोद्वेगैर्मुक्तो यः स च मे प्रियः॥","r":"Yasmannodvijate loko lokannodvijate cha yah,\nHarshamarshabhayodvegairmukto yah sa cha me priyah.","m":"One who troubles no one and is not troubled by anyone, who is free from elation, envy, fear and anxiety, is dear to me.","h":"जिससे कोई प्राणी उद्विग्न नहीं होता और जो स्वयं किसी से उद्विग्न नहीं होता, जो हर्ष, ईर्ष्या, भय और उद्वेग से मुक्त है, वह मुझे प्रिय है।","n":"१२.१५"},{"d":"अनपेक्षः शुचिर्दक्ष उदासीनो गतव्यथः।\nसर्वारम्भपरित्यागी यो मद्भक्तः स मे प्रियः॥","r":"Anapekshah shuchirdaksha udasino gatavyathah,\nSarvarambhaparityagi yo madbhaktah sa me priyah.","m":"One who expects nothing, is pure and capable, impartial and untroubled, and has given up all self-centred undertakings: that devotee is dear to me.","h":"जो किसी से कुछ अपेक्षा नहीं रखता, पवित्र और कुशल है, निष्पक्ष है, व्यथा से रहित है, और जिसने सब स्वार्थपूर्ण आरम्भों का त्याग कर दिया है, वह मेरा भक्त मुझे प्रिय है।","n":"१२.१६"},{"d":"यो न हृष्यति न द्वेष्टि न शोचति न काङ्क्षति।\nशुभाशुभपरित्यागी भक्तिमान्यः स मे प्रियः॥","r":"Yo na hrishyati na dveshti na shochati na kankshati,\nShubhashubhaparityagi bhaktimanyah sa me priyah.","m":"One who neither rejoices nor hates, neither grieves nor craves, and has let go of both good and bad outcomes, full of devotion, is dear to me.","h":"जो न हर्षित होता है, न द्वेष करता है, न शोक करता है, न कामना करता है, और जिसने शुभ-अशुभ दोनों का त्याग कर दिया है, वह भक्तिमान मुझे प्रिय है।","n":"१२.१७"},{"d":"समः शत्रौ च मित्रे च तथा मानापमानयोः।\nशीतोष्णसुखदुःखेषु समः सङ्गविवर्जितः॥","r":"Samah shatrau cha mitre cha tatha manapamanayoh,\nShitoshnasukhaduhkheshu samah sangavivarjitah.","m":"One who is the same to friend and foe, in honour and in insult, in cold and heat, in pleasure and pain, and free from attachment,","h":"जो शत्रु और मित्र में, मान और अपमान में, सर्दी-गर्मी और सुख-दुःख में समान रहता है और आसक्ति से रहित है,","n":"१२.१८"},{"d":"तुल्यनिन्दास्तुतिर्मौनी सन्तुष्टो येन केनचित्।\nअनिकेतः स्थिरमतिर्भक्तिमान्मे प्रियो नरः॥","r":"Tulyanindastutirmauni santushto yena kenachit,\nAniketah sthiramatirbhaktimanme priyo narah.","m":"who takes blame and praise alike, speaks little, is content with whatever comes, is not bound to any home, steady of mind and full of devotion: that person is dear to me.","h":"जो निन्दा और स्तुति को समान समझता है, मननशील है, जो कुछ मिल जाए उसी में सन्तुष्ट है, किसी घर से बँधा नहीं, स्थिर बुद्धि वाला और भक्तिमान है, वह मनुष्य मुझे प्रिय है।","n":"१२.१९"},{"d":"ये तु धर्म्यामृतमिदं यथोक्तं पर्युपासते।\nश्रद्दधाना मत्परमा भक्तास्तेऽतीव मे प्रियाः॥","r":"Ye tu dharmyamritamidam yathoktam paryupasate,\nShraddadhana matparama bhaktaste’tiva me priyah.","m":"And those who follow this nectar of dharma just as I have taught it, with faith, holding me as their highest goal: those devotees are dearer to me than all.","h":"और जो श्रद्धा रखते हुए, मुझे परम लक्ष्य मानकर, मेरे बताए इस धर्ममय अमृत का पालन करते हैं, वे भक्त मुझे अत्यन्त प्रिय हैं।","n":"१२.२०"},{"d":"ॐ तत्सदिति श्रीमद्भगवद्गीतासूपनिषत्सु ब्रह्मविद्यायां योगशास्त्रे श्रीकृष्णार्जुनसंवादे भक्तियोगो नाम द्वादशोऽध्यायः॥","r":"Om tat sat. Iti Shrimad Bhagavad Gitasu Upanishatsu Brahmavidyayam Yogashastre Shri Krishnarjuna samvade Bhaktiyogo nama dvadasho’dhyayah.","m":"Om, that is the truth. So ends the twelfth chapter, the Yoga of Devotion, in the dialogue between Shri Krishna and Arjun, the Upanishad of the Gita, the knowledge of Brahman and the scripture of yoga.","h":"ॐ तत् सत्। इस प्रकार श्रीमद्भगवद्गीता रूपी उपनिषद्, ब्रह्मविद्या और योगशास्त्र में, श्रीकृष्ण और अर्जुन के संवाद में भक्तियोग नामक बारहवाँ अध्याय समाप्त होता है।","n":"इति"}],"intro":"Arjun asks who knows yoga best: those who worship Krishna in his personal form, or those who meditate on the formless. Krishna answers, offers easier paths for those who find it hard, and ends with a portrait of the devotee he loves."},{"n":13,"d":"क्षेत्रक्षेत्रज्ञविभागयोग","r":"Kshetra Kshetragya Vibhag Yog","en":"The field and the knower of the field","count":34},{"n":14,"d":"गुणत्रयविभागयोग","r":"Gunatraya Vibhag Yog","en":"The three gunas","count":27},{"n":15,"d":"पुरुषोत्तमयोग","r":"Purushottam Yog","en":"The Supreme Person","count":20,"verses":[{"d":"ऊर्ध्वमूलमधःशाखमश्वत्थं प्राहुरव्ययम्।\nछन्दांसि यस्य पर्णानि यस्तं वेद स वेदवित्॥","r":"Urdhvamoolamadhahshakhamashvattham prahuravyayam,\nChhandamsi yasya parnani yastam veda sa vedavit.","m":"They speak of an eternal ashvattha tree with its roots above and its branches below, whose leaves are the Vedic hymns. Whoever knows this tree knows the Vedas.","h":"ज्ञानी लोग एक अविनाशी अश्वत्थ (पीपल) वृक्ष की बात करते हैं, जिसकी जड़ें ऊपर और शाखाएँ नीचे हैं, और वेद के छन्द जिसके पत्ते हैं। जो इस वृक्ष को जानता है, वही वेदों को जानने वाला है।","n":"१५.१","sp":{"d":"श्रीभगवानुवाच","r":"The Lord said"}},{"d":"अधश्चोर्ध्वं प्रसृतास्तस्य शाखा गुणप्रवृद्धा विषयप्रवालाः।\nअधश्च मूलान्यनुसन्ततानि कर्मानुबन्धीनि मनुष्यलोके॥","r":"Adhashchordhvam prasritastasya shakha gunapravriddha vishayapravalah,\nAdhashcha moolanyanusantatani karmanubandhini manushyaloke.","m":"Its branches spread below and above, fed by the gunas, with the objects of the senses as their buds. Below, in the human world, its roots spread out, binding beings to action.","h":"इसकी शाखाएँ नीचे और ऊपर फैली हैं, जो गुणों से बढ़ी हैं और विषय जिनकी कोंपलें हैं। नीचे मनुष्यलोक में इसकी जड़ें फैली हुई हैं, जो कर्मों से बाँधती हैं।","n":"१५.२"},{"d":"न रूपमस्येह तथोपलभ्यते नान्तो न चादिर्न च सम्प्रतिष्ठा।\nअश्वत्थमेनं सुविरूढमूलमसङ्गशस्त्रेण दृढेन छित्त्वा॥","r":"Na roopamasyeha tathopalabhyate nanto na chadirna cha sampratishtha,\nAshvatthamenam suviroodhamoolamasangashastrena dridhena chhittva.","m":"Its real form cannot be seen here, nor its end, nor its beginning, nor what it stands on. Cutting down this deep-rooted tree with the strong axe of detachment,","h":"इस संसार में इसका वास्तविक रूप दिखाई नहीं देता, न इसका अन्त, न आदि, न आधार। इस गहरी जड़ों वाले अश्वत्थ वृक्ष को वैराग्य रूपी दृढ़ शस्त्र से काटकर,","n":"१५.३"},{"d":"ततः पदं तत्परिमार्गितव्यं यस्मिन्गता न निवर्तन्ति भूयः।\nतमेव चाद्यं पुरुषं प्रपद्ये यतः प्रवृत्तिः प्रसृता पुराणी॥","r":"Tatah padam tatparimargitavyam yasmingata na nivartanti bhuyah,\nTameva chadyam purusham prapadye yatah pravrittih prasrita purani.","m":"one should seek that state from which there is no return, saying: “I take refuge in that first Person from whom this ancient stream of creation flows.”","h":"उस परम पद को खोजना चाहिए जहाँ पहुँचकर फिर कोई लौटता नहीं, और यह भाव रखना चाहिए: “मैं उस आदि पुरुष की शरण लेता हूँ, जिससे यह पुरातन सृष्टि का प्रवाह फैला है।”","n":"१५.४"},{"d":"निर्मानमोहा जितसङ्गदोषा अध्यात्मनित्या विनिवृत्तकामाः।\nद्वन्द्वैर्विमुक्ताः सुखदुःखसंज्ञैर्गच्छन्त्यमूढाः पदमव्ययं तत्॥","r":"Nirmanamoha jitasangadosha adhyatmanitya vinivrittakamah,\nDvandvairvimuktah sukhaduhkhasanjnairgachchhantyamoodhah padamavyayam tat.","m":"Free from pride and delusion, having conquered attachment, always dwelling on the Self, with desires stilled and released from the opposites called pleasure and pain, the wise reach that eternal state.","h":"जो मान और मोह से रहित हैं, जिन्होंने आसक्ति के दोष को जीत लिया है, जो सदा अध्यात्म में लगे रहते हैं, जिनकी कामनाएँ शान्त हो गई हैं और जो सुख-दुःख नामक द्वन्द्वों से मुक्त हैं, वे ज्ञानी उस अविनाशी पद को प्राप्त होते हैं।","n":"१५.५"},{"d":"न तद्भासयते सूर्यो न शशाङ्को न पावकः।\nयद्गत्वा न निवर्तन्ते तद्धाम परमं मम॥","r":"Na tadbhasayate suryo na shashanko na pavakah,\nYadgatva na nivartante taddhama paramam mama.","m":"No sun, moon or fire lights that place. Those who reach it never return: that is my supreme home.","h":"उस स्थान को न सूर्य प्रकाशित करता है, न चन्द्रमा, न अग्नि। जहाँ पहुँचकर कोई लौटता नहीं, वही मेरा परम धाम है।","n":"१५.६"},{"d":"ममैवांशो जीवलोके जीवभूतः सनातनः।\nमनःषष्ठानीन्द्रियाणि प्रकृतिस्थानि कर्षति॥","r":"Mamaivamsho jivaloke jivabhootah sanatanah,\nManahshashthanindriyani prakritisthani karshati.","m":"An eternal part of me becomes the living soul in the world of beings, and draws to itself the five senses and the mind, which belong to nature.","h":"इस जीवलोक में जीवात्मा मेरा ही सनातन अंश है, और वह प्रकृति में स्थित पाँच इन्द्रियों और छठे मन को अपनी ओर खींचता है।","n":"१५.७"},{"d":"शरीरं यदवाप्नोति यच्चाप्युत्क्रामतीश्वरः।\nगृहीत्वैतानि संयाति वायुर्गन्धानिवाशयात्॥","r":"Shariram yadavapnoti yachchapyutkramatishvarah,\nGrihitvaitani samyati vayurgandhanivashayat.","m":"When the soul, the master of the body, takes up a body or leaves it, it carries these along, as the wind carries scents from flowers.","h":"जब शरीर का स्वामी जीवात्मा कोई शरीर पाता है या उसे छोड़ता है, तब वह इन्हें साथ लेकर वैसे ही चला जाता है जैसे वायु फूलों से गन्ध ले जाती है।","n":"१५.८"},{"d":"श्रोत्रं चक्षुः स्पर्शनं च रसनं घ्राणमेव च।\nअधिष्ठाय मनश्चायं विषयानुपसेवते॥","r":"Shrotram chakshuh sparshanam cha rasanam ghranameva cha,\nAdhishthaya manashchayam vishayanupasevate.","m":"Presiding over hearing, sight, touch, taste and smell, and over the mind, it experiences the objects of the senses.","h":"कान, आँख, त्वचा, जीभ और नाक, तथा मन का आश्रय लेकर यह जीवात्मा विषयों का अनुभव करता है।","n":"१५.९"},{"d":"उत्क्रामन्तं स्थितं वापि भुञ्जानं वा गुणान्वितम्।\nविमूढा नानुपश्यन्ति पश्यन्ति ज्ञानचक्षुषः॥","r":"Utkramantam sthitam vapi bhunjanam va gunanvitam,\nVimoodha nanupashyanti pashyanti jnanachakshushah.","m":"The deluded do not see it leaving the body, staying in it, or enjoying the world through the gunas. Those with the eye of wisdom see it.","h":"शरीर छोड़ते हुए, शरीर में रहते हुए या गुणों के साथ विषयों को भोगते हुए भी मूढ़ लोग इसे नहीं देखते; ज्ञान की आँखों वाले इसे देखते हैं।","n":"१५.१०"},{"d":"यतन्तो योगिनश्चैनं पश्यन्त्यात्मन्यवस्थितम्।\nयतन्तोऽप्यकृतात्मानो नैनं पश्यन्त्यचेतसः॥","r":"Yatanto yoginashchainam pashyantyatmanyavasthitam,\nYatanto’pyakritatmano nainam pashyantyachetasah.","m":"Yogis who strive see it dwelling within themselves; but the unprepared and unaware do not see it, even when they try.","h":"प्रयत्न करने वाले योगी इसे अपने भीतर स्थित देखते हैं; पर जिनका अन्तःकरण शुद्ध नहीं है, वे अज्ञानी प्रयत्न करके भी इसे नहीं देखते।","n":"१५.११"},{"d":"यदादित्यगतं तेजो जगद्भासयतेऽखिलम्।\nयच्चन्द्रमसि यच्चाग्नौ तत्तेजो विद्धि मामकम्॥","r":"Yadadityagatam tejo jagadbhasayate’khilam,\nYachchandramasi yachchagnau tattejo viddhi mamakam.","m":"The light of the sun that brightens the whole world, and the light in the moon and in fire: know that light to be mine.","h":"सूर्य में स्थित जो तेज सारे जगत को प्रकाशित करता है, और जो तेज चन्द्रमा और अग्नि में है, उस तेज को तुम मेरा ही जानो।","n":"१५.१२"},{"d":"गामाविश्य च भूतानि धारयाम्यहमोजसा।\nपुष्णामि चौषधीः सर्वाः सोमो भूत्वा रसात्मकः॥","r":"Gamavishya cha bhootani dharayamyahamojasa,\nPushnami chaushadhih sarvah somo bhootva rasatmakah.","m":"Entering the earth, I hold up all beings with my strength; becoming the moon, full of sap, I nourish every plant.","h":"मैं पृथ्वी में प्रवेश करके अपनी शक्ति से सब प्राणियों को धारण करता हूँ, और रस से भरा चन्द्रमा बनकर सब वनस्पतियों का पोषण करता हूँ।","n":"१५.१३"},{"d":"अहं वैश्वानरो भूत्वा प्राणिनां देहमाश्रितः।\nप्राणापानसमायुक्तः पचाम्यन्नं चतुर्विधम्॥","r":"Aham vaishvanaro bhootva praninam dehamashritah,\nPranapanasamayuktah pachamyannam chaturvidham.","m":"Becoming the digestive fire in the bodies of living beings, joined with the in-breath and out-breath, I digest the four kinds of food.","h":"मैं प्राणियों के शरीर में वैश्वानर अग्नि बनकर, प्राण और अपान से मिलकर, चार प्रकार के अन्न को पचाता हूँ।","n":"१५.१४"},{"d":"सर्वस्य चाहं हृदि सन्निविष्टो मत्तः स्मृतिर्ज्ञानमपोहनं च।\nवेदैश्च सर्वैरहमेव वेद्यो वेदान्तकृद्वेदविदेव चाहम्॥","r":"Sarvasya chaham hridi sannivishto mattah smritirjnanamapohanam cha,\nVedaishcha sarvairahameva vedyo vedantakridvedavideva chaham.","m":"I am seated in the hearts of all; from me come memory, knowledge and their loss. I alone am what all the Vedas seek to know; I am the author of the Vedanta and the knower of the Vedas.","h":"मैं सबके हृदय में स्थित हूँ; मुझसे ही स्मृति, ज्ञान और उनका लोप होता है। सब वेदों द्वारा जानने योग्य मैं ही हूँ; वेदान्त का रचयिता और वेदों को जानने वाला भी मैं ही हूँ।","n":"१५.१५"},{"d":"द्वाविमौ पुरुषौ लोके क्षरश्चाक्षर एव च।\nक्षरः सर्वाणि भूतानि कूटस्थोऽक्षर उच्यते॥","r":"Dvavimau purushau loke ksharashchakshara eva cha,\nKsharah sarvani bhootani kootastho’kshara uchyate.","m":"There are two persons in this world, the perishable and the imperishable. All beings are perishable; the unchanging one is called imperishable.","h":"इस संसार में दो पुरुष हैं, क्षर (नाशवान) और अक्षर (अविनाशी)। सब प्राणी क्षर हैं और जो कूटस्थ (अपरिवर्तनशील) है, वह अक्षर कहलाता है।","n":"१५.१६"},{"d":"उत्तमः पुरुषस्त्वन्यः परमात्मेत्युदाहृतः।\nयो लोकत्रयमाविश्य बिभर्त्यव्यय ईश्वरः॥","r":"Uttamah purushastvanyah paramatmetyudahritah,\nYo lokatrayamavishya bibhartyavyaya ishvarah.","m":"But there is another, the highest Person, called the Supreme Self: the eternal Lord who enters the three worlds and sustains them.","h":"परन्तु उत्तम पुरुष इनसे अलग है, जिसे परमात्मा कहा जाता है; वही अविनाशी ईश्वर तीनों लोकों में प्रवेश करके उनका पालन करता है।","n":"१५.१७"},{"d":"यस्मात्क्षरमतीतोऽहमक्षरादपि चोत्तमः।\nअतोऽस्मि लोके वेदे च प्रथितः पुरुषोत्तमः॥","r":"Yasmatksharamatito’hamaksharadapi chottamah,\nAto’smi loke vede cha prathitah purushottamah.","m":"Because I am beyond the perishable and higher even than the imperishable, I am known in the world and in the Veda as Purushottam, the Supreme Person.","h":"क्योंकि मैं क्षर से परे हूँ और अक्षर से भी उत्तम हूँ, इसलिए संसार में और वेद में मैं पुरुषोत्तम नाम से प्रसिद्ध हूँ।","n":"१५.१८"},{"d":"यो मामेवमसम्मूढो जानाति पुरुषोत्तमम्।\nस सर्वविद्भजति मां सर्वभावेन भारत॥","r":"Yo mamevamasammoodho janati purushottamam,\nSa sarvavidbhajati mam sarvabhavena Bharata.","m":"Whoever, free from delusion, knows me as the Supreme Person knows everything, and worships me with their whole being, Bharata.","h":"हे भारत, जो मोहरहित होकर मुझे इस प्रकार पुरुषोत्तम जानता है, वह सब कुछ जानने वाला है और सम्पूर्ण भाव से मुझे भजता है।","n":"१५.१९"},{"d":"इति गुह्यतमं शास्त्रमिदमुक्तं मयानघ।\nएतद्बुद्ध्वा बुद्धिमान्स्यात्कृतकृत्यश्च भारत॥","r":"Iti guhyatamam shastramidamuktam mayanagha,\nEtadbuddhva buddhimansyatkritakrityashcha Bharata.","m":"So I have given you this most secret teaching, sinless one. Whoever understands it becomes truly wise and has done all there is to do, Bharata.","h":"हे निष्पाप अर्जुन, इस प्रकार मैंने यह अत्यन्त गुप्त शास्त्र तुमसे कहा। हे भारत, इसे जानकर मनुष्य बुद्धिमान और कृतार्थ हो जाता है।","n":"१५.२०"},{"d":"ॐ तत्सदिति श्रीमद्भगवद्गीतासूपनिषत्सु ब्रह्मविद्यायां योगशास्त्रे श्रीकृष्णार्जुनसंवादे पुरुषोत्तमयोगो नाम पञ्चदशोऽध्यायः॥","r":"Om tat sat. Iti Shrimad Bhagavad Gitasu Upanishatsu Brahmavidyayam Yogashastre Shri Krishnarjuna samvade Purushottamayogo nama panchadasho’dhyayah.","m":"Om, that is the truth. So ends the fifteenth chapter, the Yoga of the Supreme Person, in the dialogue between Shri Krishna and Arjun, the Upanishad of the Gita, the knowledge of Brahman and the scripture of yoga.","h":"ॐ तत् सत्। इस प्रकार श्रीमद्भगवद्गीता रूपी उपनिषद्, ब्रह्मविद्या और योगशास्त्र में, श्रीकृष्ण और अर्जुन के संवाद में पुरुषोत्तमयोग नामक पन्द्रहवाँ अध्याय समाप्त होता है।","n":"इति"}],"intro":"Krishna describes the world as an upside-down tree to be cut down with detachment, explains how the soul moves from body to body, and reveals himself as Purushottam, the Supreme Person beyond both the perishable and the imperishable. Many ashrams and families recite this chapter before meals."},{"n":16,"d":"दैवासुरसम्पद्विभागयोग","r":"Daivasur Sampad Vibhag Yog","en":"The divine and the demonic","count":24},{"n":17,"d":"श्रद्धात्रयविभागयोग","r":"Shraddhatraya Vibhag Yog","en":"The three kinds of faith","count":28},{"n":18,"d":"मोक्षसंन्यासयोग","r":"Moksha Sanyas Yog","en":"Freedom through renunciation","count":78}]},{"id":"durga-saptashati","kind":"granth","deity":"durga","lang":"sa","language":"Sanskrit","region":"All of India","title":{"d":"श्रीदुर्गासप्तशती","r":"Shri Durga Saptashati","en":"The seven hundred verses of the Goddess (Devi Mahatmya, Chandi Path)"},"auth":{"t":"From the Markandeya Purana, as told by the sage Markandeya","c":"traditional"},"occ":["navratri","dussehra"],"when":"Read in full on each day of Navratri, or spread across the nine days, and on Ashtami and Navami with a havan. Many homes read the three stutis (chapters 4, 5 and 11) even when there is no time for the whole path.","notes":"700 mantras in 13 chapters, chapters 81 to 93 of the Markandeya Purana. They form three episodes: the first (chapter 1, Mahakali), the middle (chapters 2 to 4, Mahalakshmi) and the last (chapters 5 to 13, Mahasaraswati). Verse numbers follow the Gita Press edition, which gives speaker lines such as ऋषिरुवाच a number of their own. Chapters are being added one at a time; so far chapter 4, chapter 11 and the Ya Devi Sarvabhuteshu hymn of chapter 5 are in, and the other chapters have a summary until their verses are entered.","kw":["saptashati","saptshati","durga path","chandi path","chandi","devi mahatmya","devi mahatmyam","markandeya purana"],"chapters":[{"n":1,"d":"मधुकैटभवध","r":"Madhu Kaitabh Vadh","en":"The slaying of Madhu and Kaitabh","count":104,"sum":"King Suratha, driven from his kingdom, and the merchant Samadhi, cast out by his family, meet in the forest hermitage of the sage Medha and ask why their minds still cling to what betrayed them. The sage tells them of Mahamaya, the Goddess’s power of illusion. At the end of an age, as Vishnu sleeps on the cosmic waters, two demons, Madhu and Kaitabh, spring from the wax of his ears and attack Brahma. Brahma praises the Goddess as Yoganidra, the sleep of Vishnu, and she withdraws from Vishnu, who wakes and slays the demons."},{"n":2,"d":"महिषासुरसैन्यवध","r":"Mahishasur Sainya Vadh","en":"The destruction of Mahishasur’s armies","count":69,"sum":"Mahishasur, the buffalo demon, has defeated the gods and taken heaven. Their anger pours out of Brahma, Vishnu, Shiv and every god as light, and the light gathers into the form of the Goddess. Each god gives her a weapon: Shiv his trident, Vishnu his discus, Indra his thunderbolt, the Himalaya a lion to ride. She roars, and in the battle that follows she destroys Mahishasur’s generals and their armies."},{"n":3,"d":"महिषासुरवध","r":"Mahishasur Vadh","en":"The slaying of Mahishasur","count":44,"sum":"The Goddess kills the generals Chikshura, Chamara and others. Mahishasur himself attacks, changing from buffalo to lion to man to elephant and back. She drinks the divine drink, laughs, presses him down with her foot and pierces him with her trident, and as he half emerges from the buffalo’s mouth she strikes off his head."},{"n":4,"d":"शक्रादिस्तुति","r":"Shakradi Stuti","en":"Indra and the gods praise the Goddess","count":42,"sum":"With Mahishasur dead, Indra and the gods bow before the Goddess and praise her in one of the great hymns of the text: she is the power behind all the gods, the fortune in good homes and the misfortune in wicked ones, and her anger itself is a mercy. She promises to come whenever they remember her in distress.","verses":[{"d":"शक्रादयः सुरगणा निहतेऽतिवीर्ये तस्मिन्दुरात्मनि सुरारिबले च देव्या।\nतां तुष्टुवुः प्रणतिनम्रशिरोधरांसा वाग्भिः प्रहर्षपुलकोद्गमचारुदेहाः॥","r":"Shakradayah suragana nihate’tivirye tasmin duratmani suraribale cha devya,\nTam tushtuvuh pranatinamrashirodharansa vagbhih praharshapulakodgamacharudehah.","m":"When the Goddess had slain that mighty, wicked demon and the army of the gods’ enemies, Indra and the hosts of gods praised her, their heads and shoulders bowed low, their bodies beautiful with the thrill of joy.","h":"जब देवी ने उस अत्यन्त पराक्रमी दुष्ट असुर और देवशत्रुओं की सेना को मार डाला, तब इन्द्र आदि देवगण गर्दन और कन्धे झुकाकर, हर्ष से पुलकित सुन्दर शरीरों के साथ, वाणी से उनकी स्तुति करने लगे।","n":"४.२","sp":{"d":"ऋषिरुवाच","r":"The sage said","no":1}},{"d":"देव्या यया ततमिदं जगदात्मशक्त्या निःशेषदेवगणशक्तिसमूहमूर्त्या।\nतामम्बिकामखिलदेवमहर्षिपूज्यां भक्त्या नताः स्म विदधातु शुभानि सा नः॥","r":"Devya yaya tatamidam jagadatmashaktya nihsheshadevaganashaktisamuhamurtya,\nTamambikamakhiladevamaharshipujyam bhaktya natah sma vidadhatu shubhani sa nah.","m":"The Goddess who by her own power pervades this world, whose form is the gathered power of all the gods, Ambika, worshipped by all gods and great sages: we bow to her in devotion. May she bring us good.","h":"जिन देवी ने अपनी शक्ति से इस सारे जगत को व्याप्त कर रखा है, जो सम्पूर्ण देवताओं की शक्तियों के समूह का स्वरूप हैं, सब देवताओं और महर्षियों से पूजित उन अम्बिका को हम भक्तिपूर्वक प्रणाम करते हैं। वे हमारा कल्याण करें।","n":"४.३"},{"d":"यस्याः प्रभावमतुलं भगवाननन्तो ब्रह्मा हरश्च न हि वक्तुमलं बलं च।\nसा चण्डिकाखिलजगत्परिपालनाय नाशाय चाशुभभयस्य मतिं करोतु॥","r":"Yasyah prabhavamatulam bhagavananantho Brahma Harashcha na hi vaktumalam balam cha,\nSa Chandikakhilajagatparipalanaya nashaya chashubhabhayasya matim karotu.","m":"Whose matchless glory and strength not even Lord Vishnu, Brahma or Shiv can describe: may that Chandika set her mind on protecting the whole world and destroying the fear of evil.","h":"जिनके अतुलनीय प्रभाव और बल का वर्णन भगवान विष्णु, ब्रह्मा और शिव भी नहीं कर सकते, वे चण्डिका सम्पूर्ण जगत की रक्षा और अशुभ भय के नाश का विचार करें।","n":"४.४"},{"d":"या श्रीः स्वयं सुकृतिनां भवनेष्वलक्ष्मीः पापात्मनां कृतधियां हृदयेषु बुद्धिः।\nश्रद्धा सतां कुलजनप्रभवस्य लज्जा तां त्वां नताः स्म परिपालय देवि विश्वम्॥","r":"Ya shrih svayam sukritinam bhavaneshvalakshmih papatmanam kritadhiyam hridayeshu buddhih,\nShraddha satam kulajanaprabhavasya lajja tam tvam natah sma paripalaya devi vishvam.","m":"You who are fortune itself in the homes of the virtuous and misfortune in the homes of the wicked, understanding in the hearts of the wise, faith in the good and modesty in the well-born: we bow to you. Goddess, protect the world.","h":"जो पुण्यात्माओं के घरों में स्वयं लक्ष्मी और पापियों के घरों में दरिद्रता के रूप में रहती हैं, विवेकी लोगों के हृदय में बुद्धि, सत्पुरुषों में श्रद्धा और कुलीन लोगों में लज्जा के रूप में रहती हैं, उन आपको हम प्रणाम करते हैं। हे देवी, विश्व की रक्षा कीजिए।","n":"४.५"},{"d":"किं वर्णयाम तव रूपमचिन्त्यमेतत्किं चातिवीर्यमसुरक्षयकारि भूरि।\nकिं चाहवेषु चरितानि तवाद्भुतानि सर्वेषु देव्यसुरदेवगणादिकेषु॥","r":"Kim varnayama tava rupamachintyametat kim chativiryamasurakshayakari bhuri,\nKim chahaveshu charitani tavadbhutani sarveshu devyasuradevaganadikeshu.","m":"How can we describe this form of yours that is beyond thought, or your overwhelming might that destroys the demons, or the wonders you performed in battle, Goddess, among demons, gods and all others?","h":"हे देवी, हम आपके इस अचिन्त्य रूप का क्या वर्णन करें? असुरों का नाश करने वाले आपके महान पराक्रम का क्या वर्णन करें? और देवताओं, असुरों आदि सबके बीच युद्ध में किए गए आपके अद्भुत चरित्रों का क्या वर्णन करें?","n":"४.६"},{"d":"हेतुः समस्तजगतां त्रिगुणापि दोषैर्न ज्ञायसे हरिहरादिभिरप्यपारा।\nसर्वाश्रयाखिलमिदं जगदंशभूतमव्याकृता हि परमा प्रकृतिस्त्वमाद्या॥","r":"Hetuh samastajagatam trigunapi doshairna jnayase Hariharadibhirapyapara,\nSarvashrayakhilamidam jagadanshabhutam avyakrita hi parama prakritistvamadya.","m":"You are the cause of all the worlds. Though made of the three qualities, you are untouched by their faults; boundless, you are not fully known even by Vishnu and Shiv. You are the refuge of all; this whole world is a part of you, for you are the unmanifest, supreme, primal Nature.","h":"आप सम्पूर्ण जगत का कारण हैं। त्रिगुणमयी होकर भी आप उनके दोषों से रहित हैं; अपार होने के कारण विष्णु और शिव आदि भी आपको पूरी तरह नहीं जानते। आप सबका आश्रय हैं; यह सारा जगत आपका ही अंश है, क्योंकि आप अव्यक्त, परम, आदि प्रकृति हैं।","n":"४.७"},{"d":"यस्याः समस्तसुरता समुदीरणेन तृप्तिं प्रयाति सकलेषु मखेषु देवि।\nस्वाहासि वै पितृगणस्य च तृप्तिहेतुरुच्चार्यसे त्वमत एव जनैः स्वधा च॥","r":"Yasyah samastasurata samudiranena triptim prayati sakaleshu makheshu devi,\nSvahasi vai pitriganasya cha triptiheturuchcharyase tvamata eva janaih svadha cha.","m":"Goddess, you are Svaha, by whose utterance all the gods are satisfied in every sacrifice; and because you satisfy the ancestors too, people call on you as Svadha.","h":"हे देवी, आप स्वाहा हैं, जिसके उच्चारण से सब यज्ञों में सम्पूर्ण देवता तृप्त होते हैं; और पितरों की तृप्ति का कारण होने से लोग आपको स्वधा भी कहते हैं।","n":"४.८"},{"d":"या मुक्तिहेतुरविचिन्त्यमहाव्रता त्वमभ्यस्यसे सुनियतेन्द्रियतत्त्वसारैः।\nमोक्षार्थिभिर्मुनिभिरस्तसमस्तदोषैर्विद्यासि सा भगवती परमा हि देवि॥","r":"Ya muktiheturavichintyamahavrata tvamabhyasyase suniyatendriyatattvasaraih,\nMokshartibhirmunibhirastasamastadoshair vidyasi sa bhagavati parama hi devi.","m":"Goddess, you are the cause of liberation, the great vow beyond thought, practised by sages who have mastered their senses, who seek freedom and are rid of every fault. You are the blessed, supreme knowledge.","h":"हे देवी, आप मुक्ति का कारण और अचिन्त्य महाव्रत स्वरूपा हैं; इन्द्रियों को वश में करने वाले, तत्त्व को जानने वाले, सब दोषों से रहित मोक्ष चाहने वाले मुनि आपका अभ्यास करते हैं। आप ही वह भगवती परा विद्या हैं।","n":"४.९"},{"d":"शब्दात्मिका सुविमलर्ग्यजुषां निधानमुद्गीथरम्यपदपाठवतां च साम्नाम्।\nदेवी त्रयी भगवती भवभावनाय वार्ता च सर्वजगतां परमार्तिहन्त्री॥","r":"Shabdatmika suvimalargyajusham nidhanam udgitharamyapadapathavatam cha samnam,\nDevi trayi bhagavati bhavabhavanaya varta cha sarvajagatam paramartihantri.","m":"You are the very soul of sacred sound, the treasury of the pure Rig and Yajur Vedas and of the Sama Veda with its lovely chanted verses. Blessed Goddess, you are the three Vedas, for the well-being of the world; you are the livelihood of all the worlds and the destroyer of their deepest pain.","h":"आप शब्दस्वरूपा हैं, अत्यन्त निर्मल ऋग्वेद और यजुर्वेद की तथा उद्गीथ के सुन्दर पदों वाले सामवेद की निधि हैं। हे भगवती देवी, संसार के कल्याण के लिए आप ही त्रयी (तीनों वेद) हैं, आप ही सारे जगत की आजीविका और उनकी बड़ी से बड़ी पीड़ा का नाश करने वाली हैं।","n":"४.१०"},{"d":"मेधासि देवि विदिताखिलशास्त्रसारा दुर्गासि दुर्गभवसागरनौरसङ्गा।\nश्रीः कैटभारिहृदयैककृताधिवासा गौरी त्वमेव शशिमौलिकृतप्रतिष्ठा॥","r":"Medhasi devi viditakhilashastrasara Durgasi durgabhavasagaranaurasanga,\nShrih Kaitabharihridayaikakritadhivasa Gauri tvameva shashimaulikritapratishtha.","m":"Goddess, you are the intelligence that knows the essence of all the scriptures. You are Durga, the boat that carries us, free of attachment, across the ocean of worldly life that is so hard to cross. You are Lakshmi, who lives in the heart of Vishnu alone, and you are Gauri, enthroned with Shiv who wears the moon.","h":"हे देवी, सब शास्त्रों का सार जानने वाली मेधा आप ही हैं। दुस्तर संसार-सागर से पार उतारने वाली आसक्तिरहित नौका, दुर्गा आप ही हैं। केवल विष्णु के हृदय में निवास करने वाली लक्ष्मी और चन्द्रशेखर शिव के साथ प्रतिष्ठित गौरी भी आप ही हैं।","n":"४.११"},{"d":"ईषत्सहासममलं परिपूर्णचन्द्रबिम्बानुकारि कनकोत्तमकान्तिकान्तम्।\nअत्यद्भुतं प्रहृतमात्तरुषा तथापि वक्त्रं विलोक्य सहसा महिषासुरेण॥","r":"Ishatsahasamamalam paripurnachandrabimbanukari kanakottamakantikantam,\nAtyadbhutam prahritamattarusha tathapi vaktram vilokya sahasa Mahishasurena.","m":"How very strange: having seen your face, gently smiling, spotless, like the full moon and lovely with the glow of the finest gold, Mahishasur still struck at you in sudden rage.","h":"यह बड़े आश्चर्य की बात है कि मन्द मुस्कान वाले, निर्मल, पूर्ण चन्द्रमा के समान और उत्तम सोने की कान्ति से सुन्दर आपके मुख को देखकर भी महिषासुर ने क्रोध में भरकर सहसा उस पर प्रहार किया।","n":"४.१२"},{"d":"दृष्ट्वा तु देवि कुपितं भ्रुकुटीकरालमुद्यच्छशाङ्कसदृशच्छवि यन्न सद्यः।\nप्राणान्मुमोच महिषस्तदतीव चित्रं कैर्जीव्यते हि कुपितान्तकदर्शनेन॥","r":"Drishtva tu devi kupitam bhrukutikaralam udyachchhashankasadrishachchhavi yanna sadyah,\nPranan mumocha Mahishastadativa chitram kairjivyate hi kupitantakadarshanena.","m":"And Goddess, it is stranger still that Mahishasur did not give up his life the moment he saw your face in anger, fearsome with its frown and red as the rising moon. For who can live after seeing Death himself enraged?","h":"और हे देवी, इससे भी बढ़कर आश्चर्य यह है कि क्रोध से भरे, भौंहों से विकराल और उदय होते चन्द्रमा जैसी लाल कान्ति वाले आपके मुख को देखकर भी महिषासुर ने तुरन्त प्राण नहीं छोड़े। भला क्रोधित यमराज को देखकर कौन जीवित रह सकता है?","n":"४.१३"},{"d":"देवि प्रसीद परमा भवती भवाय सद्यो विनाशयसि कोपवती कुलानि।\nविज्ञातमेतदधुनैव यदस्तमेतन्नीतं बलं सुविपुलं महिषासुरस्य॥","r":"Devi prasida parama bhavati bhavaya sadyo vinashayasi kopavati kulani,\nVijnatametadadhunaiva yadastametan nitam balam suvipulam Mahishasurasya.","m":"Goddess, be gracious. When you are pleased you are supreme for the world’s good; when angry you destroy whole clans in an instant. We have just seen it, now that the vast army of Mahishasur has been brought to its end.","h":"हे देवी, प्रसन्न होइए। प्रसन्न होने पर आप जगत का परम कल्याण करती हैं और क्रोधित होने पर तुरन्त ही कुलों का नाश कर देती हैं। यह बात अभी जानी गई, जब महिषासुर की यह विशाल सेना नष्ट कर दी गई।","n":"४.१४"},{"d":"ते सम्मता जनपदेषु धनानि तेषां तेषां यशांसि न च सीदति धर्मवर्गः।\nधन्यास्त एव निभृतात्मजभृत्यदारा येषां सदाभ्युदयदा भवती प्रसन्ना॥","r":"Te sammata janapadeshu dhanani tesham tesham yashansi na cha sidati dharmavargah,\nDhanyasta eva nibhritatmajabhrityadara yesham sadabhyudayada bhavati prasanna.","m":"Those on whom you, giver of prosperity, are always pleased are honoured in the land; wealth and fame are theirs and their righteous deeds never fail. Blessed are they, with children, servants and wives well cared for.","h":"आप सदा उन्नति देने वाली हैं; जिन पर आप प्रसन्न रहती हैं, वे देश में सम्मानित होते हैं, उन्हें धन और यश मिलता है, और उनके धर्म-कर्म कभी शिथिल नहीं होते। वे ही धन्य हैं, और उनके पुत्र, सेवक और पत्नी सुखी रहते हैं।","n":"४.१५"},{"d":"धर्म्याणि देवि सकलानि सदैव कर्माण्यत्यादृतः प्रतिदिनं सुकृती करोति।\nस्वर्गं प्रयाति च ततो भवतीप्रसादाल्लोकत्रयेऽपि फलदा ननु देवि तेन॥","r":"Dharmyani devi sakalani sadaiva karmanyatyadritah pratidinam sukriti karoti,\nSvargam prayati cha tato bhavatiprasadal lokatraye’pi phalada nanu devi tena.","m":"Goddess, by your grace a virtuous person performs every righteous deed with great care, day after day, and so reaches heaven. Surely, then, Goddess, you are the giver of rewards in all three worlds.","h":"हे देवी, आपकी कृपा से ही पुण्यात्मा मनुष्य प्रतिदिन अत्यन्त श्रद्धा से सब धर्मयुक्त कर्म करता है और उससे स्वर्ग को जाता है। इसलिए हे देवी, आप ही तीनों लोकों में फल देने वाली हैं।","n":"४.१६"},{"d":"दुर्गे स्मृता हरसि भीतिमशेषजन्तोः स्वस्थैः स्मृता मतिमतीव शुभां ददासि।\nदारिद्र्यदुःखभयहारिणि का त्वदन्या सर्वोपकारकरणाय सदार्द्रचित्ता॥","r":"Durge smrita harasi bhitimasheshajantoh svasthaih smrita matimativa shubham dadasi,\nDaridryaduhkhabhayaharini ka tvadanya sarvopakarakaranaya sadardrachitta.","m":"Durga, when remembered you take away the fear of every creature, and when remembered by those at peace you give them the most auspicious understanding. Remover of poverty, sorrow and fear, who but you has a heart always tender to do good to all?","h":"हे दुर्गा, स्मरण करने पर आप सब प्राणियों का भय हर लेती हैं, और स्वस्थ (सुखी) पुरुषों द्वारा स्मरण करने पर उन्हें परम कल्याणकारी बुद्धि देती हैं। हे दरिद्रता, दुःख और भय को हरने वाली, आपके सिवा और कौन है जिसका चित्त सबका उपकार करने के लिए सदा दया से भीगा रहता है?","n":"४.१७"},{"d":"एभिर्हतैर्जगदुपैति सुखं तथैते कुर्वन्तु नाम नरकाय चिराय पापम्।\nसंग्राममृत्युमधिगम्य दिवं प्रयान्तु मत्वेति नूनमहितान्विनिहंसि देवि॥","r":"Ebhirhatairjagadupaiti sukham tathaite kurvantu nama narakaya chiraya papam,\nSangramamrityumadhigamya divam prayantu matveti nunamahitanvinihansi devi.","m":"“With these slain the world will be happy; and though they have sinned enough for long ages in hell, let them die in battle and go to heaven.” Surely it is with this thought, Goddess, that you slay the enemies.","h":"“इनके मरने से संसार को सुख मिलेगा, और भले ही इन्होंने बहुत समय तक नरक में रहने योग्य पाप किए हों, ये युद्ध में मृत्यु पाकर स्वर्ग जाएँ,” निश्चय ही यही सोचकर हे देवी, आप शत्रुओं का वध करती हैं।","n":"४.१८"},{"d":"दृष्ट्वैव किं न भवती प्रकरोति भस्म सर्वासुरानरिषु यत्प्रहिणोषि शस्त्रम्।\nलोकान्प्रयान्तु रिपवोऽपि हि शस्त्रपूता इत्थं मतिर्भवति तेष्वपि तेऽतिसाध्वी॥","r":"Drishtvaiva kim na bhavati prakaroti bhasma sarvasuranarishu yatprahinoshi shastram,\nLokan prayantu ripavo’pi hi shastraputa ittham matirbhavati teshvapi te’tisadhvi.","m":"Could you not burn all the demons to ash with a mere glance? Yet you hurl your weapons at the enemy so that, purified by your weapons, even foes may reach the higher worlds. Such is your kindness even towards them.","h":"क्या आप केवल देखकर ही सब असुरों को भस्म नहीं कर सकतीं? फिर भी आप शत्रुओं पर शस्त्र चलाती हैं, ताकि आपके शस्त्रों से पवित्र होकर शत्रु भी उत्तम लोकों को जाएँ। उनके प्रति भी आपका विचार इतना उत्तम है।","n":"४.१९"},{"d":"खड्गप्रभानिकरविस्फुरणैस्तथोग्रैः शूलाग्रकान्तिनिवहेन दृशोऽसुराणाम्।\nयन्नागता विलयमंशुमदिन्दुखण्डयोग्याननं तव विलोकयतां तदेतत्॥","r":"Khadgaprabhanikaravisphuranaistathograih shulagrakantinivahena drisho’suranam,\nYannagata vilayamanshumadindukhandayogyananam tava vilokayatam tadetat.","m":"The fierce flashes of your sword and the blaze from the tip of your trident did not blind the demons’ eyes, because they were gazing at your face, lovely as the shining crescent moon.","h":"आपके खड्ग की चमक की तीव्र लपटों और त्रिशूल की नोक की कान्ति से असुरों की आँखें नष्ट नहीं हुईं, क्योंकि वे चमकते हुए अर्धचन्द्र जैसे सुन्दर आपके मुख को देख रहे थे।","n":"४.२०"},{"d":"दुर्वृत्तवृत्तशमनं तव देवि शीलं रूपं तथैतदविचिन्त्यमतुल्यमन्यैः।\nवीर्यं च हन्तृ हृतदेवपराक्रमाणां वैरिष्वपि प्रकटितैव दया त्वयेत्थम्॥","r":"Durvrittavrittashamanam tava devi shilam rupam tathaitadavichintyamatulyamanyaih,\nViryam cha hantri hritadevaparakramanam vairishvapi prakataitaiva daya tvayettham.","m":"Goddess, your nature is to put an end to the deeds of the wicked; this form of yours is beyond thought and beyond compare; your might destroys those who robbed the gods of their valour. Even towards enemies you have shown such mercy.","h":"हे देवी, दुराचारियों के आचरण को शान्त करना आपका स्वभाव है; आपका यह रूप अचिन्त्य है और दूसरों से अतुलनीय है; आपका पराक्रम देवताओं का बल हरने वालों का नाश करने वाला है। इस प्रकार आपने शत्रुओं पर भी दया ही प्रकट की है।","n":"४.२१"},{"d":"केनोपमा भवतु तेऽस्य पराक्रमस्य रूपं च शत्रुभयकार्यतिहारि कुत्र।\nचित्ते कृपा समरनिष्ठुरता च दृष्टा त्वय्येव देवि वरदे भुवनत्रयेऽपि॥","r":"Kenopama bhavatu te’sya parakramasya rupam cha shatrubhayakaryatihari kutra,\nChitte kripa samaranishthurata cha drishta tvayyeva devi varade bhuvanatraye’pi.","m":"To what can this valour of yours be compared? Where else is there a form so captivating that yet strikes terror into enemies? Compassion in the heart and ruthlessness in battle: Goddess, giver of boons, in all three worlds these are seen together only in you.","h":"आपके इस पराक्रम की उपमा किससे दी जाए? शत्रुओं को भय देने वाला और फिर भी मन को हर लेने वाला ऐसा रूप और कहाँ है? हे वरदायिनी देवी, हृदय में कृपा और युद्ध में कठोरता, ये दोनों तीनों लोकों में केवल आपमें ही देखे गए हैं।","n":"४.२२"},{"d":"त्रैलोक्यमेतदखिलं रिपुनाशनेन त्रातं त्वया समरमूर्धनि तेऽपि हत्वा।\nनीता दिवं रिपुगणा भयमप्यपास्तमस्माकमुन्मदसुरारिभवं नमस्ते॥","r":"Trailokyametadakhilam ripunashanena tratam tvaya samaramurdhani te’pi hatva,\nNita divam ripugana bhayamapyapastam asmakamunmadasuraribhavam namaste.","m":"By destroying the enemy you have saved all three worlds; slaying them at the front of battle you have sent even those hosts of enemies to heaven, and you have taken away our fear of the frenzied demons. We bow to you.","h":"शत्रुओं का नाश करके आपने इन तीनों लोकों की रक्षा की है; युद्धभूमि में उन शत्रुओं को भी मारकर स्वर्ग पहुँचाया है, और उन्मत्त असुरों से होने वाले हमारे भय को भी दूर कर दिया है। आपको नमस्कार है।","n":"४.२३"},{"d":"शूलेन पाहि नो देवि पाहि खड्गेन चाम्बिके।\nघण्टास्वनेन नः पाहि चापज्यानिःस्वनेन च॥","r":"Shulena pahi no devi pahi khadgena chambike,\nGhantasvanena nah pahi chapajyanihsvanena cha.","m":"Goddess, protect us with your trident. Ambika, protect us with your sword, with the sound of your bell and with the twang of your bowstring.","h":"हे देवी, त्रिशूल से हमारी रक्षा कीजिए। हे अम्बिका, खड्ग से, घण्टे की ध्वनि से और धनुष की डोरी की टंकार से हमारी रक्षा कीजिए।","n":"४.२४"},{"d":"प्राच्यां रक्ष प्रतीच्यां च चण्डिके रक्ष दक्षिणे।\nभ्रामणेनात्मशूलस्य उत्तरस्यां तथेश्वरि॥","r":"Prachyam raksha pratichyam cha Chandike raksha dakshine,\nBhramanenatmashulasya uttarasyam tatheshvari.","m":"Chandika, protect us in the east and the west; protect us in the south, and in the north too, Goddess, by whirling your trident.","h":"हे चण्डिका, पूर्व और पश्चिम में हमारी रक्षा कीजिए, दक्षिण में रक्षा कीजिए; और हे ईश्वरी, अपने त्रिशूल को घुमाकर उत्तर में भी हमारी रक्षा कीजिए।","n":"४.२५"},{"d":"सौम्यानि यानि रूपाणि त्रैलोक्ये विचरन्ति ते।\nयानि चात्यर्थघोराणि तै रक्षास्मांस्तथा भुवम्॥","r":"Saumyani yani rupani trailokye vicharanti te,\nYani chatyarthaghorani tai rakshasmanstatha bhuvam.","m":"With your gentle forms that move through the three worlds, and with your exceedingly terrible ones, protect us and the earth.","h":"तीनों लोकों में विचरने वाले आपके जो सौम्य रूप हैं और जो अत्यन्त भयंकर रूप हैं, उन सबके द्वारा हमारी और पृथ्वी की रक्षा कीजिए।","n":"४.२६"},{"d":"खड्गशूलगदादीनि यानि चास्त्राणि तेऽम्बिके।\nकरपल्लवसङ्गीनि तैरस्मान् रक्ष सर्वतः॥","r":"Khadgashulagadadini yani chastrani te’mbike,\nKarapallavasangini tairasman raksha sarvatah.","m":"Ambika, with the sword, trident, mace and all the weapons held in your tender hands, protect us on every side.","h":"हे अम्बिका, आपके कोमल करों में शोभा पाने वाले खड्ग, त्रिशूल, गदा आदि जो अस्त्र हैं, उन सबसे सब ओर से हमारी रक्षा कीजिए।","n":"४.२७"},{"d":"एवं स्तुता सुरैर्दिव्यैः कुसुमैर्नन्दनोद्भवैः।\nअर्चिता जगतां धात्री तथा गन्धानुलेपनैः॥","r":"Evam stuta surairdivyaih kusumairnandanodbhavaih,\nArchita jagatam dhatri tatha gandhanulepanaih.","m":"Praised in this way by the gods, the sustainer of the worlds was worshipped with heavenly flowers from the Nandan garden and with fragrant pastes,","h":"इस प्रकार देवताओं द्वारा स्तुति की गई जगत की धात्री देवी की नन्दनवन के दिव्य पुष्पों और सुगन्धित चन्दन आदि से पूजा की गई,","n":"४.२९","sp":{"d":"ऋषिरुवाच","r":"The sage said","no":28}},{"d":"भक्त्या समस्तैस्त्रिदशैर्दिव्यैर्धूपैस्तु धूपिता।\nप्राह प्रसादसुमुखी समस्तान्प्रणतान्सुरान्॥","r":"Bhaktya samastaistridashairdivyairdhupaistu dhupita,\nPraha prasadasumukhi samastan pranatan suran.","m":"and all the gods devotedly offered her heavenly incense. Her face bright with grace, she spoke to all the gods bowing before her.","h":"और सब देवताओं ने भक्तिपूर्वक दिव्य धूप से उनकी आराधना की। तब प्रसन्न मुख वाली देवी ने प्रणाम करते हुए सब देवताओं से कहा।","n":"४.३०"},{"d":"व्रियतां त्रिदशाः सर्वे यदस्मत्तोऽभिवाञ्छितम्॥","r":"Vriyatam tridashah sarve yadasmatto’bhivanchhitam.","m":"Gods, all of you, ask me for whatever you desire.","h":"हे देवताओ, तुम सब मुझसे जो कुछ चाहते हो, वह माँगो।","n":"४.३२","sp":{"d":"देव्युवाच","r":"The Goddess said","no":31}},{"d":"भगवत्या कृतं सर्वं न किञ्चिदवशिष्यते।\nयदयं निहतः शत्रुरस्माकं महिषासुरः॥","r":"Bhagavatya kritam sarvam na kinchidavashishyate,\nYadayam nihatah shatrurasmakam Mahishasurah.","m":"Blessed Goddess, you have done everything; nothing remains, now that our enemy Mahishasur has been slain.","h":"हे भगवती, आपने सब कुछ कर दिया; अब कुछ भी शेष नहीं है, क्योंकि हमारा यह शत्रु महिषासुर मारा गया।","n":"४.३४","sp":{"d":"देवा ऊचुः","r":"The gods said","no":33}},{"d":"यदि चापि वरो देयस्त्वयास्माकं महेश्वरि।\nसंस्मृता संस्मृता त्वं नो हिंसेथाः परमापदः॥","r":"Yadi chapi varo deyastvayasmakam Maheshvari,\nSansmrita sansmrita tvam no hinsethah paramapadah.","m":"Yet if you would give us a boon, great Goddess: whenever we remember you, destroy our gravest troubles.","h":"हे महेश्वरी, फिर भी यदि आप हमें वर देना चाहती हैं, तो जब-जब हम आपका स्मरण करें, तब-तब आप हमारी बड़ी से बड़ी विपत्तियों का नाश करें।","n":"४.३५"},{"d":"यश्च मर्त्यः स्तवैरेभिस्त्वां स्तोष्यत्यमलानने।\nतस्य वित्तर्द्धिविभवैर्धनदारादिसम्पदाम्॥","r":"Yashcha martyah stavairebhistvam stoshyatyamalanane,\nTasya vittarddhivibhavairdhanadaradisampadam.","m":"And, Goddess of the spotless face, for any mortal who praises you with these hymns, for the growth of their wealth, prosperity and splendour, their riches, family and fortune,","h":"और हे निर्मल मुख वाली, जो मनुष्य इन स्तोत्रों से आपकी स्तुति करे, उसके वित्त, समृद्धि, वैभव, धन, स्त्री-परिवार आदि सम्पत्ति की वृद्धि के लिए,","n":"४.३६"},{"d":"वृद्धयेऽस्मत्प्रसन्ना त्वं भवेथाः सर्वदाम्बिके॥","r":"Vriddhaye’smatprasanna tvam bhavethah sarvadambike.","m":"Ambika, may you, being pleased with us, always be gracious.","h":"हे अम्बिका, आप हम पर प्रसन्न होकर सदा कृपा करती रहें।","n":"४.३७"},{"d":"इति प्रसादिता देवैर्जगतोऽर्थे तथाऽऽत्मनः।\nतथेत्युक्त्वा भद्रकाली बभूवान्तर्हिता नृप॥","r":"Iti prasadita devairjagato’rthe tatha’tmanah,\nTathetyuktva Bhadrakali babhuvantarhita nripa.","m":"Pleased in this way by the gods for the world’s sake and their own, Bhadrakali said “So be it”, O king, and vanished.","h":"हे राजन्, इस प्रकार देवताओं ने जगत के और अपने हित के लिए देवी को प्रसन्न किया, तब भद्रकाली “तथास्तु” कहकर अन्तर्धान हो गईं।","n":"४.३९","sp":{"d":"ऋषिरुवाच","r":"The sage said","no":38}},{"d":"इत्येतत्कथितं भूप सम्भूता सा यथा पुरा।\nदेवी देवशरीरेभ्यो जगत्त्रयहितैषिणी॥","r":"Ityetatkathitam bhupa sambhuta sa yatha pura,\nDevi devasharirebhyo jagattrayahitaishini.","m":"So, O king, I have told you how in ancient times the Goddess, who wishes the good of the three worlds, arose from the bodies of the gods.","h":"हे राजन्, इस प्रकार मैंने तुम्हें बताया कि तीनों लोकों का हित चाहने वाली वे देवी प्राचीन काल में देवताओं के शरीरों से कैसे प्रकट हुई थीं।","n":"४.४०"},{"d":"पुनश्च गौरीदेहात्सा समुद्भूता यथाभवत्।\nवधाय दुष्टदैत्यानां तथा शुम्भनिशुम्भयोः॥","r":"Punashcha Gauridehatsa samudbhuta yathabhavat,\nVadhaya dushtadaityanam tatha Shumbhanishumbhayoh.","m":"And now hear how she came forth again, from the body of Gauri, to slay the wicked demons and Shumbh and Nishumbh,","h":"और फिर वे दुष्ट दैत्यों तथा शुम्भ-निशुम्भ का वध करने के लिए गौरी के शरीर से कैसे प्रकट हुईं,","n":"४.४१"},{"d":"रक्षणाय च लोकानां देवानामुपकारिणी।\nतच्छृणुष्व मया ख्यातं यथावत्कथयामि ते॥","r":"Rakshanaya cha lokanam devanamupakarini,\nTachchhrinushva maya khyatam yathavatkathayami te.","m":"and to protect the worlds, she who is the helper of the gods. Listen as I tell you exactly how it happened.","h":"और लोकों की रक्षा के लिए देवताओं का उपकार करने वाली वे कैसे प्रकट हुईं, वह मैं तुम्हें ठीक-ठीक सुनाता हूँ, सुनो।","n":"४.४२"}],"intro":"Mahishasur is dead. Indra and the gods, their bodies thrilling with joy, praise the Goddess in the Shakradi Stuti, verses 3 to 27, and she promises to return whenever they remember her. Then the sage begins the next story."},{"n":5,"d":"देवीदूतसंवाद","r":"Devi Doot Samvad","en":"The gods’ hymn, and the demons’ messenger","count":129,"sum":"Shumbh and Nishumbh have seized the three worlds. The gods go to the Himalaya and praise the Goddess as the one who dwells in every being, in the hymn that begins या देवी सर्वभूतेषु. Parvati comes to bathe in the Ganga, and from her body comes forth Ambika. Chand and Mund see her beauty and tell Shumbh, who sends the messenger Sugriva to ask for her hand. She answers that long ago she vowed to marry only the one who defeats her in battle.","part":{"from":8,"to":82},"verses":[{"d":"नमो देव्यै महादेव्यै शिवायै सततं नमः।\nनमः प्रकृत्यै भद्रायै नियताः प्रणताः स्म ताम्॥","r":"Namo devyai mahadevyai shivayai satatam namah,\nNamah prakrityai bhadrayai niyatah pranatah sma tam.","m":"Salutations to the Goddess, to the great Goddess; to the gracious one, salutations always. Salutations to Nature, to the auspicious one; with minds restrained we bow to her.","h":"देवी को नमस्कार है, महादेवी को नमस्कार है, कल्याणकारिणी शिवा को सदा नमस्कार है। प्रकृति और भद्रा को नमस्कार है। हम संयमपूर्वक उन्हें प्रणाम करते हैं।","n":"५.९","sp":{"d":"देवा ऊचुः","r":"The gods said","no":8}},{"d":"रौद्रायै नमो नित्यायै गौर्यै धात्र्यै नमो नमः।\nज्योत्स्नायै चेन्दुरूपिण्यै सुखायै सततं नमः॥","r":"Raudrayai namo nityayai Gauryai dhatryai namo namah,\nJyotsnayai chendurupinyai sukhayai satatam namah.","m":"Salutations to the fierce one, to the eternal one; to Gauri, to the sustainer, salutations again and again. To the moonlight, to her whose form is the moon, to happiness itself, salutations always.","h":"रौद्रा को नमस्कार है, नित्या को, गौरी को और जगत को धारण करने वाली धात्री को बार-बार नमस्कार है। चाँदनी रूपा, चन्द्ररूपिणी और सुखस्वरूपा देवी को सदा नमस्कार है।","n":"५.१०"},{"d":"कल्याण्यै प्रणतां वृद्ध्यै सिद्ध्यै कुर्मो नमो नमः।\nनैर्ऋत्यै भूभृतां लक्ष्म्यै शर्वाण्यै ते नमो नमः॥","r":"Kalyanyai pranatam vriddhyai siddhyai kurmo namo namah,\nNairrityai bhubhritam lakshmyai Sharvanyai te namo namah.","m":"We bow again and again to her who brings good to those who bow to her, who is growth and success. To you who are misfortune, who are the fortune of kings, who are Sharvani, salutations again and again.","h":"शरणागतों का कल्याण करने वाली, वृद्धि और सिद्धि रूपा देवी को हम बार-बार नमस्कार करते हैं। नैर्ऋती (अलक्ष्मी), राजाओं की लक्ष्मी और शर्वाणी (शिव की पत्नी) रूपा आपको बार-बार नमस्कार है।","n":"५.११"},{"d":"दुर्गायै दुर्गपारायै सारायै सर्वकारिण्यै।\nख्यात्यै तथैव कृष्णायै धूम्रायै सततं नमः॥","r":"Durgayai durgaparayai sarayai sarvakarinyai,\nKhyatyai tathaiva Krishnayai dhumrayai satatam namah.","m":"To Durga, who carries us across difficulties, to the essence, to the doer of all; to fame, to the dark one and the smoke-coloured one, salutations always.","h":"दुर्गा, कठिनाइयों से पार उतारने वाली, सारस्वरूपा, सब कुछ करने वाली, ख्याति, कृष्णा और धूम्रवर्णा देवी को सदा नमस्कार है।","n":"५.१२"},{"d":"अतिसौम्यातिरौद्रायै नतास्तस्यै नमो नमः।\nनमो जगत्प्रतिष्ठायै देव्यै कृत्यै नमो नमः॥","r":"Atisaumyatiraudrayai natastasyai namo namah,\nNamo jagatpratishthayai devyai krityai namo namah.","m":"We bow to her who is most gentle and most fierce; salutations to her again and again. Salutations to the foundation of the world, to the Goddess who is action itself, again and again.","h":"जो अत्यन्त सौम्य और अत्यन्त रौद्र हैं, उन्हें हम प्रणाम करते हैं, उन्हें बार-बार नमस्कार है। जगत की आधार और क्रिया रूपा देवी को बार-बार नमस्कार है।","n":"५.१३"},{"d":"या देवी सर्वभूतेषु विष्णुमायेति शब्दिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Ya Devi sarvabhuteshu Vishnumayeti shabdita,\nNamastasyai namastasyai namastasyai namo namah.","m":"To the Goddess who in all beings is called Vishnu’s Maya: salutations to her, salutations to her, salutations to her, again and again.","h":"जो देवी सब प्राणियों में विष्णुमाया नाम से कही जाती हैं, उनको नमस्कार है, उनको नमस्कार है, उनको बार-बार नमस्कार है।","n":"५.१४–१६"},{"d":"या देवी सर्वभूतेषु चेतनेत्यभिधीयते।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Ya Devi sarvabhuteshu chetanetyabhidhiyate,\nNamastasyai namastasyai namastasyai namo namah.","m":"To the Goddess who in all beings is called consciousness: salutations to her, salutations to her, salutations to her, again and again.","h":"जो देवी सब प्राणियों में चेतना कहलाती हैं, उनको नमस्कार है, उनको नमस्कार है, उनको बार-बार नमस्कार है।","n":"५.१७–१९"},{"d":"या देवी सर्वभूतेषु बुद्धिरूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Ya Devi sarvabhuteshu buddhirupena sansthita,\nNamastasyai namastasyai namastasyai namo namah.","m":"To the Goddess who dwells in all beings as intelligence: salutations to her, salutations to her, salutations to her, again and again.","h":"जो देवी सब प्राणियों में बुद्धि के रूप में स्थित हैं, उनको नमस्कार है, उनको नमस्कार है, उनको बार-बार नमस्कार है।","n":"५.२०–२२"},{"d":"या देवी सर्वभूतेषु निद्रारूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Ya Devi sarvabhuteshu nidrarupena sansthita,\nNamastasyai namastasyai namastasyai namo namah.","m":"To the Goddess who dwells in all beings as sleep: salutations to her, salutations to her, salutations to her, again and again.","h":"जो देवी सब प्राणियों में निद्रा के रूप में स्थित हैं, उनको नमस्कार है, उनको नमस्कार है, उनको बार-बार नमस्कार है।","n":"५.२३–२५"},{"d":"या देवी सर्वभूतेषु क्षुधारूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Ya Devi sarvabhuteshu kshudharupena sansthita,\nNamastasyai namastasyai namastasyai namo namah.","m":"To the Goddess who dwells in all beings as hunger: salutations to her, salutations to her, salutations to her, again and again.","h":"जो देवी सब प्राणियों में क्षुधा (भूख) के रूप में स्थित हैं, उनको नमस्कार है, उनको नमस्कार है, उनको बार-बार नमस्कार है।","n":"५.२६–२८"},{"d":"या देवी सर्वभूतेषु छायारूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Ya Devi sarvabhuteshu chhayarupena sansthita,\nNamastasyai namastasyai namastasyai namo namah.","m":"To the Goddess who dwells in all beings as shadow: salutations to her, salutations to her, salutations to her, again and again.","h":"जो देवी सब प्राणियों में छाया के रूप में स्थित हैं, उनको नमस्कार है, उनको नमस्कार है, उनको बार-बार नमस्कार है।","n":"५.२९–३१"},{"d":"या देवी सर्वभूतेषु शक्तिरूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Ya Devi sarvabhuteshu shaktirupena sansthita,\nNamastasyai namastasyai namastasyai namo namah.","m":"To the Goddess who dwells in all beings as power: salutations to her, salutations to her, salutations to her, again and again.","h":"जो देवी सब प्राणियों में शक्ति के रूप में स्थित हैं, उनको नमस्कार है, उनको नमस्कार है, उनको बार-बार नमस्कार है।","n":"५.३२–३४"},{"d":"या देवी सर्वभूतेषु तृष्णारूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Ya Devi sarvabhuteshu trishnarupena sansthita,\nNamastasyai namastasyai namastasyai namo namah.","m":"To the Goddess who dwells in all beings as thirst: salutations to her, salutations to her, salutations to her, again and again.","h":"जो देवी सब प्राणियों में तृष्णा के रूप में स्थित हैं, उनको नमस्कार है, उनको नमस्कार है, उनको बार-बार नमस्कार है।","n":"५.३५–३७"},{"d":"या देवी सर्वभूतेषु क्षान्तिरूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Ya Devi sarvabhuteshu kshantirupena sansthita,\nNamastasyai namastasyai namastasyai namo namah.","m":"To the Goddess who dwells in all beings as forbearance: salutations to her, salutations to her, salutations to her, again and again.","h":"जो देवी सब प्राणियों में क्षमा के रूप में स्थित हैं, उनको नमस्कार है, उनको नमस्कार है, उनको बार-बार नमस्कार है।","n":"५.३८–४०"},{"d":"या देवी सर्वभूतेषु जातिरूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Ya Devi sarvabhuteshu jatirupena sansthita,\nNamastasyai namastasyai namastasyai namo namah.","m":"To the Goddess who dwells in all beings as birth and kind: salutations to her, salutations to her, salutations to her, again and again.","h":"जो देवी सब प्राणियों में जाति (जन्म) के रूप में स्थित हैं, उनको नमस्कार है, उनको नमस्कार है, उनको बार-बार नमस्कार है।","n":"५.४१–४३"},{"d":"या देवी सर्वभूतेषु लज्जारूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Ya Devi sarvabhuteshu lajjarupena sansthita,\nNamastasyai namastasyai namastasyai namo namah.","m":"To the Goddess who dwells in all beings as modesty: salutations to her, salutations to her, salutations to her, again and again.","h":"जो देवी सब प्राणियों में लज्जा के रूप में स्थित हैं, उनको नमस्कार है, उनको नमस्कार है, उनको बार-बार नमस्कार है।","n":"५.४४–४६"},{"d":"या देवी सर्वभूतेषु शान्तिरूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Ya Devi sarvabhuteshu shantirupena sansthita,\nNamastasyai namastasyai namastasyai namo namah.","m":"To the Goddess who dwells in all beings as peace: salutations to her, salutations to her, salutations to her, again and again.","h":"जो देवी सब प्राणियों में शान्ति के रूप में स्थित हैं, उनको नमस्कार है, उनको नमस्कार है, उनको बार-बार नमस्कार है।","n":"५.४७–४९"},{"d":"या देवी सर्वभूतेषु श्रद्धारूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Ya Devi sarvabhuteshu shraddharupena sansthita,\nNamastasyai namastasyai namastasyai namo namah.","m":"To the Goddess who dwells in all beings as faith: salutations to her, salutations to her, salutations to her, again and again.","h":"जो देवी सब प्राणियों में श्रद्धा के रूप में स्थित हैं, उनको नमस्कार है, उनको नमस्कार है, उनको बार-बार नमस्कार है।","n":"५.५०–५२"},{"d":"या देवी सर्वभूतेषु कान्तिरूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Ya Devi sarvabhuteshu kantirupena sansthita,\nNamastasyai namastasyai namastasyai namo namah.","m":"To the Goddess who dwells in all beings as beauty: salutations to her, salutations to her, salutations to her, again and again.","h":"जो देवी सब प्राणियों में कान्ति (सौन्दर्य) के रूप में स्थित हैं, उनको नमस्कार है, उनको नमस्कार है, उनको बार-बार नमस्कार है।","n":"५.५३–५५"},{"d":"या देवी सर्वभूतेषु लक्ष्मीरूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Ya Devi sarvabhuteshu Lakshmirupena sansthita,\nNamastasyai namastasyai namastasyai namo namah.","m":"To the Goddess who dwells in all beings as prosperity: salutations to her, salutations to her, salutations to her, again and again.","h":"जो देवी सब प्राणियों में लक्ष्मी के रूप में स्थित हैं, उनको नमस्कार है, उनको नमस्कार है, उनको बार-बार नमस्कार है।","n":"५.५६–५८"},{"d":"या देवी सर्वभूतेषु वृत्तिरूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Ya Devi sarvabhuteshu vrittirupena sansthita,\nNamastasyai namastasyai namastasyai namo namah.","m":"To the Goddess who dwells in all beings as livelihood and activity: salutations to her, salutations to her, salutations to her, again and again.","h":"जो देवी सब प्राणियों में वृत्ति (जीविका और क्रिया) के रूप में स्थित हैं, उनको नमस्कार है, उनको नमस्कार है, उनको बार-बार नमस्कार है।","n":"५.५९–६१"},{"d":"या देवी सर्वभूतेषु स्मृतिरूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Ya Devi sarvabhuteshu smritirupena sansthita,\nNamastasyai namastasyai namastasyai namo namah.","m":"To the Goddess who dwells in all beings as memory: salutations to her, salutations to her, salutations to her, again and again.","h":"जो देवी सब प्राणियों में स्मृति के रूप में स्थित हैं, उनको नमस्कार है, उनको नमस्कार है, उनको बार-बार नमस्कार है।","n":"५.६२–६४"},{"d":"या देवी सर्वभूतेषु दयारूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Ya Devi sarvabhuteshu dayarupena sansthita,\nNamastasyai namastasyai namastasyai namo namah.","m":"To the Goddess who dwells in all beings as compassion: salutations to her, salutations to her, salutations to her, again and again.","h":"जो देवी सब प्राणियों में दया के रूप में स्थित हैं, उनको नमस्कार है, उनको नमस्कार है, उनको बार-बार नमस्कार है।","n":"५.६५–६७"},{"d":"या देवी सर्वभूतेषु तुष्टिरूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Ya Devi sarvabhuteshu tushtirupena sansthita,\nNamastasyai namastasyai namastasyai namo namah.","m":"To the Goddess who dwells in all beings as contentment: salutations to her, salutations to her, salutations to her, again and again.","h":"जो देवी सब प्राणियों में तुष्टि (सन्तोष) के रूप में स्थित हैं, उनको नमस्कार है, उनको नमस्कार है, उनको बार-बार नमस्कार है।","n":"५.६८–७०"},{"d":"या देवी सर्वभूतेषु मातृरूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Ya Devi sarvabhuteshu matrirupena sansthita,\nNamastasyai namastasyai namastasyai namo namah.","m":"To the Goddess who dwells in all beings as mother: salutations to her, salutations to her, salutations to her, again and again.","h":"जो देवी सब प्राणियों में माता के रूप में स्थित हैं, उनको नमस्कार है, उनको नमस्कार है, उनको बार-बार नमस्कार है।","n":"५.७१–७३"},{"d":"या देवी सर्वभूतेषु भ्रान्तिरूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Ya Devi sarvabhuteshu bhrantirupena sansthita,\nNamastasyai namastasyai namastasyai namo namah.","m":"To the Goddess who dwells in all beings as error: salutations to her, salutations to her, salutations to her, again and again.","h":"जो देवी सब प्राणियों में भ्रान्ति के रूप में स्थित हैं, उनको नमस्कार है, उनको नमस्कार है, उनको बार-बार नमस्कार है।","n":"५.७४–७६"},{"d":"इन्द्रियाणामधिष्ठात्री भूतानां चाखिलेषु या।\nभूतेषु सततं तस्यै व्याप्तिदेव्यै नमो नमः॥","r":"Indriyanamadhishthatri bhutanam chakhileshu ya,\nBhuteshu satatam tasyai vyaptidevyai namo namah.","m":"She who rules over the senses of all beings and is ever present in every being: to that all-pervading Goddess, salutations again and again.","h":"जो सब प्राणियों की इन्द्रियों की अधिष्ठात्री हैं और सब प्राणियों में सदा व्याप्त रहती हैं, उन व्याप्ति देवी को बार-बार नमस्कार है।","n":"५.७७"},{"d":"चितिरूपेण या कृत्स्नमेतद्व्याप्य स्थिता जगत्।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","r":"Chitirupena ya kritsnametadvyapya sthita jagat,\nNamastasyai namastasyai namastasyai namo namah.","m":"To her who, as consciousness, pervades this entire world: salutations to her, salutations to her, salutations to her, again and again.","h":"जो चेतना के रूप में इस सम्पूर्ण जगत को व्याप्त करके स्थित हैं, उनको नमस्कार है, उनको नमस्कार है, उनको बार-बार नमस्कार है।","n":"५.७८–८०"},{"d":"स्तुता सुरैः पूर्वमभीष्टसंश्रयात्तथा सुरेन्द्रेण दिनेषु सेविता।\nकरोतु सा नः शुभहेतुरीश्वरी शुभानि भद्राण्यभिहन्तु चापदः॥","r":"Stuta suraih purvamabhishtasanshrayat tatha surendrena dineshu sevita,\nKarotu sa nah shubhaheturishvari shubhani bhadranyabhihantu chapadah.","m":"Praised long ago by the gods for the fulfilment of their wishes, and worshipped by Indra day after day: may that Goddess, the source of all good, bring us good and blessings and destroy our troubles.","h":"पहले अपनी कामना पूरी होने के लिए देवताओं ने जिनकी स्तुति की और इन्द्र ने बहुत दिनों तक जिनकी सेवा की, वे कल्याण की कारण ईश्वरी हमारा शुभ और मंगल करें तथा हमारी विपत्तियों का नाश करें।","n":"५.८१"},{"d":"या साम्प्रतं चोद्धतदैत्यतापितैरस्माभिरीशा च सुरैर्नमस्यते।\nया च स्मृता तत्क्षणमेव हन्ति नः सर्वापदो भक्तिविनम्रमूर्तिभिः॥","r":"Ya sampratam choddhatadaityatapitairasmabhirisha cha suraih namasyate,\nYa cha smrita tatkshanameva hanti nah sarvapado bhaktivinamramurtibhih.","m":"She whom we gods, tormented now by arrogant demons, bow to as our ruler; she who, when we remember her with bodies bowed in devotion, at that very moment destroys all our troubles.","h":"उद्दण्ड दैत्यों से सताए हुए हम देवता इस समय जिन ईश्वरी को नमस्कार करते हैं, और भक्ति से झुककर स्मरण करने पर जो उसी क्षण हमारी सब विपत्तियों का नाश कर देती हैं (वे हमारा कल्याण करें)।","n":"५.८२"}],"intro":"Shumbh and Nishumbh have taken the three worlds. Remembering the Goddess’s promise, the gods go to the Himalaya and praise her as Vishnumaya. Each “या देवी” verse is said with “नमस्तस्यै” three times, so the Gita Press edition gives it three numbers.","excerpt":"Verses 8 to 82, the gods’ hymn to the Goddess who dwells in every being (Aparajita Stuti). The rest of the chapter is still to be entered; its story is in the summary on the chapter list."},{"n":6,"d":"धूम्रलोचनवध","r":"Dhumralochan Vadh","en":"The slaying of Dhumralochan","count":24,"sum":"Shumbh, enraged by her answer, sends his general Dhumralochan with sixty thousand demons to drag the Goddess to him by her hair. With a single sound, “हुं”, she turns him to ash, and her lion destroys his army."},{"n":7,"d":"चण्डमुण्डवध","r":"Chand Mund Vadh","en":"The slaying of Chand and Mund","count":27,"sum":"Chand and Mund come with a great army. The Goddess’s face darkens with anger and from her brow springs Kali, gaunt and terrible, wearing a garland of skulls, who devours the army and beheads both demons. She brings their heads to the Goddess, who names her Chamunda."},{"n":8,"d":"रक्तबीजवध","r":"Raktabeej Vadh","en":"The slaying of Raktabeej","count":63,"sum":"The powers of the gods take form as the Matrikas (Brahmani, Maheshwari, Kaumari, Vaishnavi, Varahi, Narasimhi and Aindri) and join the battle, and the Goddess sends Shiv himself as her messenger, so she is called Shivaduti. Every drop of Raktabeej’s blood that falls becomes a new demon, until Kali drinks the blood before it can touch the ground and the Goddess slays him."},{"n":9,"d":"निशुम्भवध","r":"Nishumbh Vadh","en":"The slaying of Nishumbh","count":41,"sum":"Nishumbh charges the Goddess. She fells him; he rises with ten thousand arms; when she pierces his heart, another being emerges from it crying “Stop!”, and she laughs and cuts off its head. The Matrikas destroy the rest of his army."},{"n":10,"d":"शुम्भवध","r":"Shumbh Vadh","en":"The slaying of Shumbh","count":32,"sum":"Shumbh taunts the Goddess for relying on others’ strength. She answers that she is alone in the world, and all the Matrikas merge back into her. They fight with weapons, then hand to hand in the sky, until she hurls him to the earth and pierces his heart with her spear."},{"n":11,"d":"नारायणीस्तुति","r":"Narayani Stuti","en":"The gods’ hymn to Narayani","count":55,"sum":"After Shumbh is slain, the gods led by Agni praise the Goddess as Narayani, in verses that are recited on their own every day, among them सर्वमङ्गलमङ्गल्ये. She grants them a boon: whenever demons trouble the world she will come again, and she foretells the forms she will take, as Vindhyavasini, Raktadantika, Shatakshi, Shakambhari, Durga, Bhima and Bhramari.","verses":[{"d":"देव्या हते तत्र महासुरेन्द्रे सेन्द्राः सुरा वह्निपुरोगमास्ताम्।\nकात्यायनीं तुष्टुवुरिष्टलाभाद्विकाशिवक्त्राब्जविकाशिताशाः॥","r":"Devya hate tatra mahasurendre sendrah sura vahnipurogamastam,\nKatyayanim tushtuvurishtalabhad vikashivaktrabjavikashitashah.","m":"When the Goddess had slain the great lord of demons, the gods with Indra, led by Agni, praised Katyayani. Their wish fulfilled, their faces bloomed like lotuses and lit up every direction.","h":"जब देवी ने वहाँ महान असुरराज का वध कर दिया, तब इन्द्र सहित सब देवता, अग्नि को आगे करके, कात्यायनी की स्तुति करने लगे। मनोरथ पूरा होने से उनके कमल जैसे मुख खिल उठे और उनसे सब दिशाएँ प्रकाशित हो गईं।","n":"११.२","sp":{"d":"ऋषिरुवाच","r":"The sage said","no":1}},{"d":"देवि प्रपन्नार्तिहरे प्रसीद प्रसीद मातर्जगतोऽखिलस्य।\nप्रसीद विश्वेश्वरि पाहि विश्वं त्वमीश्वरी देवि चराचरस्य॥","r":"Devi prapannartihare prasida prasida matarjagato’khilasya,\nPrasida vishveshvari pahi vishvam tvamishvari devi characharasya.","m":"Goddess who takes away the pain of those who come to you, be gracious! Be gracious, Mother of the whole world! Be gracious, ruler of the universe, protect the universe: you, Goddess, are the ruler of all that moves and all that is still.","h":"हे शरण में आए हुए लोगों की पीड़ा दूर करने वाली देवी, प्रसन्न होइए। हे सम्पूर्ण जगत की माता, प्रसन्न होइए। हे विश्वेश्वरी, प्रसन्न होइए और विश्व की रक्षा कीजिए। हे देवी, आप ही चर और अचर सबकी स्वामिनी हैं।","n":"११.३"},{"d":"आधारभूता जगतस्त्वमेका महीस्वरूपेण यतः स्थितासि।\nअपां स्वरूपस्थितया त्वयैतदाप्यायते कृत्स्नमलङ्घ्यवीर्ये॥","r":"Adharabhuta jagatastvameka mahisvarupena yatah sthitasi,\nApam svarupasthitaya tvayaitad apyayate kritsnamalanghyavirye.","m":"You alone are the foundation of the world, for you exist in the form of the earth. Goddess of unsurpassable power, it is you, in the form of water, who nourish all of this.","h":"आप ही अकेली इस जगत का आधार हैं, क्योंकि आप पृथ्वी के रूप में स्थित हैं। हे अलंघ्य पराक्रम वाली देवी, जल के रूप में स्थित होकर आप ही इस सम्पूर्ण जगत को तृप्त करती हैं।","n":"११.४"},{"d":"त्वं वैष्णवी शक्तिरनन्तवीर्या विश्वस्य बीजं परमासि माया।\nसम्मोहितं देवि समस्तमेतत्त्वं वै प्रसन्ना भुवि मुक्तिहेतुः॥","r":"Tvam Vaishnavi shaktiranantavirya vishvasya bijam paramasi maya,\nSammohitam devi samastametat tvam vai prasanna bhuvi muktihetuh.","m":"You are the power of Vishnu, of endless strength; you are the seed of the universe, the supreme Maya. Goddess, you have enchanted all of this; and when you are pleased, you are the cause of liberation on earth.","h":"आप अनन्त बल वाली वैष्णवी शक्ति हैं, विश्व का बीज और परम माया हैं। हे देवी, आपने ही इस सारे जगत को मोहित कर रखा है, और प्रसन्न होने पर आप ही पृथ्वी पर मुक्ति का कारण बनती हैं।","n":"११.५"},{"d":"विद्याः समस्तास्तव देवि भेदाः स्त्रियः समस्ताः सकला जगत्सु।\nत्वयैकया पूरितमम्बयैतत्का ते स्तुतिः स्तव्यपरा परोक्तिः॥","r":"Vidyah samastastava devi bhedah striyah samastah sakala jagatsu,\nTvayaikaya puritamambayaitat ka te stutih stavyapara paroktih.","m":"Goddess, all forms of knowledge are aspects of you, and so are all women in every world. You alone, the Mother, fill this universe. What praise can there be for you, who are beyond all that can be praised and beyond all words?","h":"हे देवी, सारी विद्याएँ आपके ही भेद हैं, और जगत की सारी स्त्रियाँ भी आपके ही रूप हैं। एक आप माता ने ही इस जगत को व्याप्त कर रखा है। आपकी क्या स्तुति हो सकती है, जब आप स्तुति के योग्य वस्तुओं और वाणी से भी परे हैं?","n":"११.६"},{"d":"सर्वभूता यदा देवी स्वर्गमुक्तिप्रदायिनी।\nत्वं स्तुता स्तुतये का वा भवन्तु परमोक्तयः॥","r":"Sarvabhuta yada Devi svargamuktipradayini,\nTvam stuta stutaye ka va bhavantu paramoktayah.","m":"Since you, Goddess, are all beings and the giver of heaven and liberation, you are already praised; what finer words could there be to praise you?","h":"जब आप ही सर्वभूतस्वरूपा और स्वर्ग तथा मुक्ति देने वाली हैं, तब इसी से आपकी स्तुति हो गई; आपकी स्तुति के लिए इससे उत्तम वचन और क्या हो सकते हैं?","n":"११.७"},{"d":"सर्वस्य बुद्धिरूपेण जनस्य हृदि संस्थिते।\nस्वर्गापवर्गदे देवि नारायणि नमोऽस्तु ते॥","r":"Sarvasya buddhirupena janasya hridi sansthite,\nSvargapavargade devi Narayani namo’stu te.","m":"You who dwell in the heart of every person as understanding, giver of heaven and liberation: Goddess Narayani, I bow to you.","h":"जो बुद्धि के रूप में सब लोगों के हृदय में स्थित हैं, स्वर्ग और मोक्ष देने वाली हे देवी नारायणी, आपको नमस्कार है।","n":"११.८"},{"d":"कलाकाष्ठादिरूपेण परिणामप्रदायिनि।\nविश्वस्योपरतौ शक्ते नारायणि नमोऽस्तु ते॥","r":"Kalakashthadirupena parinamapradayini,\nVishvasyoparatau shakte Narayani namo’stu te.","m":"You who, as moments and the smallest units of time, bring all things to change, and who have the power to end the universe: Narayani, I bow to you.","h":"कला, काष्ठा आदि समय के रूपों से सब वस्तुओं में परिवर्तन लाने वाली और विश्व का संहार करने में समर्थ हे नारायणी, आपको नमस्कार है।","n":"११.९"},{"d":"सर्वमङ्गलमङ्गल्ये शिवे सर्वार्थसाधिके।\nशरण्ये त्र्यम्बके गौरि नारायणि नमोऽस्तु ते॥","r":"Sarvamangalamangalye Shive sarvarthasadhike,\nSharanye Tryambake Gauri Narayani namo’stu te.","m":"Most auspicious of all that is auspicious, gracious one who fulfils every aim, giver of refuge, three-eyed Gauri: Narayani, I bow to you.","h":"हे सब मंगलों में मंगलमयी, कल्याणकारिणी शिवा, सब पुरुषार्थ सिद्ध करने वाली, शरणदायिनी, तीन नेत्रों वाली गौरी, हे नारायणी, आपको नमस्कार है।","n":"११.१०"},{"d":"सृष्टिस्थितिविनाशानां शक्तिभूते सनातनि।\nगुणाश्रये गुणमये नारायणि नमोऽस्तु ते॥","r":"Srishtisthitivinashanam shaktibhute sanatani,\nGunashraye gunamaye Narayani namo’stu te.","m":"Eternal one, you are the power behind creation, preservation and destruction; the support of the three qualities of nature and made of them: Narayani, I bow to you.","h":"हे सनातनी, आप सृष्टि, पालन और संहार की शक्ति हैं; तीनों गुणों का आधार और गुणमयी हैं। हे नारायणी, आपको नमस्कार है।","n":"११.११"},{"d":"शरणागतदीनार्तपरित्राणपरायणे।\nसर्वस्यार्तिहरे देवि नारायणि नमोऽस्तु ते॥","r":"Sharanagatadinartaparitranaparayane,\nSarvasyartihare devi Narayani namo’stu te.","m":"You who are devoted to saving the poor and suffering who come to you for refuge, Goddess who takes away everyone’s pain: Narayani, I bow to you.","h":"शरण में आए दीनों और दुखियों की रक्षा में लगी रहने वाली, सबकी पीड़ा हरने वाली हे देवी नारायणी, आपको नमस्कार है।","n":"११.१२"},{"d":"हंसयुक्तविमानस्थे ब्रह्माणीरूपधारिणि।\nकौशाम्भःक्षरिके देवि नारायणि नमोऽस्तु ते॥","r":"Hansayuktavimanasthe Brahmanirupadharini,\nKaushambhahksharike devi Narayani namo’stu te.","m":"You who take the form of Brahmani, riding the chariot drawn by swans and sprinkling water with kusha grass: Goddess Narayani, I bow to you.","h":"हंसों से जुते विमान पर बैठने वाली, ब्रह्माणी का रूप धारण करने वाली और कुश से जल छिड़कने वाली हे देवी नारायणी, आपको नमस्कार है।","n":"११.१३"},{"d":"त्रिशूलचन्द्राहिधरे महावृषभवाहिनि।\nमाहेश्वरीस्वरूपेण नारायणि नमोऽस्तु ते॥","r":"Trishulachandrahidhare mahavrishabhavahini,\nMaheshvarisvarupena Narayani namo’stu te.","m":"You who in the form of Maheshwari bear the trident, the moon and the serpent and ride the great bull: Narayani, I bow to you.","h":"माहेश्वरी के रूप में त्रिशूल, चन्द्रमा और सर्प धारण करने वाली तथा महान वृषभ पर सवार होने वाली हे नारायणी, आपको नमस्कार है।","n":"११.१४"},{"d":"मयूरकुक्कुटवृते महाशक्तिधरेऽनघे।\nकौमारीरूपसंस्थाने नारायणि नमोऽस्तु ते॥","r":"Mayurakukkutavrite mahashaktidhare’naghe,\nKaumarirupasansthane Narayani namo’stu te.","m":"Sinless one, attended by peacocks and cockerels and bearing the great spear, in the form of Kaumari: Narayani, I bow to you.","h":"मोरों और मुर्गों से घिरी रहने वाली, महाशक्ति (भाला) धारण करने वाली, निष्पाप, कौमारी रूप में स्थित हे नारायणी, आपको नमस्कार है।","n":"११.१५"},{"d":"शङ्खचक्रगदाशार्ङ्गगृहीतपरमायुधे।\nप्रसीद वैष्णवीरूपे नारायणि नमोऽस्तु ते॥","r":"Shankhachakragadashargagrihitaparamayudhe,\nPrasida Vaishnavirupe Narayani namo’stu te.","m":"You who hold the supreme weapons, the conch, the discus, the mace and the Sharnga bow, in the form of Vaishnavi, be gracious: Narayani, I bow to you.","h":"शंख, चक्र, गदा और शार्ङ्ग धनुष जैसे उत्तम आयुध धारण करने वाली वैष्णवी रूपा हे नारायणी, प्रसन्न होइए, आपको नमस्कार है।","n":"११.१६"},{"d":"गृहीतोग्रमहाचक्रे दंष्ट्रोद्धृतवसुन्धरे।\nवराहरूपिणि शिवे नारायणि नमोऽस्तु ते॥","r":"Grihitogramahachakre danshtroddhritavasundhare,\nVaraharupini Shive Narayani namo’stu te.","m":"Gracious one in the form of the Boar, holding the fierce great discus and lifting the earth on your tusk: Narayani, I bow to you.","h":"भयंकर महाचक्र धारण करने वाली और अपनी दाढ़ों पर पृथ्वी को उठाने वाली, वाराही रूप वाली कल्याणमयी हे नारायणी, आपको नमस्कार है।","n":"११.१७"},{"d":"नृसिंहरूपेणोग्रेण हन्तुं दैत्यान् कृतोद्यमे।\nत्रैलोक्यत्राणसहिते नारायणि नमोऽस्तु ते॥","r":"Nrisimharupenogrena hantum daityan kritodyame,\nTrailokyatranasahite Narayani namo’stu te.","m":"You who in the fierce form of the Man-Lion set out to slay the demons, protector of the three worlds: Narayani, I bow to you.","h":"भयंकर नृसिंह रूप से दैत्यों को मारने के लिए उद्यत होने वाली और तीनों लोकों की रक्षा करने वाली हे नारायणी, आपको नमस्कार है।","n":"११.१८"},{"d":"किरीटिनि महावज्रे सहस्रनयनोज्ज्वले।\nवृत्रप्राणहरे चैन्द्रि नारायणि नमोऽस्तु ते॥","r":"Kiritini mahavajre sahasranayanojjvale,\nVritrapranahare chaindri Narayani namo’stu te.","m":"Crowned Aindri, wielder of the great thunderbolt, shining with a thousand eyes, who took the life of Vritra: Narayani, I bow to you.","h":"मुकुट धारण करने वाली, महावज्र धारण करने वाली, हजार नेत्रों से दमकने वाली और वृत्रासुर के प्राण हरने वाली ऐन्द्री रूपा हे नारायणी, आपको नमस्कार है।","n":"११.१९"},{"d":"शिवदूतीस्वरूपेण हतदैत्यमहाबले।\nघोररूपे महारावे नारायणि नमोऽस्तु ते॥","r":"Shivadutisvarupena hatadaityamahabale,\nGhorarupe maharave Narayani namo’stu te.","m":"You who as Shivaduti destroyed the mighty armies of the demons, terrible in form and thundering aloud: Narayani, I bow to you.","h":"शिवदूती रूप से दैत्यों की महान सेना का संहार करने वाली, भयंकर रूप वाली और महान गर्जना करने वाली हे नारायणी, आपको नमस्कार है।","n":"११.२०"},{"d":"दंष्ट्राकरालवदने शिरोमालाविभूषणे।\nचामुण्डे मुण्डमथने नारायणि नमोऽस्तु ते॥","r":"Danshtrakaralavadane shiromalavibhushane,\nChamunde mundamathane Narayani namo’stu te.","m":"Chamunda, slayer of Mund, whose face is fearsome with fangs and who is adorned with a garland of heads: Narayani, I bow to you.","h":"दाढ़ों के कारण विकराल मुख वाली, मुण्डमाला से विभूषित, मुण्ड का मर्दन करने वाली हे चामुण्डा, हे नारायणी, आपको नमस्कार है।","n":"११.२१"},{"d":"लक्ष्मि लज्जे महाविद्ये श्रद्धे पुष्टि स्वधे ध्रुवे।\nमहारात्रि महाऽविद्ये नारायणि नमोऽस्तु ते॥","r":"Lakshmi lajje mahavidye shraddhe pushti svadhe dhruve,\nMaharatri maha’vidye Narayani namo’stu te.","m":"You are Lakshmi, modesty, the great knowledge, faith, nourishment, Svadha and the unchanging; the great night and the great ignorance: Narayani, I bow to you.","h":"हे लक्ष्मी, लज्जा, महाविद्या, श्रद्धा, पुष्टि, स्वधा, ध्रुवा, महारात्रि और महा-अविद्या रूपा नारायणी, आपको नमस्कार है।","n":"११.२२"},{"d":"मेधे सरस्वति वरे भूति बाभ्रवि तामसि।\nनियते त्वं प्रसीदेशे नारायणि नमोऽस्तु ते॥","r":"Medhe Sarasvati vare bhuti babhravi tamasi,\nNiyate tvam prasideshe Narayani namo’stu te.","m":"You are intelligence and Saraswati, the best, prosperity, the tawny one and the dark one; you are the order of things. Be gracious, ruler of all: Narayani, I bow to you.","h":"हे मेधा, सरस्वती, श्रेष्ठा, विभूति, बाभ्रवी (पार्वती) और तामसी, हे नियति रूपा ईश्वरी, आप प्रसन्न होइए। हे नारायणी, आपको नमस्कार है।","n":"११.२३"},{"d":"सर्वस्वरूपे सर्वेशे सर्वशक्तिसमन्विते।\nभयेभ्यस्त्राहि नो देवि दुर्गे देवि नमोऽस्तु ते॥","r":"Sarvasvarupe sarveshe sarvashaktisamanvite,\nBhayebhyastrahi no devi Durge devi namo’stu te.","m":"You who are everything, ruler of all, possessed of every power: Goddess, save us from all fears. Goddess Durga, I bow to you.","h":"हे सर्वस्वरूपा, सर्वेश्वरी, सब शक्तियों से सम्पन्न देवी, भयों से हमारी रक्षा कीजिए। हे दुर्गा देवी, आपको नमस्कार है।","n":"११.२४"},{"d":"एतत्ते वदनं सौम्यं लोचनत्रयभूषितम्।\nपातु नः सर्वभीतिभ्यः कात्यायनि नमोऽस्तु ते॥","r":"Etatte vadanam saumyam lochanatrayabhushitam,\nPatu nah sarvabhitibhyah Katyayani namo’stu te.","m":"May this gentle face of yours, adorned with three eyes, protect us from every fear. Katyayani, I bow to you.","h":"तीन नेत्रों से सुशोभित आपका यह सौम्य मुख सब भयों से हमारी रक्षा करे। हे कात्यायनी, आपको नमस्कार है।","n":"११.२५"},{"d":"ज्वालाकरालमत्युग्रमशेषासुरसूदनम्।\nत्रिशूलं पातु नो भीतेर्भद्रकालि नमोऽस्तु ते॥","r":"Jvalakaralamatyugramasheshasurasudanam,\nTrishulam patu no bhiterbhadrakali namo’stu te.","m":"May your trident, fearsome with flames, exceedingly fierce, destroyer of every demon, protect us from fear. Bhadrakali, I bow to you.","h":"ज्वालाओं से विकराल, अत्यन्त उग्र और सब असुरों का नाश करने वाला आपका त्रिशूल हमें भय से बचाए। हे भद्रकाली, आपको नमस्कार है।","n":"११.२६"},{"d":"हिनस्ति दैत्यतेजांसि स्वनेनापूर्य या जगत्।\nसा घण्टा पातु नो देवि पापेभ्योऽनः सुतानिव॥","r":"Hinasti daityatejansi svanenapurya ya jagat,\nSa ghanta patu no devi papebhyo’nah sutaniva.","m":"Goddess, may your bell, which fills the world with its sound and destroys the might of the demons, protect us from sin as a mother protects her children.","h":"हे देवी, जो अपनी ध्वनि से जगत को भरकर दैत्यों के तेज को नष्ट कर देता है, वह आपका घण्टा हमारी पापों से वैसे ही रक्षा करे, जैसे माता अपने पुत्रों की करती है।","n":"११.२७"},{"d":"असुरासृग्वसापङ्कचर्चितस्ते करोज्ज्वलः।\nशुभाय खड्गो भवतु चण्डिके त्वां नता वयम्॥","r":"Asurasrigvasapankacharchitaste karojjvalah,\nShubhaya khadgo bhavatu Chandike tvam nata vayam.","m":"May your sword, smeared with the blood and fat of demons and shining in your hand, be for our good. Chandika, we bow to you.","h":"असुरों के रक्त और चर्बी के कीचड़ से सना हुआ, आपके हाथ में चमकने वाला खड्ग हमारा कल्याण करे। हे चण्डिका, हम आपको प्रणाम करते हैं।","n":"११.२८"},{"d":"रोगानशेषानपहंसि तुष्टा रुष्टा तु कामान् सकलानभीष्टान्।\nत्वामाश्रितानां न विपन्नराणां त्वामाश्रिता ह्याश्रयतां प्रयान्ति॥","r":"Roganasheshanapahansi tushta rushta tu kaman sakalanabhishtan,\nTvamashritanam na vipannaranam tvamashrita hyashrayatam prayanti.","m":"When pleased you destroy every illness, and when angered you take away every cherished desire. Those who take refuge in you meet no misfortune; indeed, those who take refuge in you become a refuge for others.","h":"आप प्रसन्न होने पर सब रोगों को नष्ट कर देती हैं और कुपित होने पर सारी मनचाही कामनाओं को नष्ट कर देती हैं। जो आपकी शरण में हैं, उन पर विपत्ति नहीं आती; आपकी शरण में गए हुए लोग दूसरों को भी शरण देने वाले बन जाते हैं।","n":"११.२९"},{"d":"एतत्कृतं यत्कदनं त्वयाद्य धर्मद्विषां देवि महासुराणाम्।\nरूपैरनेकैर्बहुधाऽऽत्ममूर्तिं कृत्वाम्बिके तत्प्रकरोति कान्या॥","r":"Etatkritam yatkadanam tvayadya dharmadvisham devi mahasuranam,\nRupairanekairbahudha’tmamurtim kritvambike tatprakaroti kanya.","m":"Goddess, the slaughter you have made today of the great demons who hated dharma, by dividing your own form into many shapes, Ambika: who else could have done it?","h":"हे देवी, आज आपने अपने स्वरूप को अनेक रूपों में बाँटकर धर्म से द्वेष करने वाले महान असुरों का जो संहार किया है, हे अम्बिका, उसे और कौन कर सकता है?","n":"११.३०"},{"d":"विद्यासु शास्त्रेषु विवेकदीपेष्वाद्येषु वाक्येषु च का त्वदन्या।\nममत्वगर्तेऽतिमहान्धकारे विभ्रामयत्येतदतीव विश्वम्॥","r":"Vidyasu shastreshu vivekadipeshvadyeshu vakyeshu cha ka tvadanya,\nMamatvagarte’timahandhakare vibhramayatyetadativa vishvam.","m":"Who but you is present in the sciences, in the scriptures that light the lamp of discernment, and in the ancient words of the Vedas? And who but you whirls this whole world about in the deep, dark pit of possessiveness?","h":"विद्याओं में, ज्ञान का दीपक जलाने वाले शास्त्रों में और आदि वाक्यों (वेदों) में आपके सिवा और कौन है? और आपके सिवा और कौन इस विश्व को ममता के अत्यन्त अँधेरे गड्ढे में भटकाता है?","n":"११.३१"},{"d":"रक्षांसि यत्रोग्रविषाश्च नागा यत्रारयो दस्युबलानि यत्र।\nदवानलो यत्र तथाब्धिमध्ये तत्र स्थिता त्वं परिपासि विश्वम्॥","r":"Rakshansi yatrogravishashcha naga yatrarayo dasyubalani yatra,\nDavanalo yatra tathabdhimadhye tatra sthita tvam paripasi vishvam.","m":"Wherever there are demons, serpents of deadly venom, enemies or bands of robbers, wherever there is a forest fire, and in the middle of the ocean: there you stand and protect the world.","h":"जहाँ राक्षस हों, भयंकर विष वाले सर्प हों, शत्रु हों, लुटेरों की सेनाएँ हों, जहाँ दावानल हो और समुद्र के बीच में भी, वहाँ स्थित होकर आप विश्व की रक्षा करती हैं।","n":"११.३२"},{"d":"विश्वेश्वरि त्वं परिपासि विश्वं विश्वात्मिका धारयसीति विश्वम्।\nविश्वेशवन्द्या भवती भवन्ति विश्वाश्रया ये त्वयि भक्तिनम्राः॥","r":"Vishveshvari tvam paripasi vishvam vishvatmika dharayasiti vishvam,\nVishveshavandya bhavati bhavanti vishvashraya ye tvayi bhaktinamrah.","m":"Ruler of the universe, you protect the universe; as its very self you uphold the universe. You are worshipped by the lord of the universe, and those who bow to you in devotion become the refuge of the universe.","h":"हे विश्वेश्वरी, आप विश्व की रक्षा करती हैं; विश्वरूपा होने से आप विश्व को धारण करती हैं। आप विश्व के स्वामी (शिव) द्वारा भी वन्दनीय हैं, और जो आपके प्रति भक्ति से झुके रहते हैं, वे विश्व को आश्रय देने वाले बन जाते हैं।","n":"११.३३"},{"d":"देवि प्रसीद परिपालय नोऽरिभीतेर्नित्यं यथासुरवधादधुनैव सद्यः।\nपापानि सर्वजगतां प्रशमं नयाशु उत्पातपाकजनितांश्च महोपसर्गान्॥","r":"Devi prasida paripalaya no’ribhiternityam yathasuravadhadadhunaiva sadyah,\nPapani sarvajagatam prashamam nayashu utpatapakajanitanshcha mahopasargan.","m":"Goddess, be gracious, and always protect us from the fear of enemies, just as you have saved us now by slaying the demons. Swiftly bring to rest the sins of all the worlds and the great calamities born of evil omens.","h":"हे देवी, प्रसन्न होइए। जैसे आपने अभी असुरों का वध करके तुरन्त हमारी रक्षा की है, वैसे ही सदा शत्रुओं के भय से हमारी रक्षा कीजिए। सारे जगत के पापों को और उत्पातों के फल से होने वाले बड़े उपद्रवों को शीघ्र शान्त कीजिए।","n":"११.३४"},{"d":"प्रणतानां प्रसीद त्वं देवि विश्वार्तिहारिणि।\nत्रैलोक्यवासिनामीड्ये लोकानां वरदा भव॥","r":"Pranatanam prasida tvam devi vishvartiharini,\nTrailokyavasinamidye lokanam varada bhava.","m":"Goddess who takes away the suffering of the world, be gracious to us who bow before you. Worshipped by all who live in the three worlds, grant boons to all the worlds.","h":"हे विश्व की पीड़ा हरने वाली देवी, आपको प्रणाम करने वाले हम पर प्रसन्न होइए। हे तीनों लोकों के निवासियों द्वारा पूजनीय, सब लोकों को वर देने वाली बनिए।","n":"११.३५"},{"d":"वरदाहं सुरगणा वरं यन्मनसेच्छथ।\nतं वृणुध्वं प्रयच्छामि जगतामुपकारकम्॥","r":"Varadaham suragana varam yanmanasechchhatha,\nTam vrinudhvam prayachchhami jagatamupakarakam.","m":"Gods, I am ready to grant a boon. Choose whatever boon your hearts desire that will benefit the worlds, and I will give it.","h":"हे देवताओ, मैं वर देने को तैयार हूँ। तुम्हारे मन में जो वर हो, जो जगत का उपकार करने वाला हो, वह माँग लो; मैं उसे दूँगी।","n":"११.३७","sp":{"d":"देव्युवाच","r":"The Goddess said","no":36}},{"d":"सर्वाबाधाप्रशमनं त्रैलोक्यस्याखिलेश्वरि।\nएवमेव त्वया कार्यमस्मद्वैरिविनाशनम्॥","r":"Sarvabadhaprashamanam trailokyasyakhileshvari,\nEvameva tvaya karyamasmadvairivinashanam.","m":"Ruler of all, in just this way please calm every trouble of the three worlds and destroy our enemies.","h":"हे सर्वेश्वरी, आप इसी प्रकार तीनों लोकों की सब बाधाओं को शान्त करें और हमारे शत्रुओं का नाश करती रहें।","n":"११.३९","sp":{"d":"देवा ऊचुः","r":"The gods said","no":38}},{"d":"वैवस्वतेऽन्तरे प्राप्ते अष्टाविंशतिमे युगे।\nशुम्भो निशुम्भश्चैवान्यावुत्पत्स्येते महासुरौ॥","r":"Vaivasvate’ntare prapte ashtavinshatime yuge,\nShumbho Nishumbhashchaivanyavutpatsyete mahasurau.","m":"In the age of the Manu Vaivasvat, in the twenty-eighth cycle of ages, two other great demons named Shumbh and Nishumbh will be born.","h":"वैवस्वत मन्वन्तर के अट्ठाईसवें युग में शुम्भ और निशुम्भ नाम के दो दूसरे महान असुर उत्पन्न होंगे।","n":"११.४१","sp":{"d":"देव्युवाच","r":"The Goddess said","no":40}},{"d":"नन्दगोपगृहे जाता यशोदागर्भसम्भवा।\nततस्तौ नाशयिष्यामि विन्ध्याचलनिवासिनी॥","r":"Nandagopagrihe jata Yashodagarbhasambhava,\nTatastau nashayishyami Vindhyachalanivasini.","m":"Then I will be born in the house of Nand the cowherd, from the womb of Yashoda, and dwelling on the Vindhya mountains I will destroy them both.","h":"तब मैं नन्द गोप के घर में यशोदा के गर्भ से जन्म लूँगी और विन्ध्याचल पर निवास करके उन दोनों का नाश करूँगी।","n":"११.४२"},{"d":"पुनरप्यतिरौद्रेण रूपेण पृथिवीतले।\nअवतीर्य हनिष्यामि वैप्रचित्तांस्तु दानवान्॥","r":"Punarapyatiraudrena rupena prithivitale,\nAvatirya hanishyami vaiprachittanstu danavan.","m":"Again, descending to the earth in an exceedingly fierce form, I will slay the demons descended from Viprachitti.","h":"फिर पृथ्वी पर अत्यन्त भयंकर रूप में अवतार लेकर मैं विप्रचित्ति के वंशज दानवों का वध करूँगी।","n":"११.४३"},{"d":"भक्षयन्त्याश्च तानुग्रान् वैप्रचित्तान्महासुरान्।\nरक्ता दन्ता भविष्यन्ति दाडिमीकुसुमोपमाः॥","r":"Bhakshayantyashcha tanugran vaiprachittanmahasuran,\nRakta danta bhavishyanti dadimikusumopamah.","m":"As I devour those fierce great demons of Viprachitti’s line, my teeth will turn red like pomegranate flowers.","h":"उन भयंकर वैप्रचित्त महासुरों का भक्षण करते समय मेरे दाँत अनार के फूल की तरह लाल हो जाएँगे।","n":"११.४४"},{"d":"ततो मां देवताः स्वर्गे मर्त्यलोके च मानवाः।\nस्तुवन्तो व्याहरिष्यन्ति सततं रक्तदन्तिकाम्॥","r":"Tato mam devatah svarge martyaloke cha manavah,\nStuvanto vyaharishyanti satatam Raktadantikam.","m":"Then the gods in heaven and people on earth, praising me, will always call me Raktadantika, the red-toothed one.","h":"तब स्वर्ग में देवता और पृथ्वी पर मनुष्य मेरी स्तुति करते हुए मुझे सदा रक्तदन्तिका कहेंगे।","n":"११.४५"},{"d":"भूयश्च शतवार्षिक्यामनावृष्ट्यामनम्भसि।\nमुनिभिः संस्तुता भूमौ सम्भविष्याम्ययोनिजा॥","r":"Bhuyashcha shatavarshikyamanavrishtyamanambhasi,\nMunibhih sanstuta bhumau sambhavishyamyayonija.","m":"And again, when there has been no rain for a hundred years and the earth is without water, praised by the sages I will appear on earth, not born of any womb.","h":"फिर जब सौ वर्षों तक वर्षा न होगी और पृथ्वी जल से रहित हो जाएगी, तब मुनियों की स्तुति से मैं बिना गर्भ के पृथ्वी पर प्रकट होऊँगी।","n":"११.४६"},{"d":"ततः शतेन नेत्राणां निरीक्षिष्यामि यन्मुनीन्।\nकीर्तयिष्यन्ति मनुजाः शताक्षीमिति मां ततः॥","r":"Tatah shatena netranam nirikshishyami yanmunin,\nKirtayishyanti manujah Shatakshimiti mam tatah.","m":"Because I will then look upon the sages with a hundred eyes, people will praise me as Shatakshi, the hundred-eyed.","h":"तब मैं सौ नेत्रों से मुनियों को देखूँगी, इसलिए मनुष्य मुझे शताक्षी नाम से पुकारेंगे।","n":"११.४७"},{"d":"ततोऽहमखिलं लोकमात्मदेहसमुद्भवैः।\nभरिष्यामि सुराः शाकैरावृष्टेः प्राणधारकैः॥","r":"Tato’hamakhilam lokamatmadehasamudbhavaih,\nBharishyami surah shakairavrishteh pranadharakaih.","m":"Then, gods, until the rains return I will feed the whole world with life-giving vegetables grown from my own body.","h":"हे देवताओ, तब जब तक वर्षा न होगी, तब तक मैं अपने शरीर से उत्पन्न हुए, प्राणों की रक्षा करने वाले शाकों से सारे संसार का भरण-पोषण करूँगी।","n":"११.४८"},{"d":"शाकम्भरीति विख्यातिं तदा यास्याम्यहं भुवि।\nतत्रैव च वधिष्यामि दुर्गमाख्यं महासुरम्॥","r":"Shakambhariti vikhyatim tada yasyamyaham bhuvi,\nTatraiva cha vadhishyami Durgamakhyam mahasuram.","m":"Then I will become famous on earth as Shakambhari, and in that same age I will slay the great demon named Durgam.","h":"तब मैं पृथ्वी पर शाकम्भरी नाम से विख्यात होऊँगी, और उसी समय दुर्गम नामक महान असुर का वध करूँगी।","n":"११.४९"},{"d":"दुर्गा देवीति विख्यातं तन्मे नाम भविष्यति।\nपुनश्चाहं यदा भीमं रूपं कृत्वा हिमाचले॥","r":"Durga Deviti vikhyatam tanme nama bhavishyati,\nPunashchaham yada bhimam rupam kritva Himachale.","m":"From that I will be known by the name Durga Devi. And again, when I take a terrible form on the Himalaya,","h":"इससे मेरा नाम दुर्गा देवी प्रसिद्ध होगा। फिर जब मैं हिमालय पर भयंकर रूप धारण करके,","n":"११.५०"},{"d":"रक्षांसि भक्षयिष्यामि मुनीनां त्राणकारणात्।\nतदा मां मुनयः सर्वे स्तोष्यन्त्यानम्रमूर्तयः॥","r":"Rakshansi bhakshayishyami muninam tranakaranat,\nTada mam munayah sarve stoshyantyanamramurtayah.","m":"and devour the demons to protect the sages, all the sages will bow low and praise me.","h":"मुनियों की रक्षा के लिए राक्षसों का भक्षण करूँगी, तब सब मुनि झुककर मेरी स्तुति करेंगे।","n":"११.५१"},{"d":"भीमा देवीति विख्यातं तन्मे नाम भविष्यति।\nयदारुणाख्यस्त्रैलोक्ये महाबाधां करिष्यति॥","r":"Bhima Deviti vikhyatam tanme nama bhavishyati,\nYadarunakhyastrailokye mahabadham karishyati.","m":"Then my name will be famed as Bhima Devi. When the demon named Aruna brings great distress on the three worlds,","h":"तब मेरा नाम भीमा देवी प्रसिद्ध होगा। जब अरुण नामक असुर तीनों लोकों में बड़ा उपद्रव करेगा,","n":"११.५२"},{"d":"तदाहं भ्रामरं रूपं कृत्वासंख्येयषट्पदम्।\nत्रैलोक्यस्य हितार्थाय वधिष्यामि महासुरम्॥","r":"Tadaham bhramaram rupam kritvasankhyeyashatpadam,\nTrailokyasya hitarthaya vadhishyami mahasuram.","m":"then I will take the form of countless bees, and for the good of the three worlds I will slay that great demon.","h":"तब मैं असंख्य भौंरों वाला भ्रामर रूप धारण करके तीनों लोकों के हित के लिए उस महान असुर का वध करूँगी।","n":"११.५३"},{"d":"भ्रामरीति च मां लोकास्तदा स्तोष्यन्ति सर्वतः।\nइत्थं यदा यदा बाधा दानवोत्था भविष्यति॥","r":"Bhramariti cha mam lokastada stoshyanti sarvatah,\nIttham yada yada badha danavottha bhavishyati.","m":"Then people everywhere will praise me as Bhramari. In this way, whenever trouble arises from the demons,","h":"तब सब ओर लोग मुझे भ्रामरी कहकर मेरी स्तुति करेंगे। इस प्रकार जब-जब दानवों के कारण बाधा उपस्थित होगी,","n":"११.५४"},{"d":"तदा तदावतीर्याहं करिष्याम्यरिसंक्षयम्॥","r":"Tada tadavatiryaham karishyamyarisankshayam.","m":"then I will descend and destroy the enemies.","h":"तब-तब मैं अवतार लेकर शत्रुओं का संहार करूँगी।","n":"११.५५"}],"intro":"Shumbh is dead and the worlds are at peace. The gods, led by Agni, praise the Goddess as Narayani, and she promises to return whenever the world needs her. Verses 3 to 35 are the Narayani Stuti, recited on its own in many homes."},{"n":12,"d":"फलस्तुति","r":"Phalastuti","en":"The blessings of reciting this text","count":41,"sum":"The Goddess tells the gods what reciting her story brings: protection from enemies, fire, water, illness and bad dreams, peace in the home and the growth of the family. Reading it on the eighth, ninth and fourteenth days of the fortnight, and in the great autumn worship each year, pleases her especially. She then vanishes, and the sage sums up how she protects the world."},{"n":13,"d":"सुरथवैश्ययोर्वरप्रदान","r":"Surath Vaishya Var Pradan","en":"Boons for King Suratha and the merchant","count":29,"sum":"Hearing the story, Suratha and Samadhi go to a riverbank and worship the Goddess for three years with images of clay. She appears. Suratha asks for his kingdom back in this life and a kingdom that cannot be lost in the next, and is promised that he will be reborn as Savarni, the eighth Manu. The merchant, now free of attachment, asks for the knowledge that ends all clinging, and is granted it."}]}]};
